export const purchaseService = {
  /**
   * Check if user has access to a specific ai-design-studio
   */
  async checkUserHasAccess(userId: string, appSlug: string): Promise<boolean> {
    try {
      const { data, error } = await supabase
        .from("user_app_access")
        .select("*")
        .eq("user_id", userId)
        .eq("app_slug", appSlug)
        .eq("is_active", true)
        .maybeSingle();

      if (error) {
        console.error("Error checking user access:", error);
        return false;
      }

      if (!data) {
        return false;
      }

      if (data.expires_at) {
        const expiresAt = new Date(data.expires_at);
        const now = new Date();
        return expiresAt > now;
      }

      return true;
    } catch (error) {
      console.error("Error in checkUserHasAccess:", error);
      return false;
    }
  },

  /**
   * Get all apps the user has purchased/access to
   */
  async getUserPurchasedApps(userId: string): Promise<string[]> {
    try {
      // Get direct ai-design-studio access
      const { data: directAccess, error: directError } = await supabase
        .from("user_app_access")
        .select("app_slug")
        .eq("user_id", userId)
        .eq("is_active", true);

      if (directError) {
        console.error("Error fetching user direct ai-design-studio access:", directError);
      }

      // Check for bundle purchases
      const { data: bundlePurchases, error: bundleError } = await supabase
        .from("purchases")
        .select("product_id, metadata")
        .eq("user_id", userId)
        .eq("status", "completed")
        .or("product_id.eq.all-apps-bundle,metadata->>isBundle.eq.true");

      if (bundleError) {
        console.error("Error fetching bundle purchases:", bundleError);
      }

      const appSlugs = [];

      // Add directly purchased apps
      if (directAccess) {
        const directApps = directAccess
          .filter((access) => {
            if (access.expires_at) {
              const expiresAt = new Date(access.expires_at);
              const now = new Date();
              return expiresAt > now;
            }
            return true;
          })
          .map((access) => access.app_slug);
        appSlugs.push(...directApps);
      }

      // Add bundle access - all LLM agent apps
      if (bundlePurchases && bundlePurchases.length > 0) {
        // Import the ai-design-studio bundling utility dynamically to avoid circular imports
        const { CONVERTED_LLM_AGENT_APPS } = await import("../utils/appBundling");
        appSlugs.push(...CONVERTED_LLM_AGENT_APPS);
      }

      // Remove duplicates
      return [...new Set(appSlugs)];
    } catch (error) {
      console.error("Error in getUserPurchasedApps:", error);
      return [];
    }
  },

  /**
   * Get full user ai-design-studio access details
   */
  async getUserAppAccessDetails(userId: string): Promise<UserAppAccess[]> {
    try {
      const { data, error } = await supabase
        .from("user_app_access")
        .select("*")
        .eq("user_id", userId)
        .eq("is_active", true)
        .order("granted_at", { ascending: false });

      if (error) {
        console.error("Error fetching user ai-design-studio access details:", error);
        return [];
      }

      return (data as UserAppAccess[]) || [];
    } catch (error) {
      console.error("Error in getUserAppAccessDetails:", error);
      return [];
    }
  },

  /**
   * Get all user purchases
   */
  async getAllUserPurchases(userId: string): Promise<Purchase[]> {
    try {
      const { data, error } = await supabase
        .from("purchases")
        .select("*")
        .eq("user_id", userId)
        .order("purchase_date", { ascending: false });

      if (error) {
        console.error("Error fetching user purchases:", error);
        return [];
      }

      return (data as Purchase[]) || [];
    } catch (error) {
      console.error("Error in getAllUserPurchases:", error);
      return [];
    }
  },

  /**
   * Get purchase by email (for users who purchased before signing up)
   */
  async getPurchasesByEmail(email: string): Promise<Purchase[]> {
    try {
      const { data, error } = await supabase
        .from("purchases")
        .select("*")
        .eq("email", email.toLowerCase())
        .order("purchase_date", { ascending: false });

      if (error) {
        console.error("Error fetching purchases by email:", error);
        return [];
      }

      return (data as Purchase[]) || [];
    } catch (error) {
      console.error("Error in getPurchasesByEmail:", error);
      return [];
    }
  },

  /**
   * Record a new purchase and grant ai-design-studio access
   * Uses safeMutation to prevent duplicate purchases
   * 
   * NOTE: The idempotency implementation uses client-side caching which helps prevent
   * duplicates within the same browser session (e.g., rapid clicks). For complete
   * duplicate prevention across sessions/browsers, consider adding a unique constraint
   * on the purchases table for (platform, platform_transaction_id) and handling
   * the unique constraint violation error appropriately.
   */
  async recordPurchase(
    userId: string | null,
    email: string,
    platform: string,
    platformTransactionId: string,
    productName: string,
    amount: number,
    currency: string,
    appSlugs: string[],
    stripeData?: {
      paymentIntentId?: string;
      invoiceId?: string;
      customerId?: string;
    },
  ): Promise<{ success: boolean; error?: string; isDuplicate?: boolean }> {
    // Create idempotency key based on transaction ID to prevent duplicates
    const idempotencyKey = createPurchaseIdempotencyKey(
      userId || 'anonymous',
      platformTransactionId,
      platform
    );

    const result = await safeMutation(
      async () => {
        const purchaseData = {
          user_id: userId,
          email: email.toLowerCase(),
          platform,
          platform_transaction_id: platformTransactionId,
          product_name: productName,
          amount,
          currency,
          status: "completed" as const,
          purchase_date: new Date().toISOString(),
        };

        // Add stripe data if provided
        if (stripeData) {
          Object.assign(purchaseData, {
            stripe_payment_intent_id: stripeData.paymentIntentId,
            stripe_invoice_id: stripeData.invoiceId,
            stripe_customer_id: stripeData.customerId,
          });
        }

        const { data: purchase, error: purchaseError } = await supabase
          .from("purchases")
          .insert(purchaseData)
          .select()
          .single();

        if (purchaseError) {
          // Check for duplicate key errors
          if (purchaseError.message.includes('duplicate key') || 
              purchaseError.message.includes('unique constraint')) {
            console.log("[recordPurchase] Duplicate purchase detected:", platformTransactionId);
            return { duplicate: true, purchase: null };
          }
          throw purchaseError;
        }

        // Grant ai-design-studio access if userId and appSlugs provided
        if (userId && appSlugs.length > 0 && purchase) {
          const accessRecords = appSlugs.map((appSlug) => ({
            user_id: userId,
            app_slug: appSlug,
            purchase_id: purchase.id,
            access_type: "lifetime" as const,
            is_active: true,
          }));

          const { error: accessError } = await supabase
            .from("user_app_access")
            .insert(accessRecords);

          if (accessError) {
            console.error("Error granting ai-design-studio access:", accessError);
            throw accessError;
          }
        }

        return { duplicate: false, purchase };
      },
      {
        table: 'purchases',
        idempotencyKey,
        retryConfig: {
          maxAttempts: 3,
          baseDelayMs: 500,
          maxDelayMs: 5000,
          backoffFactor: 2,
        },
      }
    );

    if (result.success) {
      return { success: true };
    }

    return {
      success: false,
      error: result.error,
      isDuplicate: result.isDuplicate,
    };
  },

  /**
   * Grant ai-design-studio access to a user (for admin use or post-purchase processing)
   */
  async grantAppAccess(
    userId: string,
    appSlugs: string[],
    accessType: "subscription" | "lifetime" | "trial" = "lifetime",
    purchaseId?: string,
    expiresAt?: Date,
  ): Promise<{ success: boolean; error?: string }> {
    try {
      const accessRecords = appSlugs.map((appSlug) => ({
        user_id: userId,
        app_slug: appSlug,
        purchase_id: purchaseId,
        access_type: accessType,
        expires_at: expiresAt?.toISOString(),
        is_active: true,
      }));

      const { error } = await supabase
        .from("user_app_access")
        .insert(accessRecords);

      if (error) {
        console.error("Error granting ai-design-studio access:", error);
        return { success: false, error: error.message };
      }

      return { success: true };
    } catch (error: any) {
      console.error("Error in grantAppAccess:", error);
      return { success: false, error: error.message };
