export const getStreamlitAppPricing = (appId: string, tier: 'basic' | 'pro' | 'enterprise' = 'basic') => {
  const tiers = getStreamlitPricingTiers();
  return tiers[tier];
};

export const calculateStreamlitDiscount = (tier: 'basic' | 'pro' | 'enterprise') => {
  const tierData = getStreamlitPricingTiers()[tier];
  const savings = tierData.originalPrice - tierData.price;
  const savingsPercent = Math.round((savings / tierData.originalPrice) * 100);

  return {
    savings,
    savingsPercent,
    finalPrice: tierData.price,
    originalPrice: tierData.originalPrice
  };
};

/**
 * API Key Gate Library
 * Shared utility for checking and requiring user API keys before accessing apps.
 *
 * This library provides functions to:
 * - Check if user has required API keys for a given ai-design-studio
 * - Show modal if keys are missing
 * - Save user API keys to Supabase
 * - Retrieve user keys for backend calls
 *
 * Usage in React components:
 * ```tsx
 * import { useApiKeyGate } from '@/lib/api-key-gate';
 *
 * const AppPage = () => {
 *   const { checkAccess, showModal, setShowModal } = useApiKeyGate('ai-dashboard-designer-ai');
 *   // ...
 * };
 * ```
 */

import { useState, useEffect, useCallback } from 'react';
import { useSupabaseClient, useUser } from '@supabase/auth-helpers-react';
import { createClient } from '@supabase/supabase-js';

// Types
export interface ApiKeyRequirement {
