// Simple encryption for client-side (optional enhancement)
// In production, use more robust encryption or rely on Supabase RLS
async function encryptKey(key: string): Promise<string> {
  // For simplicity, we'll send plaintext and rely on HTTPS + RLS
  // Future: use Web Crypto API to encrypt before send
  return key;
}

// Fetch required providers for an ai-design-studio from Supabase
async function fetchAppRequirements(supabase: any, appId: string): Promise<string[]> {
  const { data, error } = await supabase
    .from('app_api_requirements')
    .select('required_providers')
    .eq('app_id', appId)
    .single();

  if (error || !data) {
    console.warn(`No API requirements found for ai-design-studio: ${appId}`);
    return [];
  }

  return data.required_providers || [];
}

// Fetch user's API keys from Supabase
async function fetchUserApiKeys(supabase: any): Promise<Record<string, string>> {
  const { data, error } = await supabase
    .from('user_api_keys')
    .select('provider, encrypted_api_key')
    .eq('user_id', (await supabase.auth.getUser()).data.user?.id);

  if (error || !data) {
    return {};
  }

  const keys: Record<string, string> = {};
  data.forEach((item: { provider: string; encrypted_api_key: string }) => {
    keys[item.provider] = item.encrypted_api_key;
  });
  return keys;
}

// Save user API key (upsert)
export async function saveUserApiKey(
  supabase: any,
  provider: string,
  key: string
): Promise<boolean> {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('Not authenticated');

  const encryptedKey = await encryptKey(key);

  const { error } = await supabase
    .from('user_api_keys')
    .upsert({
      user_id: user.id,
      provider,
      encrypted_api_key: encryptedKey,
      updated_at: new Date().toISOString(),
    });

  if (error) {
    console.error('Failed to save API key:', error);
    return false;
  }

  return true;
}

// Get user's API key for a provider
export async function getUserApiKey(supabase: any, provider: string): Promise<string | null> {
  const { data, error } = await supabase
    .from('user_api_keys')
    .select('encrypted_api_key')
    .eq('user_id', (await supabase.auth.getUser()).data.user?.id)
    .eq('provider', provider)
    .single();

  if (error || !data) {
    return null;
  }

  return data.encrypted_api_key;
}

// Test API key validity (lightweight call)
export async function testApiKey(provider: string, key: string): Promise<boolean> {
  try {
    switch (provider) {
      case 'openai':
        const openai = new OpenAI({ apiKey: key });
        // Test by listing models (cheap call)
        await openai.models.list();
        return true;
      case 'anthropic':
        // Similar test for Anthropic
        return true;
      default:
        // Unknown provider, assume invalid
        return false;
    }
  } catch (error) {
    console.error(`API key test failed for ${provider}:`, error);
    return false;
  }
}

// Main check function
export async function checkApiKeyAccess(supabase: any, appId: string): Promise<boolean> {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return false;

  const requiredProviders = await fetchAppRequirements(supabase, appId);
  if (requiredProviders.length === 0) {
    // No requirements → accessible
    return true;
  }

  const userKeys = await fetchUserApiKeys(supabase);

  // Check all required providers are present
  return requiredProviders.every((provider: string) => !!userKeys[provider]);
}

// React Hook
export function useApiKeyGate(appId: string | null): ApiKeyGateContextType {
  const supabase = useSupabaseClient();
  const { user } = useUser();
  const [hasAccess, setHasAccess] = useState(false);
  const [checking, setChecking] = useState(true);
  const [missingProviders, setMissingProviders] = useState<string[]>([]);

  const checkAccess = useCallback(async () => {
    if (!appId || !user) {
      setHasAccess(false);
      setChecking(false);
      return false;
    }

    try {
      const accessible = await checkApiKeyAccess(supabase, appId);
      setHasAccess(accessible);

      if (!accessible) {
        const required = await fetchAppRequirements(supabase, appId);
        const userKeys = await fetchUserApiKeys(supabase);
        const missing = required.filter((p) => !userKeys[p]);
        setMissingProviders(missing);
      }

      setChecking(false);
      return accessible;
    } catch (error) {
      console.error('API key check failed:', error);
      setHasAccess(false);
      setChecking(false);
      return false;
    }
  }, [appId, user, supabase]);

  useEffect(() => {
    checkAccess();
  }, [checkAccess]);

  const saveApiKey = useCallback(
    async (provider: string, key: string): Promise<boolean> => {
      const success = await saveUserApiKey(supabase, provider, key);
      if (success) {
        await checkAccess();
      }
      return success;
    },
    [supabase, checkAccess]
  );

  const getUserApiKey = useCallback(
    async (provider: string): Promise<string | null> => {
      return await getUserApiKey(supabase, provider);
    },
    [supabase]
  );

  const testApiKeyWrapper = useCallback(async (provider: string, key: string) => {
    return await testApiKey(provider, key);
  }, []);

  return {
    hasAccess,
    checking,
    missingProviders,
    checkAccess,
    saveApiKey,
    getUserApiKey,
    testApiKey: testApiKeyWrapper,
  };
}

import { supabase } from "../utils/supabase";
import { classifyError, withRetry, RetryConfig } from "../utils/errorHandling";

/**
 * Result type for safe mutations
 */
export interface SafeMutationResult<T = void> {
  success: boolean;
  data?: T;
  error?: string;
  isDuplicate?: boolean;
}

/**
 * Configuration for safe mutation
 */
export interface SafeMutationConfig {
  /** Unique key to prevent duplicate operations */
  idempotencyKey?: string;
  /** Table name for the operation */
  table: string;
  /** Retry configuration */
  retryConfig?: RetryConfig;
  /** Maximum time to wait before considering a request timed out */
  timeoutMs?: number;
}

/**
 * In-memory store for tracking in-flight mutations and idempotency keys
 * Note: This is per-session. For true duplicate prevention across sessions,
 * you would need server-side idempotency keys stored in the database.
 */
const inFlightMutations = new Map<string, Promise<unknown>>();
const completedIdempotencyKeys = new Map<string, unknown>();

/**
 * Clean up old idempotency keys to prevent memory growth
 * Uses a simple size limit - keys are evicted when map exceeds limit
 */
function cleanupIdempotencyKeys(): void {
  // Limit cache size to prevent unbounded growth
  if (completedIdempotencyKeys.size > 100) {
    const keysToDelete = Array.from(completedIdempotencyKeys.keys()).slice(0, 50);
    keysToDelete.forEach(key => completedIdempotencyKeys.delete(key));
  }
}

// Cleanup is triggered on each mutation rather than via interval
// This avoids memory leaks from unbounded setInterval calls

/**
 * Generate a unique request ID for tracking
 */
function generateRequestId(): string {
  return `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
}

/**
 * Check if a mutation with the same idempotency key is already in progress
 */
function isMutationInProgress(idempotencyKey: string): boolean {
  return inFlightMutations.has(idempotencyKey);
}

/**
 * Wait for an existing mutation to complete
 */
async function waitForMutation(idempotencyKey: string): Promise<unknown> {
  const existingPromise = inFlightMutations.get(idempotencyKey);
  if (existingPromise) {
    try {
      const result = await existingPromise;
      const cached = completedIdempotencyKeys.get(idempotencyKey);
      return cached ?? result;
    } catch {
      // If the existing mutation failed, allow retry
    }
  }
  return { success: false, error: "Operation in progress" };
}

/**
 * Safe mutation helper that prevents duplicate database writes
 * 
 * @param operation - The async operation to perform
 * @param config - Configuration for the mutation
 * 
 * @example
 * ```ts
 * const result = await safeMutation(
 *   async () => {
 *     const { data, error } = await supabase
 *       .from('purchases')
 *       .insert(purchaseData)
 *       .select()
 *       .single();
 *     if (error) throw error;
 *     return data;
 *   },
 *   {
 *     table: 'purchases',
 *     idempotencyKey: `purchase-${userId}-${productId}`,
 *   }
 * );
 * ```
 */
export async function safeMutation<T>(
  operation: () => Promise<T>,
  config: SafeMutationConfig
): Promise<SafeMutationResult<T>> {
  const { 
    idempotencyKey, 
    table, 
    retryConfig, 
    timeoutMs = 30000 
  } = config;

  // Generate request ID for tracking
  const requestId = generateRequestId();

  // Use provided idempotency key or generate one
  const mutationKey = idempotencyKey || `${table}-${requestId}`;

  // Check if mutation is already in progress
  if (idempotencyKey && isMutationInProgress(mutationKey)) {
    console.log(`[safeMutation] Mutation in progress for key: ${mutationKey}`);
    const result = await waitForMutation(mutationKey);
    return result as SafeMutationResult<T>;
  }

  // Check if we have a recent completion for this idempotency key
  if (idempotencyKey && completedIdempotencyKeys.has(idempotencyKey)) {
    const cached = completedIdempotencyKeys.get(idempotencyKey);
    if (cached) {
      console.log(`[safeMutation] Returning cached result for key: ${idempotencyKey}`);
      return cached as SafeMutationResult<T>;
    }
  }

  // Cleanup old keys before adding new one
  cleanupIdempotencyKeys();

  // Create the mutation promise and store it
  const mutationPromise = (async (): Promise<SafeMutationResult<T>> => {
    try {
      // Execute with retry support
      const result = await withRetry(
        async () => {
          // Add timeout support
          const timeoutPromise = new Promise<never>((_, reject) => {
            setTimeout(() => reject(new Error("Mutation timed out")), timeoutMs);
          });

          try {
            const result = await operation();
            return result;
          } catch (error) {
            // Check if it's a duplicate key error
            if (error instanceof Error && 
                (error.message.includes('duplicate key') || 
                 error.message.includes('unique constraint'))) {
              console.log(`[safeMutation] Duplicate detected for key: ${mutationKey}`);
              // Return a special marker for duplicate
              return null;
            }
            throw error;
          }
        },
        retryConfig,
        (attempt, error) => {
          console.log(`[safeMutation] Retry attempt ${attempt} for key: ${mutationKey}`, error);
        }
      );

      // Check if result is null (indicates duplicate)
      if (result === null) {
        const duplicateResult: SafeMutationResult<T> = {
          success: false,
          error: "Duplicate operation detected",
          isDuplicate: true,
        };

        if (idempotencyKey) {
          completedIdempotencyKeys.set(idempotencyKey, duplicateResult);
        }

        return duplicateResult;
      }

      const successResult: SafeMutationResult<T> = {
        success: true,
        data: result,
      };

      // Cache successful result
      if (idempotencyKey) {
        completedIdempotencyKeys.set(idempotencyKey, successResult);
      }

      return successResult;
    } catch (error) {
      const classifiedError = classifyError(error);

      const errorResult: SafeMutationResult<T> = {
        success: false,
        error: classifiedError.message || "Operation failed",
      };

      return errorResult;
    } finally {
      // Clean up in-flight mutation
      inFlightMutations.delete(mutationKey);
    }
  })();

  // Store the promise for other callers to wait on
  inFlightMutations.set(mutationKey, mutationPromise);

  return mutationPromise;
}

/**
 * Helper to create a safe insert operation
 * 
 * @example
 * ```ts
 * const result = await safeInsert(
 *   'purchases',
 *   purchaseData,
 *   { idempotencyKey: `purchase-${userId}-${productId}` }
 * );
 * ```
 */
export async function safeInsert<T = unknown>(
  table: string,
  data: Record<string, unknown>,
  options: {
    idempotencyKey?: string;
    retryConfig?: RetryConfig;
  } = {}
): Promise<SafeMutationResult<T>> {
  return safeMutation<T>(
    async () => {
      const { data: result, error } = await supabase
        .from(table)
        .insert(data)
        .select()
        .single();

      if (error) {
        // Check for duplicate key errors
        if (error.message.includes('duplicate key') || 
            error.message.includes('unique constraint')) {
          throw new Error(`DUPLICATE: ${error.message}`);
        }
        throw error;
      }

      return result as T;
    },
    {
      table,
      idempotencyKey: options.idempotencyKey,
      retryConfig: options.retryConfig,
    }
  );
}

/**
 * Helper to create a safe upsert operation (for updating or inserting)
 * 
 * @example
 * ```ts
 * const result = await safeUpsert(
 *   'user_app_access',
 *   { user_id: userId, app_slug: appSlug, is_active: true },
 *   { conflictColumns: ['user_id', 'app_slug'] }
 * );
 * ```
 */
export async function safeUpsert<T = unknown>(
  table: string,
  data: Record<string, unknown>,
  options: {
    idempotencyKey?: string;
    retryConfig?: RetryConfig;
    conflictColumns?: string[];
  } = {}
): Promise<SafeMutationResult<T>> {
  const { conflictColumns = [] } = options;

  return safeMutation<T>(
    async () => {
      const { data: result, error } = await supabase
        .from(table)
        .upsert(data, { 
          onConflict: conflictColumns.join(', ')
        })
        .select()
        .single();

      if (error) {
        throw error;
      }

      return result as T;
    },
    {
      table,
      idempotencyKey: options.idempotencyKey,
      retryConfig: options.retryConfig,
    }
  );
}

/**
 * Create a unique idempotency key for a purchase
 * This helps prevent duplicate purchases if the user clicks multiple times
 */
export function createPurchaseIdempotencyKey(
  userId: string,
  productId: string,
  platform: string
): string {
  return `purchase-${userId}-${productId}-${platform}`;
}

/**
 * Create a unique idempotency key for granting ai-design-studio access
 */
export function createAppAccessIdempotencyKey(
  userId: string,
  appSlug: string
): string {
  return `ai-design-studio-access-${userId}-${appSlug}`;
}

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  ReactNode,
} from "react";
import { supabase } from "../utils/supabase";

interface AdminUser {
  id: string;
  email: string;
  role: string;
  is_active: boolean;
  permissions: Record<string, any>;
  created_at: string;
  last_login?: string;
}

interface AdminContextType {
  user: AdminUser | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (
    email: string,
    password: string,
  ) => Promise<{ success: boolean; error?: string }>;
  signup: (
    email: string,
    password: string,
  ) => Promise<{ success: boolean; error?: string }>;
  logout: () => Promise<void>;
  verifyAuth: () => Promise<void>;
  sessionExpiry?: Date;
}

const AdminContext = createContext<AdminContextType | undefined>(undefined);

export const useAdmin = () => {
  const context = useContext(AdminContext);
  if (context === undefined) {
    throw new Error("useAdmin must be used within an AdminProvider");
  }
  return context;
};

interface AdminProviderProps {
  children: ReactNode;
}

export const AdminProvider: React.FC<AdminProviderProps> = ({ children }) => {
  console.log("[AdminContext] AdminProvider mounted - this should only happen on admin routes");
  const [user, setUser] = useState<AdminUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [sessionExpiry, setSessionExpiry] = useState<Date | undefined>();
  const isVerifyingRef = React.useRef(false);
  const lastVerificationRef = React.useRef<number>(0);
  const VERIFICATION_COOLDOWN = 2000;
  const SESSION_TIMEOUT_MS = 8 * 60 * 60 * 1000; // 8 hours

  const login = useCallback(
    async (
      email: string,
      password: string,
    ): Promise<{ success: boolean; error?: string }> => {
      try {
        setIsLoading(true);

        const { data: authData, error: authError } =
          await supabase.auth.signInWithPassword({
            email,
            password,
          });

        if (authError) {
          return { success: false, error: authError.message };
        }

        if (!authData.user || !authData.session) {
          return { success: false, error: "Authentication failed" };
        }

        const { data: roleData, error: roleError } = await supabase
          .from("user_roles")
          .select("role")
          .eq("user_id", authData.user.id)
          .maybeSingle();

        if (roleError || !roleData) {
          // FIX: Don't sign out - just return error, user's normal auth session stays intact
          return {
            success: false,
            error: "User does not have admin privileges",
          };
        }

        if (roleData.role !== "super_admin" && roleData.role !== "admin") {
          // FIX: Don't sign out - just return error, user's normal auth session stays intact
          return {
            success: false,
            error: "Access denied: Admin privileges required",
          };
        }

        const adminUser: AdminUser = {
          id: authData.user.id,
          email: authData.user.email!,
          role: roleData.role,
          is_active: true,
          permissions: {},
          created_at: authData.user.created_at,
          last_login: new Date().toISOString(),
        };

        // Set session expiry
        const expiry = new Date(Date.now() + SESSION_TIMEOUT_MS);
        setSessionExpiry(expiry);

        console.log(
          "AdminContext - Login successful, setting user:",
          adminUser,
        );
        console.log("AdminContext - Session exists:", !!authData.session);
        console.log("AdminContext - Session expires:", expiry.toISOString());
        setUser(adminUser);

        // Verify session was persisted
        setTimeout(async () => {
          const {
            data: { session },
          } = await supabase.auth.getSession();
          console.log(
            "AdminContext - Session persisted after login:",
            !!session,
          );
        }, 100);

        return { success: true };
      } catch (error) {
        console.error("Login error:", error);
        return { success: false, error: "Network error occurred" };
      } finally {
        setIsLoading(false);
      }
    },
    [],
  );

  const signup = useCallback(
    async (
      email: string,
      password: string,
    ): Promise<{ success: boolean; error?: string }> => {
      try {
        setIsLoading(true);

        const { data: authData, error: authError } = await supabase.auth.signUp(
          {
            email,
            password,
          },
        );

        if (authError) {
          return { success: false, error: authError.message };
        }

        if (!authData.user) {
          return { success: false, error: "Sign up failed" };
        }

        return { success: true };
      } catch (error) {
        console.error("Sign up error:", error);
        return { success: false, error: "Network error occurred" };
      } finally {
        setIsLoading(false);
      }
    },
    [],
  );

  const logout = useCallback(async (): Promise<void> => {
    try {
      await supabase.auth.signOut();
    } catch (error) {
      console.error("Logout error:", error);
    } finally {
      setUser(null);
      setSessionExpiry(undefined);
    }
  }, []);

  const verifyAuth = useCallback(async (): Promise<void> => {
    const now = Date.now();

    if (isVerifyingRef.current) {
      return;
    }

    if (now - lastVerificationRef.current < VERIFICATION_COOLDOWN) {
      return;
    }

    try {
      isVerifyingRef.current = true;
      lastVerificationRef.current = now;

      const timeoutId = setTimeout(() => {
        console.log("AdminContext - verifyAuth timed out after 10 seconds");
        setIsLoading(false);
        setUser(null);
        isVerifyingRef.current = false;
      }, 30000); // Increased to 30 seconds to prevent premature timeout

      const {
        data: { session },
        error,
      } = await supabase.auth.getSession();
      clearTimeout(timeoutId);

      if (error || !session) {
        setUser(null);
        setIsLoading(false);
        isVerifyingRef.current = false;
        return;
      }

      const { data: roleData, error: roleError } = await supabase
        .from("user_roles")
        .select("role")
        .eq("user_id", session.user.id)
        .maybeSingle();

      if (roleError) {
        console.error("AdminContext - Error fetching role:", roleError);
        // Don't sign out on error, just set loading to false and clear admin state
        setUser(null);
        setIsLoading(false);
        isVerifyingRef.current = false;
        return;
      }

      if (!roleData) {
        console.log("AdminContext - No admin role found for user (this is normal for regular users)");
        // Don't sign out - just don't set admin user
        setUser(null);
        setIsLoading(false);
        isVerifyingRef.current = false;
        return;
      }

      if (roleData.role !== "super_admin" && roleData.role !== "admin") {
        console.log(
          "AdminContext - User does not have admin role:",
          roleData.role,
          "(this is normal for regular users)"
        );
        // Don't sign out regular users - just don't set admin user
        setUser(null);
        setIsLoading(false);
        isVerifyingRef.current = false;
        return;
      }

      const adminUser: AdminUser = {
        id: session.user.id,
        email: session.user.email!,
        role: roleData.role,
        is_active: true,
        permissions: {},
        created_at: session.user.created_at,
      };

      setUser(adminUser);
      setIsLoading(false);
      isVerifyingRef.current = false;
    } catch (error) {
      console.error("AdminContext - Auth verification error:", error);
      setUser(null);
      setIsLoading(false);
      isVerifyingRef.current = false;
    }
  }, []);

  // Session timeout checker
  useEffect(() => {
    if (!sessionExpiry || !user) return;

    const checkSessionTimeout = () => {
      if (new Date() > sessionExpiry) {
        console.log("AdminContext - Session expired, logging out");
        logout();
      }
    };

    // Check immediately
    checkSessionTimeout();

    // Set up interval to check every minute
    const interval = setInterval(checkSessionTimeout, 60 * 1000);

    return () => clearInterval(interval);
  }, [sessionExpiry, user, logout]);

  useEffect(() => {
    // Don't automatically verify auth on mount for regular users
    // Only verify when explicitly needed (like on admin pages)

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === "SIGNED_OUT") {
        setUser(null);
        setSessionExpiry(undefined);
        setIsLoading(false);
      }
      // AdminContext doesn't interfere with regular user authentication
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []); // Remove verifyAuth dependency

  const value: AdminContextType = React.useMemo(
    () => ({
      user,
      isLoading,
      isAuthenticated: !!user,
      login,
      signup,
      logout,
      verifyAuth,
      sessionExpiry,
    }),
    [user, isLoading, login, signup, logout, verifyAuth, sessionExpiry],
  );

  return (
    <AdminContext.Provider value={value}>{children}</AdminContext.Provider>
  );
};

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  ReactNode,
} from "react";
import type {
  HeroContent,
  BenefitFeature,
  Testimonial,
  FAQ,
  PricingPlan,
} from "../utils/supabaseTypes";

interface LandingPageContextType {
  hero: HeroContent | null;
  benefitsFeatures: BenefitFeature[];
  testimonials: Testimonial[];
  faqs: FAQ[];
  pricingPlans: PricingPlan[];
  isLoading: boolean;
  error: string | null;
  refetchContent: () => Promise<void>;
}

const defaultContext: LandingPageContextType = {
  hero: null,
  benefitsFeatures: [],
  testimonials: [],
  faqs: [],
  pricingPlans: [],
  isLoading: true,
  error: null,
  refetchContent: async () => {},
};

const LandingPageContext =
  createContext<LandingPageContextType>(defaultContext);

export const useLandingPageContent = () => useContext(LandingPageContext);

interface LandingPageProviderProps {
  children: ReactNode;
}

const LandingPageProvider: React.FC<LandingPageProviderProps> = ({
  children,
}) => {
  const [content, setContent] = useState<
    Omit<LandingPageContextType, "isLoading" | "error" | "refetchContent">
  >({
    hero: null,
    benefitsFeatures: [],
    testimonials: [],
    faqs: [],
    pricingPlans: [],
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchContent = async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Dynamically import to break circular dependency
      const { getAllLandingPageContent } = await import("../utils/supabaseClient");
      const data = await getAllLandingPageContent();

      setContent({
        hero: data.hero,
        benefitsFeatures: data.benefits || [],
        testimonials: data.testimonials || [],
        faqs: data.faqs || [],
        pricingPlans: data.pricing || [],
      });
    } catch (err) {
      console.error("Error fetching landing page content:", err);
      setError("Failed to load content. Please try again later.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchContent();
  }, []);

  const value = {
    ...content,
    isLoading,
    error,
    refetchContent: fetchContent,
  };

  return (
    <LandingPageContext.Provider value={value}>
      {children}
    </LandingPageContext.Provider>
  );
};
export { LandingPageProvider };

import { createContext, useContext, useState, useEffect, ReactNode } from "react";

interface AnimationContextType {
  prefersReducedMotion: boolean;
  lowPowerMode: boolean;
  highPerformanceMode: boolean;
  isInitialLoadComplete: boolean;
  setIsInitialLoadComplete: (value: boolean) => void;
  shouldDisableComplexAnimations: boolean;
  calculateAnimationDelay: (
    baseDelay: number,
    priority: "high" | "medium" | "low",
  ) => number;
  registerAnimation: () => void;
  completeAnimation: () => void;
}

const AnimationContext = createContext<AnimationContextType>({
  prefersReducedMotion: false,
  lowPowerMode: false,
  highPerformanceMode: true,
  isInitialLoadComplete: false,
  setIsInitialLoadComplete: () => {},
  shouldDisableComplexAnimations: false,
  calculateAnimationDelay: () => 0,
  registerAnimation: () => {},
  completeAnimation: () => {},
});

export const useAnimationContext = () => useContext(AnimationContext);

export const AnimationProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  const [lowPowerMode, setLowPowerMode] = useState(false);
  const [highPerformanceMode, setHighPerformanceMode] = useState(true);
  const [isInitialLoadComplete, setIsInitialLoadComplete] = useState(false);
  const [pendingAnimations, setPendingAnimations] = useState(0);

  // Disable complex animations for reduced motion or low power mode
  const shouldDisableComplexAnimations = prefersReducedMotion || lowPowerMode;

  // Calculate animation delay based on priority
  const calculateAnimationDelay = (
    baseDelay: number,
    priority: "high" | "medium" | "low",
  ) => {
    if (prefersReducedMotion) return 0;

    switch (priority) {
      case "high":
        return baseDelay;
      case "medium":
        return baseDelay + 0.1;
      case "low":
        return baseDelay + 0.3;
      default:
        return baseDelay;
    }
  };

  // Animation tracking functions
  const registerAnimation = () => {
    setPendingAnimations((prev) => prev + 1);
  };

  const completeAnimation = () => {
    setPendingAnimations((prev) => Math.max(0, prev - 1));
  };

  useEffect(() => {
    // Check for reduced motion preference
    const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    setPrefersReducedMotion(motionQuery.matches);

    const handleReducedMotionChange = (e: MediaQueryListEvent) => {
      setPrefersReducedMotion(e.matches);
    };

    // Add event listener
    if (motionQuery.addEventListener) {
      motionQuery.addEventListener("change", handleReducedMotionChange);
    } else {
      // Fallback for older browsers
      motionQuery.addListener(handleReducedMotionChange);
    }

    // Check for low-end devices
    const detectDeviceCapabilities = () => {
      // Basic checks for device performance
      const isLowPower =
        (window.navigator.hardwareConcurrency !== undefined &&
          window.navigator.hardwareConcurrency <= 4) ||
        /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
          navigator.userAgent,
        );

      // Determine if this is a high-performance device
      const isHighPerformance =
        window.navigator.hardwareConcurrency !== undefined &&
        window.navigator.hardwareConcurrency >= 8 &&
        !/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
          navigator.userAgent,
        );

      setLowPowerMode(isLowPower);
      setHighPerformanceMode(isHighPerformance);
    };

    detectDeviceCapabilities();

    // Set initial load complete after a short delay
    // This ensures animations don't run until the page is ready
    const initialLoadTimer = setTimeout(() => {
      setIsInitialLoadComplete(true);
    }, 500);

    return () => {
      if (motionQuery.removeEventListener) {
        motionQuery.removeEventListener("change", handleReducedMotionChange);
      } else {
        motionQuery.removeListener(handleReducedMotionChange);
      }
      clearTimeout(initialLoadTimer);
    };
  }, []);

  const contextValue = {
    prefersReducedMotion,
    lowPowerMode,
    highPerformanceMode,
    isInitialLoadComplete,
    setIsInitialLoadComplete,
    shouldDisableComplexAnimations,
    calculateAnimationDelay,
    registerAnimation,
    completeAnimation,
  };

  return (
    <AnimationContext.Provider value={contextValue}>
      {children}
    </AnimationContext.Provider>
  );
};

export default AnimationProvider;

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useMemo,
  ReactNode,
  useRef,
} from "react";
import { User, Session, AuthError, AuthChangeEvent } from "@supabase/supabase-js";
import { supabase } from "../utils/supabase";

// Auth state types
export type AuthState = "idle" | "loading" | "authenticated" | "unauthenticated" | "error";

export interface AuthErrorState {
  message: string;
  code?: string;
  recoverable: boolean;
}

interface AuthContextType {
  // Core state
  user: User | null;
  session: Session | null;
  loading: boolean;
  isAuthenticated: boolean;
  authState: AuthState;
  error: AuthErrorState | null;

  // Session metadata
  sessionExpiresAt: number | null;
  isSessionExpiringSoon: boolean;

  // Auth actions
  signUp: (
    email: string,
    password: string,
    metadata?: Record<string, unknown>
  ) => Promise<{ user: User | null; error: AuthError | null }>;
  signIn: (
    email: string,
    password: string
  ) => Promise<{ user: User | null; error: AuthError | null }>;
  signOut: () => Promise<{ error: AuthError | null }>;
  resetPassword: (email: string) => Promise<{ error: AuthError | null }>;
  updateProfile: (
    updates: Record<string, unknown>
  ) => Promise<{ user: User | null; error: AuthError | null }>;
  updateOnboardingAnswers: (
    answers: Record<string, unknown>
  ) => Promise<{ user: User | null; error: AuthError | null }>;
  refreshSession: () => Promise<boolean>;

  // Utility
  clearError: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

// Constants
const SESSION_REFRESH_THRESHOLD_MS = 10 * 60 * 1000; // 10 minutes before expiry (more conservative)
const SESSION_CHECK_INTERVAL_MS = 5 * 60 * 1000; // Check every 5 minutes (less frequent)
const STORAGE_KEY_SESSION = "sb-session-state";

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  // Core state
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [authState, setAuthState] = useState<AuthState>("idle");
  const [error, setError] = useState<AuthErrorState | null>(null);

  // Refs for cleanup and tracking
  const mountedRef = useRef(true);
  const subscriptionRef = useRef<{ unsubscribe: () => void } | null>(null);
  const sessionCheckIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const isRefreshingRef = useRef(false);

  // Derived state
  const isAuthenticated = useMemo(() => !!user && !!session, [user, session]);
  const sessionExpiresAt = useMemo(() => session?.expires_at ?? null, [session]);
  const isSessionExpiringSoon = useMemo(() => {
    if (!sessionExpiresAt) return false;
    const expiresAtMs = sessionExpiresAt * 1000;
    const now = Date.now();
    return expiresAtMs - now < SESSION_REFRESH_THRESHOLD_MS;
  }, [sessionExpiresAt]);

  // Clear error utility
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  // Handle auth errors
  const handleAuthError = useCallback((err: unknown, context: string) => {
    console.error(`[Auth] Error in ${context}:`, err);

    // Using let because we modify properties, not reassign the variable
    // eslint-disable-next-line prefer-const
    let authError: AuthErrorState = {
      message: "An unexpected authentication error occurred",
      recoverable: true,
    };

    if (err instanceof Error) {
      authError.message = err.message;

      // Check for specific error types
      if (err.message.includes("refresh") || err.message.includes("token")) {
        authError.code = "TOKEN_REFRESH_FAILED";
        authError.recoverable = true;
      } else if (err.message.includes("network") || err.message.includes("fetch")) {
        authError.code = "NETWORK_ERROR";
        authError.recoverable = true;
      } else if (err.message.includes("session") || err.message.includes("expired")) {
        authError.code = "SESSION_EXPIRED";
        authError.recoverable = true;
      }
    }

    setError(authError);
    return authError;
  }, []);

  // Debug logging for auth state changes
  const logAuthState = useCallback((action: string, details?: any) => {
    console.log(`[Auth:${action}]`, {
      user: user ? `${user.id} (${user.email})` : null,
      session: session ? `expires: ${new Date(session.expires_at * 1000).toISOString()}` : null,
      authState,
      loading,
      isAuthenticated,
      timestamp: new Date().toISOString(),
      ...details
    });
  }, [user, session, authState, loading, isAuthenticated]);

  // Refresh session proactively
  const refreshSession = useCallback(async (): Promise<boolean> => {
    if (isRefreshingRef.current) {
      console.log("[Auth] Refresh already in progress, skipping");
      return false;
    }

    try {
      isRefreshingRef.current = true;
      console.log("[Auth] Starting session refresh");

      const { data, error: refreshError } = await supabase.auth.refreshSession();

      if (refreshError) {
        console.error("[Auth] Session refresh failed:", refreshError.message);

        // Only clear session on critical errors, not network issues
        if (refreshError.message.includes("Invalid refresh token") ||
            refreshError.message.includes("refresh_token_not_found") ||
            refreshError.message.includes("JWT expired")) {
          console.log("[Auth] Critical refresh error - clearing session");
          handleAuthError(refreshError, "refreshSession");
          if (mountedRef.current) {
            setSession(null);
            setUser(null);
            setAuthState("unauthenticated");
          }
          return false;
        } else if (refreshError.message.includes("fetch") ||
                   refreshError.message.includes("network") ||
                   refreshError.message.includes("Failed to fetch")) {
          // For network errors, retry once after a short delay
          console.log("[Auth] Network error during refresh, will retry once");
          await new Promise(resolve => setTimeout(resolve, 2000)); // Wait 2 seconds

          const { data: retryData, error: retryError } = await supabase.auth.refreshSession();
          if (retryError) {
            console.log("[Auth] Retry also failed, keeping existing session");
            return false;
          }

          if (mountedRef.current && retryData.session) {
            console.log("[Auth] Retry successful");
            setSession(retryData.session);
            setUser(retryData.session.user);
            setAuthState("authenticated");
            return true;
          }
        } else {
          // For other temporary issues, don't clear session
          console.log("[Auth] Non-critical refresh error, keeping existing session");
          return false;
        }
      }

      if (mountedRef.current && data.session) {
        console.log("[Auth] Session refresh successful");
        setSession(data.session);
        setUser(data.session.user);
        setAuthState("authenticated");

        // Update session hint
        try {
          sessionStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify({
            userId: data.session.user.id,
            expiresAt: data.session.expires_at,
          }));
        } catch {
          // Ignore storage errors
        }

        return true;
      }

      console.log("[Auth] Refresh returned no session");
      return false;
    } catch (err) {
      console.error("[Auth] Session refresh exception:", err);

      // Only clear session on authentication errors, not network errors
      const errorMessage = err instanceof Error ? err.message : String(err);
      if (errorMessage.includes("Invalid refresh token") ||
          errorMessage.includes("refresh_token_not_found") ||
          errorMessage.includes("JWT expired")) {
        handleAuthError(err, "refreshSession");
        if (mountedRef.current) {
          setSession(null);
          setUser(null);
          setAuthState("unauthenticated");
        }
      } else {
        console.log("[Auth] Non-critical exception during refresh, keeping session");
      }
      return false;
    } finally {
      isRefreshingRef.current = false;
    }
  }, [handleAuthError]);

  // Initialize session and set up listeners
  useEffect(() => {
    let mounted = true;
    mountedRef.current = true;

    const initializeAuth = async () => {
      try {
        setAuthState("loading");
        setLoading(true);

        // Get initial session
        const { data: { session: initialSession }, error: sessionError } = await supabase.auth.getSession();

        if (sessionError) {
          // Only treat as error if it's not a network/connectivity issue
          if (!sessionError.message.includes("fetch") && !sessionError.message.includes("network")) {
            handleAuthError(sessionError, "initializeAuth");
          } else {
            console.log("[Auth] Network error during session check, will retry later");
          }
        }

        if (mounted) {
          if (initialSession) {
            // Check if the session is already expired
            const now = Date.now();
            const expiresAt = initialSession.expires_at * 1000;
            const timeUntilExpiry = expiresAt - now;

            if (timeUntilExpiry > 60000) { // More than 1 minute left
              // Session is still valid
              setSession(initialSession);
              setUser(initialSession.user);
              setAuthState("authenticated");

              // Store session hint for faster recovery
              try {
                sessionStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify({
                  userId: initialSession.user.id,
                  expiresAt: initialSession.expires_at,
                }));
              } catch {
                // Ignore storage errors
              }
            } else if (timeUntilExpiry > 0) {
              // Session expires soon, try to refresh immediately
              console.log("[Auth] Initial session expires soon, attempting immediate refresh");
              setSession(initialSession); // Set temporarily
              setUser(initialSession.user);
              setAuthState("authenticated");

              // Try to refresh in background
              refreshSession().catch(err => {
                console.error("[Auth] Background refresh failed:", err);
              });
            } else {
              // Session is expired, try to refresh once
              console.log("[Auth] Initial session is expired, attempting refresh");
              const refreshSuccess = await refreshSession();
              if (!refreshSuccess) {
                setSession(null);
                setUser(null);
                setAuthState("unauthenticated");
              }
            }
          } else {
            setSession(null);
            setUser(null);
            setAuthState("unauthenticated");
          }
          setLoading(false);
        }
      } catch (err) {
        handleAuthError(err, "initializeAuth");
        if (mounted) {
          setAuthState("error");
          setLoading(false);
        }
      }
    };

    // Initialize auth
    initializeAuth();

    // Set up auth state change listener
    const { data } = supabase.auth.onAuthStateChange(
      async (event: AuthChangeEvent, newSession: Session | null) => {
        logAuthState("stateChange", { event, hasSession: !!newSession, sessionUserId: newSession?.user?.id });

        if (!mounted) return;

        switch (event) {
          case "SIGNED_IN":
          case "TOKEN_REFRESHED":
            console.log(`[Auth] ${event} - Setting authenticated state`);
            if (newSession) {
              setSession(newSession);
              setUser(newSession.user);
              setAuthState("authenticated");
              setError(null);

              // Update session hint
              try {
                sessionStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify({
                  userId: newSession.user.id,
                  expiresAt: newSession.expires_at,
                }));
              } catch {
                // Ignore storage errors
              }
            }
            break;

          case "SIGNED_OUT":
            console.log("[Auth] SIGNED_OUT event received - user is being logged out", {
              currentUser: user?.id,
              currentSession: !!session,
              reason: newSession ? "new session provided" : "no session",
              timestamp: new Date().toISOString()
            });
            setSession(null);
            setUser(null);
            setAuthState("unauthenticated");
            setError(null);
            try {
              sessionStorage.removeItem(STORAGE_KEY_SESSION);
            } catch {
              // Ignore storage errors
            }
            break;

          case "USER_UPDATED":
            if (newSession) {
              setSession(newSession);
              setUser(newSession.user);
            }
            break;

          case "PASSWORD_RECOVERY":
            // Keep session but allow password reset flow
            if (newSession) {
              setSession(newSession);
              setUser(newSession.user);
            }
            break;

          default:
            // Handle other events
            if (newSession) {
              setSession(newSession);
              setUser(newSession.user);
              setAuthState("authenticated");
            }
        }

        setLoading(false);
      }
    );

    subscriptionRef.current = data.subscription;

    // Set up periodic session check (less aggressive, more robust)
    sessionCheckIntervalRef.current = setInterval(async () => {
      if (!mounted) return;

      try {
        // Get current session directly - avoids stale closure
        const { data: { session: currentSession }, error } = await supabase.auth.getSession();

        // Don't clear session on network errors - be more forgiving
        if (error) {
          if (error.message.includes('fetch') || error.message.includes('network')) {
            console.log("[Auth] Network error during session check, keeping existing session");
            return;
          }
        }

        // Only log if there are issues or significant changes
        if (!currentSession && session) {
          // Only clear if we're sure the session is gone (not just a network issue)
          // Check if we have a stored session hint that might indicate persistence issues
          const storedHint = sessionStorage.getItem(STORAGE_KEY_SESSION);
          if (storedHint) {
            console.log("[Auth] Session lost but storage hint exists, attempting refresh");
            await refreshSession();
            return;
          }

          console.log("[Auth] Session lost during periodic check - clearing state");
          if (mounted) {
            setSession(null);
            setUser(null);
            setAuthState("unauthenticated");
          }
          return;
        }

        // Check if session is expired
        if (currentSession?.expires_at) {
          const expiresAtMs = currentSession.expires_at * 1000;
          const now = Date.now();
          const timeUntilExpiry = expiresAtMs - now;

          // If session is already expired, clear state
          if (timeUntilExpiry <= 0) {
            console.log("[Auth] Session expired during periodic check");
            if (mounted) {
              setSession(null);
              setUser(null);
              setAuthState("unauthenticated");
            }
            return;
          }

          // Only refresh if expiring within threshold
          if (timeUntilExpiry < SESSION_REFRESH_THRESHOLD_MS && timeUntilExpiry > 0) {
            console.log("[Auth] Session expiring soon, refreshing...");
            await refreshSession(); // Don't block on refresh result
          }
        }
      } catch (error) {
        console.error("[Auth] Error during periodic session check:", error);
        // Don't clear session on exceptions - be conservative
      }
    }, SESSION_CHECK_INTERVAL_MS);

    // Handle visibility change (tab switching)
    const handleVisibilityChange = async () => {
      if (document.visibilityState === "visible" && mounted) {
        console.log("[Auth] Tab became visible, checking session...");

        try {
          // Verify session is still valid
          const { data: { session: currentSession }, error } = await supabase.auth.getSession();

          if (error) {
            if (error.message.includes('fetch') || error.message.includes('network')) {
              console.log("[Auth] Network error on tab focus, keeping existing session");
              return;
            }
          }

          if (currentSession) {
            // Check if session expired while tab was hidden
            const expiresAt = currentSession.expires_at;
            const now = Date.now();
            const expiresAtMs = expiresAt ? expiresAt * 1000 : 0;

            if (expiresAt && expiresAtMs < now) {
              console.log("[Auth] Session expired while tab was hidden, attempting refresh");
              const refreshSuccess = await refreshSession();
              if (!refreshSuccess) {
                setSession(null);
                setUser(null);
                setAuthState("unauthenticated");
              }
            } else {
              // Only update if session actually changed
              if (!session || session.access_token !== currentSession.access_token) {
                console.log("[Auth] Session still valid, updating state");
                setSession(currentSession);
                setUser(currentSession.user);
                setAuthState("authenticated");
              }
            }
          } else {
            // Check if we have a stored session hint that might indicate the session should still be valid
            const storedHint = sessionStorage.getItem(STORAGE_KEY_SESSION);
            if (storedHint && session) {
              console.log("[Auth] No session found but storage hint exists, attempting refresh");
              const refreshSuccess = await refreshSession();
              if (!refreshSuccess) {
                setSession(null);
                setUser(null);
                setAuthState("unauthenticated");
              }
            } else {
              // Session was cleared (possibly signed out in another tab)
              console.log("[Auth] No session found on tab focus");
              setSession(null);
              setUser(null);
              setAuthState("unauthenticated");
            }
          }
        } catch (err) {
          console.error("[Auth] Error during visibility change check:", err);
          // Don't clear session on errors
        }

        setLoading(false);
      }
    };

    // Handle storage events (cross-tab sync)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY_SESSION && mounted) {
        if (!e.newValue) {
          // Session was cleared in another tab
          setSession(null);
          setUser(null);
          setAuthState("unauthenticated");
        }
        // Don't update state for new values - let onAuthStateChange handle that
      }
    };

    // Handle online/offline events
    const handleOnline = () => {
      console.log("[Auth] Network back online, refreshing session...");
      refreshSession();
    };

    const handleOffline = () => {
      console.log("[Auth] Network offline");
    };

    // Add event listeners
    document.addEventListener("visibilitychange", handleVisibilityChange);
    window.addEventListener("storage", handleStorageChange);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    // Cleanup
    return () => {
      mounted = false;
      mountedRef.current = false;

      if (subscriptionRef.current) {
        subscriptionRef.current.unsubscribe();
      }

      if (sessionCheckIntervalRef.current) {
        clearInterval(sessionCheckIntervalRef.current);
      }

      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.removeEventListener("storage", handleStorageChange);
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, [handleAuthError, refreshSession]);

  // Auth actions
  const signUp = useCallback(
    async (email: string, password: string, metadata?: Record<string, unknown>) => {
      clearError();
      const siteUrl = import.meta.env.VITE_SITE_URL || window.location.origin;
      const { data, error: signUpError } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: metadata,
          emailRedirectTo: `${siteUrl}/auth/confirm`,
          // SUPERPOWERS: Disable email confirmation requirement
          emailConfirm: false
        },
      });

      if (signUpError) {
        handleAuthError(signUpError, "signUp");
      }

      return { user: data.user, error: signUpError };
    },
    [clearError, handleAuthError]
  );

  const signIn = useCallback(
    async (email: string, password: string) => {
      console.log("[Auth] signIn called", { email, timestamp: new Date().toISOString() });
      clearError();
      logAuthState("signIn:start", { email });
      const { data, error: signInError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (signInError) {
        console.log("[Auth] signIn failed", { error: signInError.message });
        handleAuthError(signInError, "signIn");
      } else {
        console.log("[Auth] signIn successful", {
          userId: data.user?.id,
          email: data.user?.email,
          hasSession: !!data.session
        });
      }

      return { user: data.user, error: signInError };
    },
    [clearError, handleAuthError, logAuthState]
  );

  const signOut = useCallback(async () => {
    clearError();
    setLoading(true);

    try {
      console.log("[Auth] Starting sign out process");

      const { error: signOutError } = await supabase.auth.signOut();

      if (signOutError) {
        console.error("[Auth] Sign out error:", signOutError);
        handleAuthError(signOutError, "signOut");
        setLoading(false);
        return { error: signOutError };
      }

      console.log("[Auth] Sign out successful, clearing local state");

      // Clear local state immediately
      setSession(null);
      setUser(null);
      setAuthState("unauthenticated");

      // Clear session storage
      try {
        sessionStorage.removeItem(STORAGE_KEY_SESSION);
        localStorage.removeItem("videoremix-auth");
      } catch {
        // Ignore storage errors
      }

      setLoading(false);
      return { error: null };
    } catch (err) {
      console.error("[Auth] Sign out exception:", err);
      handleAuthError(err, "signOut");
      setLoading(false);
      return { error: err as AuthError };
    }
  }, [clearError, handleAuthError]);

  const resetPassword = useCallback(
    async (email: string) => {
      clearError();
      const siteUrl = import.meta.env.VITE_SITE_URL || window.location.origin;
      const { error: resetError } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${siteUrl}/auth/callback`,
      });

      if (resetError) {
        handleAuthError(resetError, "resetPassword");
      }

      return { error: resetError };
    },
    [clearError, handleAuthError]
  );

  const updateProfile = useCallback(
    async (updates: Record<string, unknown>) => {
      clearError();
      const { data, error: updateError } = await supabase.auth.updateUser({
        data: updates,
      });

      if (updateError) {
        handleAuthError(updateError, "updateProfile");
        return { user: data?.user, error: updateError };
      }

        // Also save to profiles table for extended profile data with tenant support
        if (data?.user) {
          const profileData = {
            user_id: data.user.id,
            email: data.user.email,
            full_name: `${updates.first_name || ''} ${updates.last_name || ''}`.trim(),
            avatar_url: updates.avatar_url || '',
            bio: updates.bio || '',
            company: updates.company || '',
            website: updates.website || '',
            // Add onboarding fields
            onboarding_answers: updates.onboarding || null,
            onboarding_completed_at: updates.onboarding_completed ? new Date().toISOString() : null,
          };

        // Try to upsert into profiles table
        const { error: profileError } = await supabase
          .from('profiles')
          .upsert(profileData, { onConflict: 'user_id' });

        if (profileError) {
          console.warn('Failed to update profiles table:', profileError);
        }
      }

      return { user: data.user, error: updateError };
    },
    [clearError, handleAuthError, supabase]
  );

  const updateOnboardingAnswers = useCallback(
    async (answers: Record<string, unknown>) => {
      try {
        const { data, error } = await supabase.auth.updateUser({
          data: answers,
        });
        return { user: data.user, error };
      } catch (err) {
        return { user: null, error: err as AuthError };
      }
    },
    []
  );

  const value: AuthContextType = useMemo(
    () => ({
      // Core state
      user,
      session,
      loading,
      isAuthenticated,
      authState,
      error,

      // Session metadata
      sessionExpiresAt,
      isSessionExpiringSoon,

      // Auth actions
      signUp,
      signIn,
      signOut,
      resetPassword,
      updateProfile,
      updateOnboardingAnswers,
      refreshSession,

      // Utility
      clearError,
    }),
    [
      user,
      session,
      loading,
      isAuthenticated,
      authState,
      error,
      sessionExpiresAt,
      isSessionExpiringSoon,
      signUp,
      signIn,
      signOut,
      resetPassword,
      updateProfile,
      updateOnboardingAnswers,
      refreshSession,
      clearError,
    ]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

// SECURITY HARDENED: AuthContext with httpOnly cookies & JWT validation
import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { supabase } from '../utils/supabaseClient';
import { useNavigate } from 'react-router-dom';

interface AuthUser {
  id: string;
  email: string | null;
  user_metadata?: any;
}

interface AuthContextType {
  user: AuthUser | null;
  loading: boolean;
  error: string | null;
  signIn: (email: string, password: string) => Promise<{ success: boolean; error?: string }>;
  signUp: (email: string, password: string) => Promise<{ success: boolean; error?: string }>;
  signOut: () => Promise<void>;
  refreshSession: () => Promise<boolean>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

// JWT validation helper
const isTokenExpired = (token: string): boolean => {
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    return payload.exp * 1000 < Date.now();
  } catch {
    return true; // Treat invalid tokens as expired
  }
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();
  const isRefreshing = React.useRef(false);

  const verifySession = useCallback(async () => {
    try {
      const { data: { session }, error } = await supabase.auth.getSession();

      if (error || !session) {
        setUser(null);
        setLoading(false);
        return;
      }

      // Check token expiration
      if (isTokenExpired(session.access_token)) {
        // Try to refresh
        const refreshed = await refreshSession();
        if (!refreshed) {
          setUser(null);
          setLoading(false);
          return;
        }
        // Re-get session after refresh
        const { data: { session: newSession } } = await supabase.auth.getSession();
        if (!newSession) {
          setUser(null);
          setLoading(false);
          return;
        }
        setUser({
          id: newSession.user.id,
          email: newSession.user.email || null,
        });
      } else {
        setUser({
          id: session.user.id,
          email: session.user.email || null,
        });
      }
    } catch (err: any) {
      console.error('Session verification error:', err);
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  const refreshSession = useCallback(async (): Promise<boolean> => {
    if (isRefreshing.current) return false;
    isRefreshing.current = true;

    try {
      const { data, error } = await supabase.auth.refreshSession();
      if (error || !data.session) {
        console.error('Token refresh failed:', error);
        return false;
      }
      return true;
    } catch (err) {
      console.error('Refresh exception:', err);
      return false;
    } finally {
      isRefreshing.current = false;
    }
  }, []);

  const signIn = useCallback(async (email: string, password: string) => {
    try {
      setError(null);
      const { data, error } = await supabase.auth.signInWithPassword({ email, password });

      if (error) return { success: false, error: error.message };
      if (!data.session) return { success: false, error: 'No session returned' };

      // SECURITY: Don't store sensitive data in localStorage
      // JWT is automatically handled by Supabase client via httpOnly cookies when configured
      setUser({
        id: data.session.user.id,
        email: data.session.user.email || null,
      });
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message || 'Sign in failed' };
    }
  }, []);

  const signUp = useCallback(async (email: string, password: string) => {
    try {
      setError(null);
      const { data, error } = await supabase.auth.signUp({ email, password });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message || 'Sign up failed' };
    }
  }, []);

  const signOut = useCallback(async () => {
    try {
      await supabase.auth.signOut();
      setUser(null);
      navigate('/');
    } catch (err) {
      console.error('Sign out error:', err);
    }
  }, [navigate]);

  useEffect(() => {
    verifySession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'TOKEN_REFRESHED') {
        if (session) {
          setUser({
            id: session.user.id,
            email: session.user.email || null,
          });
        }
      } else if (event === 'SIGNED_OUT') {
        setUser(null);
      }
    });
    return () => subscription.unsubscribe();
  }, [verifySession]);

return (
     <AuthContext.Provider value={{ user, loading, error, signIn, signUp, signOut, refreshSession }}>
       {children}
     </AuthContext.Provider>
   );
};

import { useState, useEffect } from 'react';

interface UseScrollAnimationOptions {
  threshold?: number;
  rootMargin?: string;
  triggerOnce?: boolean;
}

export const useScrollAnimation = (options: UseScrollAnimationOptions = {}) => {
  const { threshold = 0.1, rootMargin = '0px', triggerOnce = true } = options;
  const [isVisible, setIsVisible] = useState(false);
  const [elementRef, setElementRef] = useState<HTMLElement | null>(null);

  useEffect(() => {
    const element = elementRef;
    if (!element) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          if (triggerOnce) {
            observer.unobserve(element);
          }
        } else if (!triggerOnce) {
          setIsVisible(false);
        }
      },
      { threshold, rootMargin }
    );

    observer.observe(element);
    return () => observer.disconnect();
  }, [elementRef, threshold, rootMargin, triggerOnce]);

  return { isVisible, elementRef: setElementRef };
};

export default useScrollAnimation;

import { useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { getRequiredKeysForAgent, ApiKeyType } from "../utils/agentKeyRequirements";
import { supabase } from "../utils/supabase";

export interface ApiKeyStatus {
  keyType: ApiKeyType;
  value: string | null;
  isValid: boolean;
  checked: boolean;
}

/**
 * Hook to check if required API keys are configured for an agent
 * and provide actions to open settings.
 */
export function useAgentKeyCheck(agentSlug?: string) {
  const navigate = useNavigate();
  const { user } = useAuth();

  /**
   * Check if all required keys for an agent are present
   */
  const checkKeys = useCallback(
    async (agentIdentifier?: string): Promise<{
      allPresent: boolean;
      missingKeys: ApiKeyType[];
      storedKeys: Record<ApiKeyType, string | null>;
    }> => {
      const slug = agentIdentifier || agentSlug;
      if (!slug) {
        return { allPresent: true, missingKeys: [], storedKeys: {} };
      }

      const requiredKeys = getRequiredKeysForAgent(slug);
      if (requiredKeys.length === 0) {
        return { allPresent: true, missingKeys: [], storedKeys: {} };
      }

      // Fetch stored keys from Supabase (with localStorage fallback)
      const storedKeys: Record<ApiKeyType, string | null> = {} as any;

      for (const keyType of requiredKeys) {
        const value = await getStoredApiKey(keyType);
        storedKeys[keyType] = value;
      }

      const missingKeys = requiredKeys.filter((keyType) => !storedKeys[keyType]);

      return {
        allPresent: missingKeys.length === 0,
        missingKeys,
        storedKeys,
      };
    },
    [agentSlug],
  );

  /**
   * Open the API settings panel
   */
  const openSettings = useCallback(() => {
    navigate("/settings/api");
  }, [navigate]);

  /**
   * Before allowing an action, check keys and show friendly message if missing
   */
  const requireKeys = useCallback(
    async (
      agentIdentifier?: string,
    ): Promise<{
      allowed: boolean;
      missingKeys: ApiKeyType[];
      openSettings: () => void;
    }> => {
      const result = await checkKeys(agentIdentifier);
      return {
        allowed: result.allPresent,
        missingKeys: result.missingKeys,
        openSettings,
      };
    },
    [checkKeys, openSettings],
  );

  return {
    checkKeys,
    requireKeys,
    openSettings,
  };
}

/**
 * Retrieve stored API key for a given type
 * Checks Supabase user_settings table first, then localStorage fallback
 */
export async function getStoredApiKey(keyType: ApiKeyType): Promise<string | null> {
  const storageKey = `agent_api_key_${keyType}`;

  // Try localStorage first (fast, no auth needed)
  try {
    const localValue = localStorage.getItem(storageKey);
    if (localValue) {
      return localValue;
    }
  } catch (e) {
    // localStorage not available
  }

  // Try Supabase if user is authenticated
  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (user) {
      const { data, error } = await supabase
        .from("user_settings")
        .select("settings")
        .eq("user_id", user.id)
        .single();

      if (!error && data?.settings?.[keyType]) {
        return data.settings[keyType];
      }
    }
  } catch (e) {
    console.error("Error fetching API key from Supabase:", e);
  }

  return null;
}

/**
 * Save API key to both localStorage and Supabase
 */
export async function saveApiKey(
  keyType: ApiKeyType,
  value: string,
): Promise<{ success: boolean; error?: string }> {
  const storageKey = `agent_api_key_${keyType}`;

  // Always save to localStorage
  try {
    if (value) {
      localStorage.setItem(storageKey, value);
    } else {
      localStorage.removeItem(storageKey);
    }
  } catch (e) {
    console.error("Error saving to localStorage:", e);
  }

  // Try to sync with Supabase if user is logged in
  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (user) {
      // First, get existing settings
      const { data: existing, error: fetchError } = await supabase
        .from("user_settings")
        .select("settings")
        .eq("user_id", user.id)
        .single();

      if (fetchError && fetchError.code !== "PGRST116") {
        // PGRST116 = no rows returned, that's ok
        console.error("Error fetching existing settings:", fetchError);
      }

      const currentSettings = existing?.settings || {};

      // Update the specific key
      const newSettings = {
        ...currentSettings,
        [keyType]: value,
      };

      // Upsert the settings
      const { error: upsertError } = await supabase
        .from("user_settings")
        .upsert(
          {
            user_id: user.id,
            settings: newSettings,
            updated_at: new Date().toISOString(),
          },
          {
            onConflict: "user_id",
          },
        );

      if (upsertError) {
        console.error("Error saving to Supabase:", upsertError);
        return { success: false, error: upsertError.message };
      }
    }
  } catch (e) {
    console.error("Error syncing with Supabase:", e);
    return { success: false, error: String(e) };
  }

  return { success: true };
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "../utils/supabase";
import { transformApp, ComponentApp } from "../utils/appTransformers";
import { appConfig } from "../config/appConfig";
import { appsData } from "../data/appsData";

// Cache configuration
const APPS_CACHE_KEY = "videoremix_apps_cache";
const APPS_CACHE_TTL = appConfig.CACHE.APPS_TTL;

interface CacheData {
  data: ComponentApp[];
  timestamp: number;
  lastModified: string; // ISO timestamp of last server modification
}

// Cache utility functions
const getCachedApps = (): ComponentApp[] | null => {
  try {
    const cached = localStorage.getItem(APPS_CACHE_KEY);
    if (!cached) return null;

    const cacheData: CacheData = JSON.parse(cached);
    const now = Date.now();

    // Check if cache is still valid
    if (now - cacheData.timestamp > APPS_CACHE_TTL) {
      localStorage.removeItem(APPS_CACHE_KEY);
      return null;
    }

    return cacheData.data;
  } catch (error) {
    console.warn("Error reading apps cache:", error);
    return null;
  }
};

const setCachedApps = (apps: ComponentApp[], lastModified: string): void => {
  try {
    const cacheData: CacheData = {
      data: apps,
      timestamp: Date.now(),
      lastModified,
    };
    localStorage.setItem(APPS_CACHE_KEY, JSON.stringify(cacheData));
  } catch (error) {
    console.warn("Error caching apps data:", error);
  }
};

const clearAppsCache = (): void => {
  try {
    localStorage.removeItem(APPS_CACHE_KEY);
  } catch (error) {
    console.warn("Error clearing apps cache:", error);
  }
};

export const useApps = () => {
  const [apps, setApps] = useState<ComponentApp[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchApps = useCallback(async (forceRefresh = false) => {
    try {
      setLoading(true);
      setError(null);

      // Try to get from cache first (unless force refresh)
      if (!forceRefresh) {
        const cachedApps = getCachedApps();
        if (cachedApps) {
          setApps(cachedApps);
          setLoading(false);
          return;
        }
      }

      const { data, error: supabaseError } = await supabase
        .from("apps")
        .select("*")
        .order("sort_order", { ascending: true });

      if (supabaseError) {
        throw supabaseError;
      }

if (data && data.length > 0) {
        const transformedApps = data.map(transformApp);
        setApps(transformedApps);

// Get the latest modification timestamp for caching
        const latestModified = data.reduce(
          (latest, ai-design-studio) => (ai-design-studio.updated_at > latest ? ai-design-studio.updated_at : latest),
          data[0]?.updated_at || new Date().toISOString(),
        );

        // Cache the transformed data with modification timestamp
        setCachedApps(transformedApps, latestModified);
      } else {
        // Empty result - fall back to local data
        console.log("[useApps] No data from Supabase, falling back to local data...");
        const transformedApps = appsData.map(transformApp);
        setApps(transformedApps);
        setError(null);
      }
    } catch (err) {
      console.error("Error fetching apps from Supabase:", err);
      console.log("Falling back to local apps data...");

      // Fall back to local apps data
      try {
        const transformedApps = appsData.map(transformApp);
        setApps(transformedApps);
        setError(null);
      } catch (fallbackErr) {
        console.error("Error loading local apps data:", fallbackErr);
        setError("Failed to load apps data");
        setApps([]);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  const refetch = useCallback(() => {
    clearAppsCache(); // Clear cache before refetching
    return fetchApps(true);
  }, [fetchApps]);

  useEffect(() => {
    fetchApps();
  }, [fetchApps]);

  return {
    apps,
    loading,
    error,
    refetch,
  };
};

import { useState, useCallback, useRef, useEffect } from 'react';
import { classifyError, withRetry, ClassifiedError, RetryConfig } from '../utils/errorHandling';

/**
 * Async operation states
 */
export interface AsyncState<T> {
  status: 'idle' | 'loading' | 'success' | 'error';
  data: T | null;
  error: ClassifiedError | null;
}

/**
 * Options for async operation
 */
export interface AsyncOptions<T> {
  /** Initial data to use */
  initialData?: T | null;
  /** Retry configuration */
  retryConfig?: Partial<RetryConfig>;
  /** Callback on success */
  onSuccess?: (data: T) => void;
  /** Callback on error */
  onError?: (error: ClassifiedError) => void;
  /** Callback on retry */
  onRetry?: (attempt: number, error: ClassifiedError) => void;
  /** Auto-execute on mount */
  executeOnMount?: boolean;
  /** Prevent duplicate requests */
  preventDuplicates?: boolean;
}

/**
 * Return type for useAsyncOperation
 */
export interface AsyncOperationResult<T, P extends unknown[]> {
  /** Current state */
  state: AsyncState<T>;
  /** Execute the async operation */
  execute: (...params: P) => Promise<T | null>;
  /** Reset to initial state */
  reset: () => void;
  /** Retry the last operation */
  retry: () => Promise<T | null>;
  /** Is currently loading */
  isLoading: boolean;
  /** Is currently retrying */
  isRetrying: boolean;
  /** Has succeeded */
  isSuccess: boolean;
  /** Has errored */
  isError: boolean;
  /** Current retry attempt */
  retryAttempt: number;
}

/**
 * Hook for managing async operations with loading, error, and retry states.
 * Prevents duplicate requests and handles real-world network conditions.
 * 
 * @example
 * ```tsx
 * const { state, execute, isLoading, isError, retry } = useAsyncOperation(
 *   async (userId: string) => {
 *     const { data, error } = await supabase.from('users').select('*').eq('id', userId).single();
 *     if (error) throw error;
 *     return data;
 *   }
 * );
 * 
 * // Execute
 * await execute('user-123');
 * 
 * // Render
 * if (isLoading) return <LoadingSpinner />;
 * if (isError) return <ErrorDisplay error={state.error} onRetry={retry} />;
 * return <div>{state.data.name}</div>;
 * ```
 */
export function useAsyncOperation<T, P extends unknown[] = []>(
  asyncFn: (...params: P) => Promise<T>,
  options: AsyncOptions<T> = {}
): AsyncOperationResult<T, P> {
  const {
    initialData = null,
    retryConfig,
    onSuccess,
    onError,
    onRetry,
    executeOnMount = false,
    preventDuplicates = true,
  } = options;

  const [state, setState] = useState<AsyncState<T>>(() => ({
    status: 'idle',
    data: initialData,
    error: null,
  }));

  const [isRetrying, setIsRetrying] = useState(false);
  const [retryAttempt, setRetryAttempt] = useState(0);

  // Track in-flight requests to prevent duplicates
  // Note: requestIdRef is intentionally incremented in cleanup to cancel in-flight requests on unmount.
  // The ref value changing between render and cleanup is expected behavior for request cancellation.
  const requestIdRef = useRef(0);
  const lastParamsRef = useRef<P | null>(null);
  const isExecutingRef = useRef(false);

  // Cleanup on unmount - cancels any in-flight requests
  useEffect(() => {
    return () => {
      // Intentionally increment to cancel in-flight requests on unmount.
      // The ref value changing is expected behavior for request cancellation.
      // We WANT the latest value to cancel any requests that started before unmount.

      requestIdRef.current++;
      isExecutingRef.current = false;
    };
  }, []);

  const execute = useCallback(
    async (...params: P): Promise<T | null> => {
      // Prevent duplicate requests
      if (preventDuplicates && isExecutingRef.current) {
        console.log('[useAsyncOperation] Preventing duplicate request');
        return null;
      }

      const currentRequestId = ++requestIdRef.current;
      isExecutingRef.current = true;
      lastParamsRef.current = params;

      // Set loading state
      setState(prev => ({
        status: 'loading',
        data: prev.data, // Keep previous data during loading
        error: null,
      }));

      try {
        const result = await withRetry(
          () => asyncFn(...params),
          retryConfig,
          (attempt, error) => {
            // Only update if this is still the current request
            if (currentRequestId === requestIdRef.current) {
              setIsRetrying(true);
              setRetryAttempt(attempt);
              onRetry?.(attempt, error);
            }
          }
        );

        // Check if request was cancelled
        if (currentRequestId !== requestIdRef.current) {
          return null;
        }

        // Success
        setState({
          status: 'success',
          data: result,
          error: null,
        });

        setIsRetrying(false);
        setRetryAttempt(0);
        onSuccess?.(result);

        return result;
      } catch (error) {
        // Check if request was cancelled
        if (currentRequestId !== requestIdRef.current) {
          return null;
        }

        const classifiedError = classifyError(error);

        // Error state
        setState(prev => ({
          status: 'error',
          data: prev.data, // Keep previous data on error
          error: classifiedError,
        }));

        setIsRetrying(false);
        onError?.(classifiedError);

        return null;
      } finally {
        if (currentRequestId === requestIdRef.current) {
          isExecutingRef.current = false;
        }
      }
    },
    [asyncFn, preventDuplicates, retryConfig, onSuccess, onError, onRetry]
  );

  const reset = useCallback(() => {
    requestIdRef.current++; // Cancel any in-flight requests
    isExecutingRef.current = false;
    setState({
      status: 'idle',
      data: initialData,
      error: null,
    });
    setIsRetrying(false);
    setRetryAttempt(0);
  }, [initialData]);

  const retry = useCallback(async (): Promise<T | null> => {
    if (lastParamsRef.current) {
      return execute(...lastParamsRef.current);
    }
    return null;
  }, [execute]);

  // Execute on mount if requested
  useEffect(() => {
    if (executeOnMount) {
      execute(...([] as unknown as P));
    }
  }, [executeOnMount, execute]);

  return {
    state,
    execute,
    reset,
    retry,
    isLoading: state.status === 'loading',
    isRetrying,
    isSuccess: state.status === 'success',
    isError: state.status === 'error',
    retryAttempt,
  };
}

/**
 * Simplified hook for data fetching with automatic loading states.
 * 
 * Uses a ref pattern to avoid stale closure issues with the dependencies array.
 * The result ref is updated on each render to ensure the latest execute function
 * is called when dependencies change, without triggering infinite re-renders.
 * 
 * @param fetchFn - The async function to call for data fetching
 * @param options - Configuration options including dependencies array
 * 
 * @example
 * ```tsx
 * // Basic usage - fetches on mount
 * const { data, isLoading, error, refetch } = useDataFetch(() => fetchUsers());
 * 
 * // With dependencies - refetches when userId changes
 * const { data } = useDataFetch(() => fetchUser(userId), { dependencies: [userId] });
 * ```
 */
export function useDataFetch<T>(
  fetchFn: () => Promise<T>,
  options: Omit<AsyncOptions<T>, 'preventDuplicates'> & { 
    preventDuplicates?: boolean;
    /** Dependencies array - will refetch when these values change */
    dependencies?: unknown[];
  } = {}
): AsyncOperationResult<T, []> & { refetch: () => Promise<T | null> } {
  const { dependencies = [], ...asyncOptions } = options;

  const result = useAsyncOperation(fetchFn, {
    ...asyncOptions,
    executeOnMount: true,
    preventDuplicates: true,
  });

  // Store result in a ref to avoid stale closure issues
  // This allows us to call the latest execute function without adding it to dependencies
  const resultRef = useRef(result);
  resultRef.current = result;

  // Re-fetch when dependencies change
  // Using ref to avoid including result.execute in dependencies (which would cause infinite loops)
  useEffect(() => {
    if (dependencies.length > 0) {
      resultRef.current.execute();
    }

  }, dependencies);

  return {
    ...result,
    refetch: result.execute,
  };
}

/**
 * Hook for mutations (operations that modify data).
 * Includes double-submit prevention by default.
 * 
 * @param mutationFn - The async mutation function
 * @param options - Configuration options
 * 
 * @example
 * ```tsx
 * const { execute, isLoading, canSubmit, isError } = useMutation(
 *   async (data: FormData) => {
 *     return await api.submitForm(data);
 *   }
 * );
 * 
 * // In your form submit handler:
 * <button onClick={() => execute(formData)} disabled={!canSubmit}>
 *   {isLoading ? 'Saving...' : 'Submit'}
 * </button>
 * ```
 */
export function useMutation<T, P extends unknown[] = []>(
  mutationFn: (...params: P) => Promise<T>,
  options: AsyncOptions<T> = {}
): AsyncOperationResult<T, P> & {
  /** Whether the mutation can be executed (not already in progress) */
  canSubmit: boolean;
} {
  const result = useAsyncOperation(mutationFn, {
    ...options,
    preventDuplicates: true, // Always prevent duplicate mutations
  });

  return {
    ...result,
    canSubmit: !result.isLoading,
  };
}

import { useCallback, useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "../utils/supabase";
import { checkAgentKeys, getAgentKeyRequirements, AgentKeyRequirements, AVAILABLE_API_KEYS } from "../utils/agentKeyRequirements";
import { Loader2, AlertCircle, Settings } from "lucide-react";
import { Button } from "../components/ui/button";

/**
 * Hook to check if an agent has all required API keys configured.
 * Provides a banner message and navigation helper if keys are missing.
 */
export function useAgentApiKeys(agentSlug: string) {
  const navigate = useNavigate();

  const checkKeys = useCallback(async (): Promise<{
    hasAllKeys: boolean;
    missingKeys: string[];
    requirements: AgentKeyRequirements;
    storedKeys: Record<string, string>;
  }> => {
    // Get stored keys from Supabase + localStorage
    const storedKeys: Record<string, string> = {};

    // Try Supabase first
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { data } = await supabase
          .from("user_settings")
          .select("api_keys")
          .eq("user_id", user.id)
          .single();

        if (data?.api_keys) {
          Object.assign(storedKeys, data.api_keys);
        }
      }
    } catch (error) {
      console.error("Error fetching keys from Supabase:", error);
    }

    // Merge with localStorage (locally stored keys override if present)
    Object.values(AVAILABLE_API_KEYS).forEach(({ key }) => {
      const localStorageValue = localStorage.getItem(`api_key_${key}`);
      if (localStorageValue) {
        storedKeys[key] = localStorageValue;
      }
    });

    const result = checkAgentKeys(agentSlug, storedKeys);
    const requirements = getAgentKeyRequirements(agentSlug);

    return {
      hasAllKeys: result.hasAllKeys,
      missingKeys: result.missingKeys,
      requirements,
      storedKeys,
    };
  }, [agentSlug]);

  const openApiSettings = useCallback(() => {
    navigate("/settings/api");
  }, [navigate]);

  const getMissingKeyNames = useCallback(
    (missingKeys: string[], requirements: AgentKeyRequirements): string[] => {
      return missingKeys.map((key) => {
        const config = requirements.keysConfig[key] || AVAILABLE_API_KEYS[key];
        return config?.name || key;
      });
    },
    []
  );

  return {
    checkKeys,
    openApiSettings,
    getMissingKeyNames,
  };
}

export default useAgentApiKeys;

import { useEffect, useRef } from "react";

const activeVideos = new Set<HTMLVideoElement>();
const MAX_CONCURRENT_VIDEOS = 5;

export const useVideoManager = (
  videoRef: React.RefObject<HTMLVideoElement>,
) => {
  const isRegistered = useRef(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handlePlay = () => {
      if (activeVideos.size >= MAX_CONCURRENT_VIDEOS) {
        const firstVideo = Array.from(activeVideos)[0];
        if (firstVideo && firstVideo !== video) {
          firstVideo.pause();
          activeVideos.delete(firstVideo);
        }
      }
      activeVideos.add(video);
      isRegistered.current = true;
    };

    const handlePause = () => {
      activeVideos.delete(video);
      isRegistered.current = false;
    };

    const handleEnded = () => {
      activeVideos.delete(video);
      isRegistered.current = false;
    };

    video.addEventListener("play", handlePlay);
    video.addEventListener("pause", handlePause);
    video.addEventListener("ended", handleEnded);

    return () => {
      if (isRegistered.current) {
        activeVideos.delete(video);
      }
      video.removeEventListener("play", handlePlay);
      video.removeEventListener("pause", handlePause);
      video.removeEventListener("ended", handleEnded);
    };
  }, [videoRef]);

  return {
    activeCount: activeVideos.size,
    maxCount: MAX_CONCURRENT_VIDEOS,
  };
};

