  IdentityGraphNode,
  IdentityGraphEdge,
  GeneratedAsset,
  ScanJob,
  ScanEvent,
  IntelligenceProfile,
} from '../types/personalization';

const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY
