// Hook to calculate confidence score
export function useConfidenceScore(profiles: PlatformProfile[]) {
  const [score, setScore] = useState<number>(0);

  useEffect(() => {
    if (!profiles.length) {
      setScore(0);
      return;
    }

    // Calculate weighted confidence score
    const totalScore = profiles.reduce((sum, profile) => {
      const weight = profile.confidence_score || 0.5;
      const platformMultiplier = {
        github: 1.0,
        twitter: 0.9,
        linkedin: 0.95,
        medium: 0.7,
        devto: 0.75,
      }[profile.platform.toLowerCase()] || 0.5;

      return sum + (weight * platformMultiplier);
    }, 0);

    const avgScore = Math.min(100, Math.round((totalScore / profiles.length) * 100));
    setScore(avgScore);
  }, [profiles]);

  return score;
}

// Hook to build identity graph
export function useIdentityGraph(profileId: string | null) {
  const [nodes, setNodes] = useState<IdentityGraphNode[]>([]);
  const [edges, setEdges] = useState<IdentityGraphEdge[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!profileId) return;

    const fetchData = async () => {
      setLoading(true);
      const [nodesRes, edgesRes] = await Promise.all([
        supabase.from('identity_graph_nodes').select('*').eq('profile_id', profileId),
        supabase.from('identity_graph_edges').select('*').eq('source_node_id', profileId),
      ]);

      setNodes(nodesRes.data || []);
      setEdges(edgesRes.data || []);
      setLoading(false);
    };

    fetchData();
  }, [profileId]);

  return { nodes, edges, loading };
}

// Hook to run a full scan job
export function useRunScanJob() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const runScan = useCallback(async (username: string, userId: string) => {
    setLoading(true);
    setError(null);

    try {
      const { data: { session } } = await supabase.auth.getSession();
      const res = await fetch('/api/personalizer/job/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session?.access_token}`,
        },
        body: JSON.stringify({ username, userId }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to create scan job');

      setLoading(false);
      return data.jobId;
    } catch (err: any) {
      setError(err.message);
      setLoading(false);
      return null;
    }
  }, []);

  return { runScan, loading, error };
}

import { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import { supabase } from "../utils/supabase";

export interface DashboardPreferences {
  theme: "dark" | "light";
  layout_density: "compact" | "comfortable";
  widget_order: string[];
  hidden_widgets: string[];
}

const DEFAULT_PREFERENCES: DashboardPreferences = {
  theme: "dark",
  layout_density: "comfortable",
  widget_order: [],
  hidden_widgets: [],
};

export const useDashboardPreferences = () => {
  const { user } = useAuth();
  const [preferences, setPreferences] =
    useState<DashboardPreferences>(DEFAULT_PREFERENCES);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!user) {
      setPreferences(DEFAULT_PREFERENCES);
      setLoading(false);
      return;
    }

    fetchPreferences();
  }, [user]);

  const fetchPreferences = async () => {
    if (!user) return;

    try {
      setLoading(true);
      setError(null);

      const { data, error: fetchError } = await supabase
        .from("user_dashboard_preferences")
        .select("theme, layout_density, widget_order, hidden_widgets")
        .eq("user_id", user.id)
        .maybeSingle();

      if (fetchError) {
        console.error("Error fetching preferences:", fetchError);
        setError(fetchError.message);
        return;
      }

      if (data) {
        setPreferences({
          theme: data.theme || "dark",
          layout_density: data.layout_density || "comfortable",
          widget_order: data.widget_order || [],
          hidden_widgets: data.hidden_widgets || [],
        });
      } else {
        await createDefaultPreferences();
      }
    } catch (err) {
      console.error("Error in fetchPreferences:", err);
      setError("Failed to load preferences");
    } finally {
      setLoading(false);
    }
  };

  const createDefaultPreferences = async () => {
    if (!user) return;

    try {
      const { data, error: insertError } = await supabase
        .from("user_dashboard_preferences")
        .insert({
          user_id: user.id,
          theme: DEFAULT_PREFERENCES.theme,
          layout_density: DEFAULT_PREFERENCES.layout_density,
          widget_order: DEFAULT_PREFERENCES.widget_order,
          hidden_widgets: DEFAULT_PREFERENCES.hidden_widgets,
        })
        .select()
        .single();

      if (insertError) {
        console.error("Error creating default preferences:", insertError);
        return;
      }

      if (data) {
        setPreferences({
          theme: data.theme,
          layout_density: data.layout_density,
          widget_order: data.widget_order || [],
          hidden_widgets: data.hidden_widgets || [],
        });
      }
    } catch (err) {
      console.error("Error in createDefaultPreferences:", err);
    }
  };

  const updatePreferences = async (updates: Partial<DashboardPreferences>) => {
    if (!user) return;

    try {
      setError(null);
      const newPreferences = { ...preferences, ...updates };

      const { error: updateError } = await supabase
        .from("user_dashboard_preferences")
        .update({
          theme: newPreferences.theme,
          layout_density: newPreferences.layout_density,
          widget_order: newPreferences.widget_order,
          hidden_widgets: newPreferences.hidden_widgets,
        })
        .eq("user_id", user.id);

      if (updateError) {
        console.error("Error updating preferences:", updateError);
        setError(updateError.message);
        return;
      }

      setPreferences(newPreferences);
    } catch (err) {
      console.error("Error in updatePreferences:", err);
      setError("Failed to update preferences");
    }
  };

  const setTheme = (theme: "dark" | "light") => {
    updatePreferences({ theme });
  };

  const setLayoutDensity = (density: "compact" | "comfortable") => {
    updatePreferences({ layout_density: density });
  };

  const toggleWidget = (widgetId: string) => {
    const isHidden = preferences.hidden_widgets.includes(widgetId);
    const newHiddenWidgets = isHidden
      ? preferences.hidden_widgets.filter((id) => id !== widgetId)
      : [...preferences.hidden_widgets, widgetId];

    updatePreferences({ hidden_widgets: newHiddenWidgets });
  };

  const reorderWidgets = (newOrder: string[]) => {
    updatePreferences({ widget_order: newOrder });
  };

  const resetPreferences = () => {
    updatePreferences(DEFAULT_PREFERENCES);
  };

  return {
    preferences,
    loading,
    error,
    setTheme,
    setLayoutDensity,
    toggleWidget,
    reorderWidgets,
    resetPreferences,
    updatePreferences,
  };
};

import { useState, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Goal, Niche, OnboardingAnswers } from '../types/onboarding';

export type WizardStep = 1 | 2 | 3 | 4 | 5;

export interface UseOnboardingReturn {
  step: WizardStep;
  answers: Partial<OnboardingAnswers>;
  setGoals: (goals: Goal[]) => void;
  setNiche: (niche: Niche) => void;
  setSelectedCategories: (categories: string[]) => void;
  nextStep: () => void;
  prevStep: () => void;
  completeOnboarding: () => Promise<void>;
}

export const useOnboarding = (): UseOnboardingReturn => {
  const { user, updateProfile } = useAuth();
  const navigate = useNavigate();

  const [step, setStep] = useState<WizardStep>(1);
  const [answers, setAnswers] = useState<Partial<OnboardingAnswers>>({
    goals: [],
    selectedCategories: [],
  });

  const setGoals = useCallback((goals: Goal[]) => {
    setAnswers(prev => ({ ...prev, goals }));
  }, []);

  const setNiche = useCallback((niche: Niche) => {
    setAnswers(prev => ({ ...prev, niche }));
  }, []);

  const setSelectedCategories = useCallback((selectedCategories: string[]) => {
    setAnswers(prev => ({ ...prev, selectedCategories }));
  }, []);

  const nextStep = useCallback(() => {
    setStep(prev => Math.min(5, (prev + 1) as WizardStep));
  }, []);

  const prevStep = useCallback(() => {
    setStep(prev => Math.max(1, (prev - 1) as WizardStep));
  }, []);

  const completeOnboarding = useCallback(async () => {
    if (!user) return;

    try {
      await updateProfile({
        onboarding: answers,
        onboarding_completed: true,
      });

      // Award onboarding achievement via Supabase
      const { supabase } = await import('../utils/supabase');
      await supabase.rpc('award_achievement', {
        p_achievement_type: 'onboarding_completed',
        p_metadata: { completed_at: new Date().toISOString() },
      });

      navigate('/dashboard', { replace: true });
    } catch (error) {
      console.error('Failed to complete onboarding:', error);
      throw error;
    }
  }, [user, answers, updateProfile, navigate]);

  return useMemo(() => ({
    step,
    answers,
    setGoals,
    setNiche,
    setSelectedCategories,
    nextStep,
    prevStep,
    completeOnboarding,
  }), [step, answers, setGoals, setNiche, setSelectedCategories, nextStep, prevStep, completeOnboarding]);
};

import { useState, useEffect, useCallback } from "react";
import { VideoService } from "../services/videoService";
