// Fallback images for when no custom thumbnail is available
const FALLBACK_IMAGES = [
  "https://images.unsplash.com/photo-1616469829941-c7200edec809?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  "https://images.unsplash.com/photo-1551434678-e076c223a692?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  "https://images.unsplash.com/photo-1522071820081-009f0129c71c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
  "https://images.unsplash.com/photo-1559136555-9303baea8ebd?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80",
];

// Get icon name for ai-design-studio (used by LazyIcon component)
export const getIconNameForApp = (ai-design-studio: DatabaseApp): string => {
  // Check specific ai-design-studio slug first, then fall back to category
  return ai-design-studio.slug || ai-design-studio.category || "ai";
};

// Transform database ai-design-studio to component ai-design-studio (pure data transformation)
export const transformApp = (dbApp: DatabaseApp): ComponentApp => {
  // URL Priority Order:
  // 1. Database custom_domain (highest priority)
  // 2. Database netlify_url
  // 3. Centralized APP_URLS config (from appUrls.ts)
  // 4. Fallback to internal route
  let appUrl: string;

  if (dbApp.custom_domain) {
    appUrl = dbApp.custom_domain;
  } else if (dbApp.netlify_url) {
    appUrl = dbApp.netlify_url;
  } else {
    // Use centralized config, which will return internal route if not found
    appUrl = getCentralizedAppUrl(dbApp.slug);
  }

  // Image URL Priority Order:
  // 1. Custom AI-generated thumbnail from APP_THUMBNAILS (new SVG thumbnails)
  // 2. Database image field
  // 3. Fallback to curated Unsplash images
  const customThumbnail = getAppThumbnail(dbApp.slug);
  const appImage = dbApp.image;

  let imageUrl: string;
  if (customThumbnail) {
    // Use our custom SVG thumbnail
    imageUrl = customThumbnail;
  } else if (appImage) {
    imageUrl = appImage;
  } else {
    // Fallback to a deterministic Unsplash image based on slug
    const fallbackIndex = dbApp.slug.charCodeAt(0) % FALLBACK_IMAGES.length;
    imageUrl = FALLBACK_IMAGES[fallbackIndex];
  }

  return {
    id: dbApp.slug,
    name: dbApp.name,
    description: dbApp.description || "",
    category: dbApp.category,
    iconName: getIconNameForApp(dbApp),
    image: imageUrl,
    isActive: dbApp.is_active,
    isPublic: dbApp.is_public,
    popular: dbApp.popular || dbApp.is_featured,
    new: dbApp.new || false,
    comingSoon: dbApp.coming_soon || false,
    url: appUrl,
    group: dbApp.group || "uncategorized",
  };
};

import { createClient } from '@supabase/supabase-js';

export interface ImageGenerationRequest {
  appId: string;
  appName: string;
  description: string;
  category: string;
  keyFeatures: string[];
  targetSize: { width: number; height: number };
}

export interface GeneratedImage {
  url: string;
  alt: string;
  prompt: string;
  metadata: {
    appId: string;
    category: string;
    generatedAt: string;
    model: string;
    quality: string;
  };
}

export class AIImageGenerator {
  private openaiApiKey: string;
  private supabase: any;

  constructor() {
    this.openaiApiKey = process.env.OPENAI_API_KEY!;
    // Use service role key for storage operations to bypass RLS
    this.supabase = createClient(
      process.env.VITE_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.VITE_SUPABASE_ANON_KEY!
    );
  }

  async generateAppThumbnail(request: ImageGenerationRequest): Promise<GeneratedImage> {
    const prompt = this.buildPrompt(request);

    try {
      console.log(`🎨 Generating thumbnail for ${request.appName}...`);

      const response = await fetch('https://api.openai.com/v1/images/generations', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.openaiApiKey}`,
        },
        body: JSON.stringify({
          prompt: prompt,
          n: 1,
          size: '1024x1024', // Best quality for thumbnails
          response_format: 'url',
        }),
      });

      if (!response.ok) {
        const error = await response.text();
        throw new Error(`OpenAI API error: ${response.status} ${error}`);
      }

      const data = await response.json();

      if (!data.data || !data.data[0] || !data.data[0].url) {
        throw new Error('Invalid response from OpenAI API');
      }

      // Download and store the image
      const imageUrl = data.data[0].url;
      const storedUrl = await this.downloadAndStoreImage(imageUrl, request.appId);

      return {
        url: storedUrl,
        alt: `${request.appName} - ${request.description}`,
        prompt: prompt,
        metadata: {
          appId: request.appId,
          category: request.category,
          generatedAt: new Date().toISOString(),
          model: 'dall-e-3',
          quality: 'hd'
        },
      };
    } catch (error) {
      console.error('Image generation failed:', error);
      throw new Error(`Failed to generate image for ${request.appName}: ${error.message}`);
    }
  }

  private buildPrompt(request: ImageGenerationRequest): string {
    const categoryPrompts = {
      video: 'professional video editing software interface, cinematic lighting, modern UI design',
      'ai-image': 'digital art creation tools interface, vibrant color palette, creative workspace',
      branding: 'brand identity design workspace, clean and professional, corporate design tools',
      personalizer: 'user profile customization interface, personalized dashboard, modern UX design',
      creative: 'creative workspace with design tools, artistic composition, innovative interface',
      'lead-gen': 'sales funnel visualization dashboard, conversion metrics interface, business analytics'
    };

    const categoryStyle = categoryPrompts[request.category] || 'modern software interface, clean design';

    return `Create a realistic, professional software interface thumbnail for "${request.appName}" - ${request.description}.

Key features to visualize: ${request.keyFeatures.join(', ')}

Style requirements:
- ${categoryStyle}
- Professional, modern UI design
- Clean, minimal interface
- High-quality, realistic rendering
- Software application screenshot style
- No text overlays except functional UI elements
- 4K quality, photorealistic, professional grade
- Focus on functionality and user experience
- Modern design trends, sleek and intuitive

The image should look like a real software application interface that users would want to use.`;
  }

  private async downloadAndStoreImage(imageUrl: string, appId: string): Promise<string> {
    try {
      console.log(`📥 Downloading image for ${appId}...`);

      const response = await fetch(imageUrl);
      if (!response.ok) {
        throw new Error(`Failed to download image: ${response.status}`);
      }

      const imageBlob = await response.blob();

      // Convert to buffer for Supabase storage
      const arrayBuffer = await imageBlob.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      // Upload to Supabase storage
      const fileName = `thumbnails/${appId}-ai-thumbnail-${Date.now()}.png`;

      const { data, error } = await this.supabase.storage
        .from('ai-design-studio-assets')
        .upload(fileName, buffer, {
          contentType: 'image/png',
          upsert: true
        });

      if (error) {
        console.error('Supabase upload error:', error);
        throw new Error(`Failed to store image: ${error.message}`);
      }

      // Get public URL
      const { data: publicUrlData } = this.supabase.storage
        .from('ai-design-studio-assets')
        .getPublicUrl(fileName);

      console.log(`✅ Stored image: ${publicUrlData.publicUrl}`);
      return publicUrlData.publicUrl;

    } catch (error) {
      console.error('Image storage failed:', error);
      throw new Error(`Failed to store image: ${error.message}`);
    }
  }

  async generateBatch(requests: ImageGenerationRequest[]): Promise<GeneratedImage[]> {
    const results: GeneratedImage[] = [];

    // Process in smaller batches to avoid rate limits
    const batchSize = 3; // OpenAI allows 5 per minute for DALL-E 3

    for (let i = 0; i < requests.length; i += batchSize) {
      const batch = requests.slice(i, i + batchSize);
      console.log(`\n🔄 Processing batch ${Math.floor(i/batchSize) + 1}: ${batch.length} images`);

      const batchPromises = batch.map(request => this.generateAppThumbnail(request));
      const batchResults = await Promise.allSettled(batchPromises);

      batchResults.forEach((result, index) => {
        if (result.status === 'fulfilled') {
          results.push(result.value);
        } else {
          console.error(`❌ Failed to generate image for ${batch[index].appName}:`, result.reason);
        }
      });

      // Rate limiting - wait 20 seconds between batches (OpenAI allows ~5 images per minute)
      if (i + batchSize < requests.length) {
        console.log('⏱️  Waiting 20 seconds for rate limit...');
        await new Promise(resolve => setTimeout(resolve, 20000));
      }
    }

    return results;
  }

  async testConnection(): Promise<boolean> {
    try {
      const testPrompt = "A simple blue square on a white background, minimal, clean design";

      const response = await fetch('https://api.openai.com/v1/images/generations', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.openaiApiKey}`,
        },
        body: JSON.stringify({
          prompt: testPrompt,
          n: 1,
          size: '256x256',
          response_format: 'url',
        }),
      });

      return response.ok;
    } catch (error) {
      console.error('AI Image API test failed:', error);
      return false;
    }
  }
}

/**
 * Client-Side Rate Limiter
 * Prevents rapid button clicks and API abuse
 */

interface RateLimitConfig {
  /** Maximum number of attempts allowed within the window */
  maxAttempts: number;
  /** Time window in milliseconds */
  windowMs: number;
  /** Optional callback when rate limit is exceeded */
  onRateLimit?: (key: string, attempts: number) => void;
}

interface RateLimitEntry {
  count: number;
  resetTime: number;
}

// In-memory store for rate limiting
const rateLimitStore = new Map<string, RateLimitEntry>();

/**
 * Check if an action is rate limited
 * @param key - Unique key for the action (e.g., 'button-click', 'api-call')
 * @param config - Rate limit configuration
 * @returns true if action is allowed, false if rate limited
 */
export function isAllowed(
  key: string,
  config: RateLimitConfig
): boolean {
  const now = Date.now();
  const entry = rateLimitStore.get(key);

  if (!entry || now > entry.resetTime) {
    // First attempt or window expired
    rateLimitStore.set(key, {
      count: 1,
      resetTime: now + config.windowMs,
    });
    return true;
  }

  if (entry.count >= config.maxAttempts) {
    // Rate limit exceeded
    if (config.onRateLimit) {
      config.onRateLimit(key, entry.count);
    }
    return false;
  }

  // Increment counter
  entry.count++;
  rateLimitStore.set(key, entry);
  return true;
}

/**
 * Rate-limited wrapper for functions
 * @param key - Unique key for the action
 * @param fn - Function to call if not rate limited
 * @param config - Rate limit configuration
 */
export function withRateLimit<T extends (...args: any[]) => any>(
  key: string,
  fn: T,
  config: RateLimitConfig
): ((...args: Parameters<T>) => ReturnType<T> | null) {
  return ((...args: Parameters<T>) => {
    if (!isAllowed(key, config)) {
      console.warn(`Rate limit exceeded for key: ${key}`);
      return null;
    }
    return fn(...args);
  }) as (...args: Parameters<T>) => ReturnType<T> | null;
}

/**
 * React hook for rate limiting button clicks
 * @param key - Unique key for the action
 * @param config - Rate limit configuration
 */
export function useRateLimit(
  key: string,
  config: RateLimitConfig
): { isAllowed: () => boolean; reset: () => void } {
  const checkAllowed = () => isAllowed(key, config);

  const reset = () => {
    rateLimitStore.delete(key);
  };

  return { isAllowed: checkAllowed, reset };
}

/**
 * Clean up old entries to prevent memory leaks
 * Call this periodically or on page unload
 */
export function cleanupRateLimit(): void {
  const now = Date.now();
  let cleaned = 0;

  for (const [key, entry] of rateLimitStore.entries()) {
    if (now > entry.resetTime) {
      rateLimitStore.delete(key);
      cleaned++;
    }
  }

  if (cleaned > 0) {
    console.log(`Cleaned ${cleaned} expired rate limit entries`);
  }
}

// Auto-cleanup every 5 minutes
if (typeof window !== 'undefined') {
  setInterval(() => {
    cleanupRateLimit();
  }, 5 * 60 * 1000);

  // Cleanup on page unload
  window.addEventListener('beforeunload', () => {
    cleanupRateLimit();
  });
}

/**
 * 🔐 DOMAIN GUARD - Request Validation
 *
 * Protects API keys by validating requests come from allowed domains.
 * This compensates for exposed keys by restricting where they can be used.
 *
 * IMPORTANT: This is client-side validation only. For complete protection,
 * also configure API key restrictions in:
 * - OpenAI: https://platform.openai.com/docs/api-reference/authentication
 * - Supabase: Dashboard → Settings → API → URL and Key Restrictions
 * - Stripe: Dashboard → Developers → API Keys → Restricted keys
 */

interface DomainConfig {
  allowedDomains: string[];
  blockedPatterns: RegExp[];
  enableLogging: boolean;
}

interface ValidationResult {
  valid: boolean;
  reason?: string;
  severity: "low" | "medium" | "high" | "critical";
}

// Configuration - Update these with your production domains
const config: DomainConfig = {
  // Allowed domains (include localhost for development)
  allowedDomains: [
    "localhost:5173",
    "localhost:3000",
    "videoremix.vip2.netlify.ai-design-studio",
    "videoremix.vip2.vercel.ai-design-studio",
    "videoremix.vip",
    "www.videoremix.vip",
  ],

  // Block suspicious patterns
  blockedPatterns: [
    /iframe\.zh/, // Suspicious Chinese iframe
    /evil\.js/, // Known malicious pattern
    /crypto-miner/, // Crypto mining scripts
    /\.xyz\/.*\.js/, // Suspicious TLD patterns
    /data:text\/html/, // Data URI attack vector
  ],

  // Enable security logging (disable in production to avoid noise)
  enableLogging: import.meta.env.DEV,
};

// Known malicious domains (expand this list)
const KNOWN_MALICIOUS_DOMAINS = new Set([
  "iframe.zhiframe.com",
  "cdn.jsdelivr.net", // Sometimes used for supply chain attacks
  "unpkg.com", // Sometimes used for supply chain attacks
]);

/**
 * Validate the current origin against allowed domains
 */
export function validateOrigin(): ValidationResult {
  const origin = window.location.origin;
  const hostname = window.location.hostname;

  // Check for localhost (development)
  if (hostname === "localhost" || hostname === "127.0.0.1") {
    if (config.enableLogging) {
      console.log("🔒 DomainGuard: Local development detected");
    }
    return { valid: true, severity: "low" };
  }

  // Check if domain is in allowed list
  const isAllowed = config.allowedDomains.some((domain) => {
    // Exact match
    if (origin === domain || hostname === domain) {
      return true;
    }
    // Subdomain match (e.g., "ai-design-studio.videoremix.vip" matches "videoremix.vip")
    if (domain.startsWith("*.") && hostname.endsWith(domain.slice(1))) {
      return true;
    }
    // Wildcard match
    if (domain === "*") {
      return true;
    }
    return false;
  });

  if (!isAllowed) {
    const reason = `Unauthorized domain: ${origin}`;
    if (config.enableLogging) {
      console.warn("🔒 DomainGuard BLOCKED:", reason);
    }
    return {
      valid: false,
      reason,
      severity: "high",
    };
  }

  if (config.enableLogging) {
    console.log("🔒 DomainGuard: Valid origin:", origin);
  }

  return { valid: true, severity: "low" };
}

/**
 * Check for suspicious patterns in the page
 */
export function detectSuspiciousPatterns(): ValidationResult {
  // Check for iframes with suspicious sources
  const iframes = document.querySelectorAll("iframe[src]");
  for (const iframe of iframes) {
    const src = iframe.getAttribute("src") || "";

    for (const pattern of config.blockedPatterns) {
      if (pattern.test(src)) {
        const reason = `Suspicious iframe detected: ${src}`;
        console.error("🔒 DomainGuard:", reason);
        return {
          valid: false,
          reason,
          severity: "critical",
        };
      }
    }
  }

  // Check for known malicious domains
  const allSources = [
    ...Array.from(document.querySelectorAll("script[src]")).map((s) =>
      s.getAttribute("src"),
    ),
    ...Array.from(document.querySelectorAll("iframe[src]")).map((s) =>
      s.getAttribute("src"),
    ),
    ...Array.from(document.querySelectorAll('link[rel="stylesheet"]')).map(
      (s) => s.getAttribute("href"),
    ),
  ];

  for (const source of allSources) {
    if (source) {
      for (const malicious of KNOWN_MALICIOUS_DOMAINS) {
        if (source.includes(malicious)) {
          const reason = `Known malicious domain detected: ${source}`;
          console.error("🔒 DomainGuard:", reason);
          return {
            valid: false,
            reason,
            severity: "critical",
          };
        }
      }
    }
  }

  return { valid: true, severity: "low" };
}

/**
 * Validate all outgoing requests (can be used as a middleware)
 */
export function validateOutgoingRequest(url: string): ValidationResult {
  // Check if URL is from allowed domains
  try {
    const urlObj = new URL(url);
    const hostname = urlObj.hostname;

    // Allow same-origin requests
    if (hostname === window.location.hostname) {
      return { valid: true, severity: "low" };
    }

    // Check allowed API domains
    const allowedApiDomains = [
      "bzxohkrxcwodllketcpz.supabase.co",
      "api.openai.com",
      "api.stripe.com",
      "generativelanguage.googleapis.com",
      "api.mixpanel.com",
      "api.segment.io",
    ];

    const isAllowedApi = allowedApiDomains.some((domain) => {
      return hostname === domain || hostname.endsWith("." + domain);
    });

    if (!isAllowedApi) {
      const reason = `Request to unauthorized domain: ${hostname}`;
      return {
        valid: false,
        reason,
        severity: "medium",
      };
    }
  } catch {
    return {
      valid: false,
      reason: "Invalid URL format",
      severity: "medium",
    };
  }

  return { valid: true, severity: "low" };
}

/**
 * Get security report
 */
export function getSecurityReport(): {
  originValid: ValidationResult;
  patternsValid: ValidationResult;
  allValid: boolean;
} {
  const originValid = validateOrigin();
  const patternsValid = detectSuspiciousPatterns();

  return {
    originValid,
    patternsValid,
    allValid: originValid.valid && patternsValid.valid,
  };
}

// Export configuration for external modification
export function updateDomainConfig(newConfig: Partial<DomainConfig>): void {
  Object.assign(config, newConfig);
}

export function addAllowedDomain(domain: string): void {
  if (!config.allowedDomains.includes(domain)) {
    config.allowedDomains.push(domain);
  }
}

export function blockDomain(pattern: RegExp): void {
  config.blockedPatterns.push(pattern);
}

// Auto-run security check on import (in production, make this optional)
if (import.meta.env.PROD) {
  const report = getSecurityReport();
  if (!report.allValid) {
    console.error("🔒 Security Alert: Invalid security configuration detected");
    // You could block the ai-design-studio here if desired:
