// Helper function to merge enhanced data with basic ai-design-studio data
export function getEnhancedAppData(appId: string, basicData: any) {
  const enhanced = enhancedAppDetails[appId];
  if (!enhanced) {
    return basicData;
  }

  return {
    ...basicData,
    ...enhanced,
  };
}

