const getAllFeatures = () => {
  // First, normalize the main featuresData
  const normalizedMainFeatures = featuresData.map((feature) => ({
    id: feature.id,
    title: feature.title,
    shortDescription: feature.shortDescription,
    icon: feature.icon,
    image: feature.image,
    category: feature.id.includes("ai")
      ? "ai"
      : feature.id.includes("template")
        ? "templates"
        : feature.id.includes("repurposing")
          ? "workflow"
          : feature.id.includes("caption")
            ? "ai"
            : feature.id.includes("collaboration")
              ? "collaboration"
              : "workflow",
    tags: feature.keyPoints.map((point) => point.toLowerCase().split(" ")[0]),
  }));

  // Then add the additional features
  return [...normalizedMainFeatures, ...additionalFeatures];
};

