import React, { useState, useEffect } from "react";
import { Helmet } from "react-helmet-async";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import {
  User,
  Mail,
  Edit,
  Save,
  X,
  AlertCircle,
  CheckCircle,
  ShoppingBag,
  Calendar,
  DollarSign,
  CreditCard,
  Package,
  Loader,
  Globe,
  Building,
} from "lucide-react";
import { useAuth } from "../context/AuthContext";
import {
  purchaseService,
  PurchaseWithProduct,
} from "../services/purchaseService";

const ProfilePage: React.FC = () => {
  const { user, updateProfile } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    first_name: user?.user_metadata?.first_name || "",
    last_name: user?.user_metadata?.last_name || "",
    bio: user?.user_metadata?.bio || "",
    company: user?.user_metadata?.company || "",
    website: user?.user_metadata?.website || "",
  });
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [purchases, setPurchases] = useState<PurchaseWithProduct[]>([]);
  const [purchasesLoading, setPurchasesLoading] = useState(true);
  const [purchasesError, setPurchasesError] = useState<string | null>(null);

  const handleInputChange =
    (field: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    };

  const handleSave = async () => {
    setError(null);
    setSuccess(null);
    setLoading(true);

    try {
      const { error } = await updateProfile({
        first_name: formData.first_name,
        last_name: formData.last_name,
        bio: formData.bio,
        company: formData.company,
        website: formData.website,
      });

      if (error) {
        setError(error.message);
      } else {
        setSuccess("Profile updated successfully!");
        setIsEditing(false);
      }
    } catch (err) {
      setError("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setFormData({
      first_name: user?.user_metadata?.first_name || "",
      last_name: user?.user_metadata?.last_name || "",
      bio: user?.user_metadata?.bio || "",
      company: user?.user_metadata?.company || "",
      website: user?.user_metadata?.website || "",
    });
    setIsEditing(false);
    setError(null);
    setSuccess(null);
  };

  useEffect(() => {
    const fetchPurchases = async () => {
      if (!user?.id) {
        setPurchasesLoading(false);
        return;
      }

      try {
        setPurchasesLoading(true);
        setPurchasesError(null);
        const data = await purchaseService.getUserPurchasesWithProducts(
          user.id,
        );
        setPurchases(data);
      } catch (err) {
        console.error("Error fetching purchases:", err);
        setPurchasesError("Failed to load purchase history");
      } finally {
        setPurchasesLoading(false);
      }
    };

    fetchPurchases();
  }, [user?.id]);

  const getPlatformBadgeColor = (platform: string) => {
    switch (platform.toLowerCase()) {
      case "stripe":
        return "bg-blue-500/20 text-blue-400 border-blue-500/30";
      case "paypal":
        return "bg-blue-600/20 text-blue-300 border-blue-600/30";
      case "paykickstart":
        return "bg-green-500/20 text-green-400 border-green-500/30";
      case "zaxxa":
        return "bg-purple-500/20 text-purple-400 border-purple-500/30";
      default:
        return "bg-gray-500/20 text-gray-400 border-gray-500/30";
    }
  };

  const getStatusBadgeColor = (status: string) => {
    switch (status.toLowerCase()) {
      case "completed":
        return "bg-green-500/20 text-green-400 border-green-500/30";
      case "pending":
        return "bg-yellow-500/20 text-yellow-400 border-yellow-500/30";
      case "refunded":
        return "bg-red-500/20 text-red-400 border-red-500/30";
      case "failed":
        return "bg-red-500/20 text-red-400 border-red-500/30";
      default:
        return "bg-gray-500/20 text-gray-400 border-gray-500/30";
    }
  };

  const getProductTypeBadgeColor = (productType?: string) => {
    if (!productType) return "bg-gray-500/20 text-gray-400 border-gray-500/30";
    return productType === "subscription"
      ? "bg-orange-500/20 text-orange-400 border-orange-500/30"
      : "bg-teal-500/20 text-teal-400 border-teal-500/30";
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="text-white">Please sign in to view your profile.</div>
      </div>
    );
  }

  return (
    <>
