                                    </span>
                                  )}
                                  {purchase.is_subscription &&
                                    !purchase.product?.product_type && (
                                      <span className="px-3 py-1 rounded-full text-xs font-medium border bg-orange-500/20 text-orange-400 border-orange-500/30">
