                            </div>
                            <div className="flex items-center gap-2 text-gray-400 text-sm">
                              <Calendar className="h-4 w-4" />
                              <span>
                                {new Date(
                                  purchase.purchase_date,
                                ).toLocaleDateString()}
                              </span>
                            </div>
                            <div className="flex items-center gap-2 text-gray-500 text-xs">
                              <CreditCard className="h-3 w-3" />
