                    <div className="space-y-2">
                      <Label htmlFor="select_analysis_type">Select Analysis Type</Label>
                      <Textarea
                        id="select_analysis_type"
                        rows={3}
                        placeholder=""
                        className="bg-gray-900/50 border-gray-600"
