    e.preventDefault();
    if (!formData.enter_blog_url.trim()) {
      setError("Please enter a blog URL");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/dashboard-designer-ai-`, {
