          >
            <SmartInput
              label="Blog URL"
              name="enter_blog_url"
              type="url"
              value={formData.enter_blog_url}
              onChange={(val) => setFormData({ ...formData, enter_blog_url: val })}
              placeholder="https://example.com/blog/your-article"
              helperText="Paste the full URL of the blog post you want to convert"
              required
            />
          </FormSection>

          {error && (
            <ErrorMessage
