    setGeminiApiKey("");
    setAge("");
    setHeightCm("");
    setWeightKg("");
    setSex("male");
    setActivityLevel("moderate");
    setDietaryPreferences("none");
    setFitnessGoals("general_health");
    setQuery("");
    setResult(null);
    setError(null);
