                  value={geminiApiKey}
                  onChange={setGeminiApiKey}
                  type="password"
                  placeholder="AIza... (required for health analysis)"
                  helperText="Get your Gemini API key from aistudio.google.com"
                  required
                />

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <SmartInput
                    label="Age *"
                    name="age"
                    value={age}
                    onChange={setAge}
                    type="number"
