const AiBreakupRecoveryAgentPage: React.FC = () => {
  const { user } = useAuth();
  const [file, setFile] = useState<File | null>(null);
  const [formData, setFormData] = useState({ 
    enter_your_gemini_api_key: "", 
    how_are_you_feeling_what_happened: "", 
    upload_screenshots_of_your_chats_optional: "" 
  });
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('ai-breakup-recovery-state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setFormData(prev => ({ ...prev, ...parsed }));
      } catch {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('ai-breakup-recovery-state', JSON.stringify({ ...formData }));
  }, [formData]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) {
      setFile(e.target.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) {
        setError('Please sign in to use this app.');
        setLoading(false);
        return;
      }

      const runInput: Record<string, unknown> = { situation: formData.how_are_you_feeling_what_happened };
      if (file) {
        runInput.images = [file];
      }

      const res = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/run-app`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${session.access_token}`,
          'Content-Type': 'application/json',
          'X-App-Id': 'ai-breakup-recovery-agent',
          'X-Tenant-Id': (user as any)?.tenantId || undefined,
        },
        body: JSON.stringify({ input: runInput }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || data.message || 'Failed');
      setResult(data);
      localStorage.removeItem('ai-breakup-recovery-state');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
