                  </div>
                </FormSection>

                <FormSection title="API Configuration" description="Enter your Gemini API key">
                  <ApiKeyInput
                    label="Gemini API Key"
                    name="enter_your_gemini_api_key"
                    value={formData.enter_your_gemini_api_key}
