import { SmartTextarea } from "@/components/agent-ui/SmartTextarea";
import { ActionButton } from "@/components/agent-ui/ActionButton";
import { EmptyState } from "@/components/agent-ui/EmptyState";
import { FileUploadZone } from "@/components/agent-ui/FileUploadZone";
import { ApiKeyInput } from "@/components/agent-ui/ApiKeyInput";

const Ag2AdaptiveResearchTeamPage: React.FC = () => {
  const { user } = useAuth();
  const [file, setFile] = useState<File | null>(null);
  const [textValues, setTextValues] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('ag2-research-form-data');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setTextValues(parsed.textValues || {});
      } catch {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('ag2-research-form-data', JSON.stringify({ textValues }));
  }, [textValues]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) setFile(e.target.files[0]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) {
      setError('Please upload a file');
      return;
    }
    if (!textValues.research_question?.trim()) {
      setError('Please enter a research question');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('openai_api_key', textValues.openai_api_key || '');
      formData.append('model', textValues.model || '');
      formData.append('upload_pdfs_or_text_files', textValues.upload_pdfs_or_text_files || '');
      formData.append('research_question', textValues.research_question || '');
      const res = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/pdf-business-assistant`, {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed');
      setResult(data);
      localStorage.removeItem('ag2-research-form-data');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const isFormValid = file && textValues.research_question?.trim();

  return (
    <>
      <Helmet>
        <title>AG2 Adaptive Research Team - VideoRemix.vip</title>
        <meta name="description" content="Multi-agent research team that adapts to your research questions." />
      </Helmet>
      <main className="pt-24 pb-20">
        <div className="container mx-auto px-4 max-w-3xl">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="text-center mb-12">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-blue-600 to-purple-500 rounded-3xl mb-6">
              <Upload className="h-10 w-10 text-white" />
            </div>
            <h1 className="text-4xl font-bold mb-4">AG2 Adaptive Research Team</h1>
            <p className="text-xl text-gray-400">AI-powered multi-agent research with adaptive reasoning</p>
          </motion.div>

          <Card className="bg-gray-800/50 border-gray-700 mb-8">
            <CardHeader><CardTitle>Upload & Configure</CardTitle></CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">

                <div className="space-y-2">
                  <label htmlFor="file" className="text-sm font-medium text-gray-200">
                    Upload File <span className="text-red-500">*</span>
                  </label>
                  <FileUploadZone
                    accept=".pdf,.txt,.docx"
                    maxSize={10 * 1024 * 1024}
                    onFileSelect={setFile}
                    selectedFile={file}
                    helperText="Upload research materials (PDF, TXT, or DOCX up to 10MB)"
                  />
                </div>

                <div className="space-y-2">
                  <ApiKeyInput
                    label="OpenAI API Key"
                    value={textValues.openai_api_key || ''}
                    onChange={(val) => setTextValues(prev => ({ ...prev, openai_api_key: val }))}
                    helperText="Your API key is stored locally and never sent to our servers"
                    required={false}
                  />
                </div>

                <div className="space-y-2">
                  <SmartInput
                    label="Model"
                    name="model"
                    type="text"
                    value={textValues.model || ''}
                    onChange={(val) => setTextValues(prev => ({ ...prev, model: val }))}
                    placeholder="gpt-4o, gpt-4-turbo, gpt-3.5-turbo"
                    helperText="OpenAI model to use for analysis (defaults to gpt-4o)"
                    required={false}
                  />
                </div>

                <div className="space-y-2">
                  <SmartTextarea
                    label="Research question"
                    name="research_question"
                    value={textValues.research_question || ''}
                    onChange={(val) => setTextValues(prev => ({ ...prev, research_question: val }))}
                    placeholder="What specific insights are you looking for from this research material? e.g., 'Identify the main论点 and supporting evidence for the author's claims about AI safety'"
                    helperText="Be specific about what you want to learn from the uploaded materials"
                    rows={4}
                    required
                  />
                </div>

                <ActionButton 
                  type="submit" 
                  onClick={handleSubmit}
                  loading={loading}
                  disabled={!isFormValid}
                  className="w-full"
                  size="lg"
                >
                  <FileText className="h-4 w-4" />
                  {loading ? 'Processing...' : 'Process File'}
                </ActionButton>
              </form>
            </CardContent>
          </Card>

          {error && (
            <Card className="border-red-500/50 bg-red-500/10 mb-8">
              <CardContent className="pt-6">
                <p className="text-red-300">{error}</p>
              </CardContent>
            </Card>
          )}

           {loading && (
             <Card className="bg-gray-800/50 border-gray-700">
               <CardContent className="py-8 text-center">
                 <Loader2 className="h-8 w-8 animate-spin mx-auto mb-2 text-blue-500" />
                 <p className="text-gray-400">Adaptive research team analyzing your materials...</p>
               </CardContent>
             </Card>
           )}

           {result && (
             <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
               <Card className="bg-gray-800/50 border-gray-700">
                 <CardHeader><CardTitle>Research Results</CardTitle></CardHeader>
                 <CardContent>
                   <div className="bg-gray-900/50 rounded-lg p-4">
                     <p className="text-gray-300 leading-relaxed whitespace-pre-wrap">
                       {typeof result.result === 'string' ? result.result : JSON.stringify(result, null, 2)}
                     </p>
                   </div>
                 </CardContent>
               </Card>
             </motion.div>
           )}

           {!result && !loading && (
             <EmptyState
               icon={<FileText className="h-16 w-16 text-gray-600" />}
               title="Ready to research"
               description="Upload your research materials and enter a question to get AI-powered multi-agent analysis"
               tips={[
                 "Upload PDF, TXT, or DOCX files for analysis",
                 "Be specific in your research question",
                 "The adaptive team will reason through multiple angles"
             ]}
             />
           )}
        </div>
      </main>
    </>
  );
};

export default Ag2AdaptiveResearchTeamPage;

import React, { useState, useEffect } from "react";
import { Helmet } from "react-helmet-async";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "../../context/AuthContext";
import {
  Brain,
  Zap,
  History,
  Sparkles,
  MessageSquare,
  ArrowRight,
  Clock,
  Lightbulb,
  CheckCircle2,
  RefreshCw
} from "lucide-react";
import { SmartTextarea } from "@/components/agent-ui/SmartTextarea";
import { ActionButton } from "@/components/agent-ui/ActionButton";
import { ResultCard, ResultGrid } from "@/components/agent-ui/ResultCard";
import { EmptyState } from "@/components/agent-ui/EmptyState";
import { LoadingIndicator } from "@/components/agent-ui/LoadingIndicator";
import { ErrorMessage } from "@/components/agent-ui/ErrorMessage";

interface ReasoningResponse {
  standardAnswer?: string;
  reasoningAnswer?: string;
  timestamp: string;
  question: string;
  model: string;
  mode: string;
  processingTime: number;
}

const ReasoningAgentPage: React.FC = () => {
  const { user } = useAuth();
  const [question, setQuestion] = useState("");
  const [mode, setMode] = useState<"standard" | "reasoning" | "compare">("compare");
  const [model, setModel] = useState("gpt-4o-mini");
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<ReasoningResponse | null>(null);
  const [history, setHistory] = useState<ReasoningResponse[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    const savedQuestion = localStorage.getItem('reasoning-question');
    const savedMode = localStorage.getItem('reasoning-mode');
    const savedModel = localStorage.getItem('reasoning-model');
    if (savedQuestion) setQuestion(savedQuestion);
    if (savedMode) setMode(savedMode as "standard" | "reasoning" | "compare");
    if (savedModel) setModel(savedModel);
  }, []);

  useEffect(() => {
    localStorage.setItem('reasoning-question', question);
  }, [question]);

  useEffect(() => {
    localStorage.setItem('reasoning-mode', mode);
  }, [mode]);

  useEffect(() => {
    localStorage.setItem('reasoning-model', model);
  }, [model]);

  useEffect(() => {
    const saved = localStorage.getItem('reasoning-history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch {
        // Ignore parse errors, start fresh
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('reasoning-history', JSON.stringify(history));
  }, [history]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim() || isProcessing) return;

    setIsProcessing(true);
    setError(null);
    setResult(null);

    try {
      const response = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/reasoning-agent`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          question: question.trim(),
          mode,
          model,
          userId: user?.id
        })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to process reasoning request');
      }

      const reasoningResult: ReasoningResponse = {
        ...data,
        timestamp: new Date().toISOString()
      };

      setResult(reasoningResult);
      setHistory(prev => [reasoningResult, ...prev.slice(0, 19)]);

    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unexpected error occurred');
      console.error('Reasoning agent error:', err);
    } finally {
      setIsProcessing(false);
    }
  };

  const exampleQuestions = [
    "How many 'r's are in 'strawberry'?",
    "If a bat and ball cost $1.10 and bat costs $1.00 more than ball, how much each?",
    "A farmer has 17 sheep, all but 9 die. How many left?",
    "What is the 17th letter of the alphabet?",
    "If you have 3 apples, give half away, then buy 4 more, how many total?"
  ];

  const clearHistory = () => {
    setHistory([]);
    localStorage.removeItem('reasoning-history');
  };

  return (
    <>
      <Helmet>
        <title>AI Reasoning Agent - Compare AI Thinking Patterns | VideoRemix.vip</title>
        <meta
          name="description"
          content="Watch AI think step-by-step. Compare standard answers vs reasoned responses to see how reasoning mode improves problem-solving."
        />
      </Helmet>

      <main className="pt-24 pb-20">
        <div className="container mx-auto px-4 max-w-6xl">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center mb-12"
          >
            <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-purple-600 via-pink-500 to-orange-500 rounded-2xl mb-6 shadow-lg shadow-purple-500/20">
              <Brain className="h-10 w-10 text-white" />
            </div>
            <h1 className="text-4xl md:text-5xl font-bold text-white mb-4 bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-pink-400">
              AI Reasoning Agent
            </h1>
            <p className="text-xl text-gray-300 max-w-2xl mx-auto">
              Compare how AI answers with and without explicit reasoning.
              See the difference step-by-step thinking makes.
            </p>
          </motion.div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 }}
                className="bg-gray-800/50 backdrop-blur-sm rounded-xl p-6 border border-gray-700"
              >
                <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                  <Sparkles className="h-5 w-5 text-purple-400" />
                  Configuration
                </h2>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-2">
                      AI Model
                    </label>
                    <select
                      value={model}
                      onChange={(e) => setModel(e.target.value)}
                      className="w-full bg-gray-900/50 border border-gray-600 rounded-lg px-3 py-2.5 text-white focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 transition-all"
                    >
                      <option value="gpt-4o">GPT-4o (Most Capable)</option>
                      <option value="gpt-4o-mini">GPT-4o Mini (Fastest)</option>
                      <option value="gpt-4-turbo">GPT-4 Turbo</option>
                    </select>
                    <p className="text-xs text-gray-500 mt-1">
                      GPT-4o provides best reasoning; mini is faster for simple puzzles
                    </p>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-2">
                      Reasoning Mode
                    </label>
                    <select
                      value={mode}
                      onChange={(e) => setMode(e.target.value as any)}
                      className="w-full bg-gray-900/50 border border-gray-600 rounded-lg px-3 py-2.5 text-white focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 transition-all"
                    >
                      <option value="compare">
                        Compare Both (Recommended)
                      </option>
                      <option value="reasoning">
                        Reasoning Mode Only
                      </option>
                      <option value="standard">
                        Standard Mode Only
                      </option>
                    </select>
                    <p className="text-xs text-gray-500 mt-1">
                      Compare to see how reasoning changes the answer
                    </p>
                  </div>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-2">
                      Ask a Reasoning Question
                    </label>
                    <SmartTextarea
                      value={question}
                      onChange={(e) => setQuestion(e.target.value)}
                      placeholder="Enter a logic puzzle, math problem, or analytical question that requires step-by-step thinking..."
                      className="w-full"
                    />
                    <p className="text-xs text-gray-500 mt-2">
                      Format tip: Be specific about what you're asking. Include all relevant details and constraints for best results.
                    </p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <span className="text-sm text-gray-400 flex items-center mr-2">Try:</span>
                    {exampleQuestions.map((q, i) => (
                      <button
                        key={i}
                        type="button"
                        onClick={() => setQuestion(q)}
                        className="text-xs bg-gray-700/50 hover:bg-gray-700 text-gray-300 px-3 py-1.5 rounded-full transition-all border border-gray-600 hover:border-purple-500/50"
                      >
                        {q.length > 40 ? q.substring(0, 40) + '...' : q}
                      </button>
                    ))}
                  </div>

                  <div className="flex items-center gap-4">
                    <ActionButton
                      type="submit"
                      isLoading={isProcessing}
                      disabled={isProcessing || !question.trim()}
                      loadingText="Analyzing..."
                      icon={<Brain className="h-5 w-5" />}
                      className="flex-1"
                    >
                      Analyze with AI
                    </ActionButton>

                    {history.length > 0 && (
                      <button
                        type="button"
                        onClick={() => setShowHistory(!showHistory)}
                        className="flex items-center gap-2 bg-gray-700/50 hover:bg-gray-700 text-gray-300 px-4 py-2.5 rounded-lg transition-colors"
                      >
                        <History className="h-4 w-4" />
                        History ({history.length})
                      </button>
                    )}
                  </div>
                </form>
              </motion.div>

              <AnimatePresence>
                {(result || isProcessing) && (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    className="bg-gray-800/50 backdrop-blur-sm rounded-xl p-6 border border-gray-700"
                  >
                    <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                      <Zap className="h-5 w-5 text-yellow-400" />
                      AI Response
                    </h2>

                    {isProcessing && (
                      <LoadingIndicator 
                        message="AI is thinking..." 
                        submessage="This may take 10-30 seconds" 
                      />
                    )}

                    {result && !isProcessing && (
                      <div className="space-y-6">
                        {mode === "compare" && result.standardAnswer && result.reasoningAnswer && (
                          <ResultGrid columns={2}>
                            <ResultCard
                              title="Standard Response"
                              subtitle="No step-by-step reasoning"
                              icon={<Zap className="h-4 w-4 text-blue-400" />}
                              content={result.standardAnswer}
                              metadata={{
                                "Processing Time": `${Math.round(result.processingTime / 1000)}s`,
                                "Model": result.model
                              }}
                            />
                            <ResultCard
                              title="With Reasoning"
                              subtitle="Step-by-step thinking"
                              icon={<Brain className="h-4 w-4 text-purple-400" />}
                              content={result.reasoningAnswer}
                              metadata={{
                                "Processing Time": `${Math.round(result.processingTime / 1000)}s`,
                                "Model": result.model
                              }}
                              variant="highlighted"
                            />
                          </ResultGrid>
                        )}

                        {mode === "standard" && result.standardAnswer && (
                          <ResultCard
                            title="Standard Response"
                            subtitle="Direct answer without explicit reasoning"
                            icon={<Zap className="h-4 w-4 text-blue-400" />}
                            content={result.standardAnswer}
                            metadata={{
                              "Processing Time": `${Math.round(result.processingTime / 1000)}s`,
                              "Model": result.model,
                              "Timestamp": new Date(result.timestamp).toLocaleString()
                            }}
                          />
                        )}

                        {mode === "reasoning" && result.reasoningAnswer && (
                          <ResultCard
                            title="Reasoning Response"
                            subtitle="Step-by-step analytical thinking"
                            icon={<Brain className="h-4 w-4 text-purple-400" />}
                            content={result.reasoningAnswer}
                            metadata={{
                              "Processing Time": `${Math.round(result.processingTime / 1000)}s`,
                              "Model": result.model,
                              "Timestamp": new Date(result.timestamp).toLocaleString()
                            }}
                            variant="highlighted"
                          />
                        )}

                        <div className="flex items-center gap-4 text-xs text-gray-500 pt-2 border-t border-gray-700">
                          <span className="flex items-center gap-1">
                            <Clock className="h-3 w-3" />
                            {Math.round(result.processingTime / 1000)}s
                          </span>
                          <span>{new Date(result.timestamp).toLocaleString()}</span>
                          <span className="flex items-center gap-1">
                            <Sparkles className="h-3 w-3" />
                            {result.model}
                          </span>
                        </div>
                      </div>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>

              {!result && !isProcessing && (
                <EmptyState
                  icon={<Brain className="h-12 w-12 text-purple-400" />}
                  title="No reasoning results yet"
                  description="Enter a logic puzzle, math problem, or analytical question above to see how AI reasoning compares to standard responses."
                  tips={[
                    "Try: 'How many r's are in strawberry?'",
                    "Classic: 'A bat and ball cost $1.10, bat is $1.00 more...'",
                    "Logic: 'A farmer has 17 sheep, all but 9 die...'",
                    "Math: 'What is the 17th letter of the alphabet?'"
                  ]}
                />
              )}

              {error && (
                <ErrorMessage
                  message={error}
                  onDismiss={() => setError(null)}
                />
              )}

              <AnimatePresence>
                {showHistory && history.length > 0 && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    exit={{ opacity: 0, height: 0 }}
                    className="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700 overflow-hidden"
                  >
                    <div className="p-4 border-b border-gray-700 flex items-center justify-between">
                      <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <History className="h-5 w-5 text-blue-400" />
                        Recent Queries
                      </h3>
                      <button
                        onClick={clearHistory}
                        className="text-sm text-gray-400 hover:text-red-400 transition-colors"
                      >
                        Clear All
                      </button>
                    </div>
                    <div className="divide-y divide-gray-700/50 max-h-96 overflow-y-auto">
                      {history.map((entry, idx) => (
                        <div
                          key={idx}
                          onClick={() => {
                            setResult(entry);
                            setQuestion(entry.question);
                            setMode(entry.mode as any);
                            setModel(entry.model);
                            setShowHistory(false);
                            window.scrollTo({ top: 0, behavior: 'smooth' });
                          }}
                          className="p-4 hover:bg-gray-700/30 cursor-pointer transition-colors"
                        >
                          <div className="flex items-start justify-between gap-4">
                            <div className="flex-1 min-w-0">
                              <p className="text-sm text-white line-clamp-2 mb-2">
                                {entry.question}
                              </p>
                              <div className="flex items-center gap-3 text-xs text-gray-500">
                                <span className="px-2 py-0.5 bg-gray-700/50 rounded">
                                  {entry.mode}
                                </span>
                                <span>{entry.model}</span>
                                <span className="flex items-center gap-1">
                                  <Clock className="h-3 w-3" />
                                  {new Date(entry.timestamp).toLocaleTimeString()}
                                </span>
                              </div>
                            </div>
                            <ArrowRight className="h-4 w-4 text-gray-500 flex-shrink-0" />
                          </div>
                        </div>
                      ))}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            <div className="space-y-6">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-gray-800/50 backdrop-blur-sm rounded-xl p-6 border border-gray-700"
              >
                <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                  <MessageSquare className="h-5 w-5 text-green-400" />
                  How It Works
                </h3>
                <div className="space-y-4">
                  {[
                    { step: 1, title: 'Enter Question', desc: 'Choose a puzzle, logic problem, or analytical question' },
                    { step: 2, title: 'Select Mode', desc: 'Compare standard vs reasoning or use reasoning explicitly' },
                    { step: 3, title: 'View Results', desc: 'See how reasoning changes the AI\'s approach and answer' }
                  ].map((item, i) => (
                    <div key={i} className="flex gap-3">
                      <div className="w-7 h-7 rounded-full bg-purple-600/20 text-purple-400 flex items-center justify-center text-sm font-bold flex-shrink-0">
                        {item.step}
                      </div>
                      <div>
                        <p className="text-sm font-medium text-white">{item.title}</p>
                        <p className="text-xs text-gray-400">{item.desc}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </motion.div>

              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.3 }}
                className="bg-gradient-to-br from-purple-900/30 to-pink-900/20 rounded-xl p-6 border border-purple-500/20"
              >
                <h3 className="text-lg font-bold text-white mb-3 flex items-center gap-2">
