            <ResultGrid columns={2}>
              <ResultCard
                icon={<FileText />}
                title="Word Count"
                value={result.wordCount || result.words || "—"}
                subtext="words generated"
                variant="info"
              />
              <ResultCard
                icon={<Search />}
                title="Sources Used"
                value={result.sources?.length || "—"}
                subtext="web sources researched"
                variant="success"
              />
