  product: string;
  timestamp: string;
  status: 'processing' | 'completed' | 'error';
  competitorProfile?: {
    companyOverview?: {
      name?: string;
      founded?: string;
      hq?: string;
      size?: string;
    };
    targetMarket?: {
      customers?: string[];
      industries?: string[];
