interface PortfolioItem {
  id: string;
  symbol: string;
  shares: number;
  buyPrice: number;
  currentPrice?: number;
  value?: number;
  gain?: number;
  gainPct?: number;
}

interface StockData {
  symbol: string;
  price: number;
  change: number;
  changePercent: number;
  name?: string;
  pe?: number;
  marketCap?: number;
  volume?: number;
}

interface AIInsight {
  analysis: string;
  recommendation: 'Buy' | 'Hold' | 'Sell' | 'Neutral';
  confidence: number;
  risks?: string[];
  opportunities?: string[];
}

const FinanceAgentPage: React.FC = () => {
  const { user } = useAuth();

  // Stock lookup state
  const [symbol, setSymbol] = useState("");
  const [stockData, setStockData] = useState<StockData | null>(null);
  const [stockLoading, setStockLoading] = useState(false);
  const [stockError, setStockError] = useState<string | null>(null);

  // Portfolio state
  const [portfolio, setPortfolio] = useState<PortfolioItem[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newSymbol, setNewSymbol] = useState("");
  const [newShares, setNewShares] = useState(100);
  const [newBuyPrice, setNewBuyPrice] = useState(100);

  // AI Analysis state
  const [aiInsight, setAiInsight] = useState<AIInsight | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiQuestion, setAiQuestion] = useState("");

  // Load portfolio from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('finance-portfolio');
    if (saved) {
      try {
        setPortfolio(JSON.parse(saved));
      } catch {
        // Ignore corrupted data
      }
    }
  }, []);

  // Save portfolio
  useEffect(() => {
    localStorage.setItem('finance-portfolio', JSON.stringify(portfolio));
  }, [portfolio]);

  // Fetch stock data
  const fetchStockData = async (sym: string) => {
    setStockLoading(true);
    setStockError(null);
    setStockData(null);

    try {
      const response = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/finance-agent`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'getStock', symbol: sym.toUpperCase() })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to fetch stock data');
      }

      setStockData(data.stock);

    } catch (err) {
      setStockError(err instanceof Error ? err.message : 'Failed to fetch stock data');
    } finally {
      setStockLoading(false);
    }
  };

  // Get AI Analysis
  const getAIAnalysis = async () => {
    if (!stockData) return;

    setAiLoading(true);
    setAiInsight(null);

    try {
      const response = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/finance-agent`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'analyze',
          symbol: stockData.symbol,
          stockData: stockData,
          userId: user?.id
        })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Analysis failed');
      }

      setAiInsight(data.insight);

    } catch (err) {
      console.error('AI analysis error:', err);
    } finally {
      setAiLoading(false);
    }
  };

  // Ask AI question
  const askAI = async () => {
    if (!aiQuestion.trim() || !stockData) return;

    setAiLoading(true);
    try {
      const response = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/finance-agent`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'ask',
          question: aiQuestion,
          symbol: stockData.symbol,
          stockInfo: stockData
        })
      });

      const data = await response.json();
      setAiInsight(prev => ({
        ...prev,
        analysis: data.answer || 'No response'
      }));

    } catch (err) {
      console.error('AI question error:', err);
    } finally {
      setAiLoading(false);
    }
  };

  // Add to portfolio
  const addToPortfolio = () => {
    if (!newSymbol.trim()) return;

    const newItem: PortfolioItem = {
      id: `portfolio_${Date.now()}`,
      symbol: newSymbol.toUpperCase(),
      shares: newShares,
      buyPrice: newBuyPrice
    };

    setPortfolio(prev => [...prev, newItem]);
    setShowAddModal(false);
    setNewSymbol("");
    setNewShares(100);
    setNewBuyPrice(100);
  };

  // Remove from portfolio
  const removeFromPortfolio = (id: string) => {
    setPortfolio(prev => prev.filter(item => item.id !== id));
  };

  // Calculate portfolio totals
  const portfolioTotals = portfolio.reduce((acc, item) => {
    const value = (item.currentPrice || item.buyPrice) * item.shares;
    const cost = item.buyPrice * item.shares;
    return {
      value: acc.value + value,
      cost: acc.cost + cost
    };
  }, { value: 0, cost: 0 });

  return (
    <>
      <Helmet>
        <title>AI Finance Agent - Stock Analysis & Portfolio Tracking | VideoRemix.vip</title>
        <meta
          name="description"
          content="AI-powered finance platform: Real-time stock data, portfolio tracking, and intelligent market insights powered by OpenAI."
        />
      </Helmet>

      <main className="pt-24 pb-20">
