  onClose,
  onPurchase,
  onBundlePurchase
}) => {
  const [activeSection, setActiveSection] = useState('overview');
  const [selectedTier, setSelectedTier] = useState<'single' | 'bundle'>('single');
  const [loading, setLoading] = useState(false);
