            tier: selectedTier,
            userId: user?.id || 'guest',
            userEmail: user?.email || '',
            allowGuestCheckout: true, // Always allow guest checkout
            purchaseType: selectedTier,
            isBundle: selectedTier === 'bundle',
          }),
        },
      );

