import React, { useEffect, useRef } from "react";
import { Navigate, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

interface ProtectedRouteProps {
  children: ReactNode;
}

/**
 * ProtectedRoute component that handles authentication state reliably.
 *
 * Features:
 * - Waits for session resolution before making routing decisions
 * - Preserves intended destination for post-login redirect
 * - Prevents redirect loops
 * - Handles edge cases (tab switching, session expiry, etc.)
 */
const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children }) => {
  const { user, loading, authState, isAuthenticated, isSessionExpiringSoon, refreshSession } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  // Track if we've made a routing decision to prevent flicker
  const hasMadeDecisionRef = useRef(false);
  const previousAuthStateRef = useRef(authState);

  // Proactively refresh session if expiring soon
  useEffect(() => {
    if (isAuthenticated && isSessionExpiringSoon) {
      console.log("[ProtectedRoute] Session expiring soon, refreshing...");
      refreshSession();
    }
  }, [isAuthenticated, isSessionExpiringSoon, refreshSession]);

  // Reset decision flag when auth state changes
  useEffect(() => {
    if (authState !== previousAuthStateRef.current) {
      hasMadeDecisionRef.current = false;
      previousAuthStateRef.current = authState;
    }
  }, [authState]);

  // Loading state - wait for session resolution
  // We show loading until we have a definitive auth state
  if (loading || authState === "loading" || authState === "idle") {
    return (
      <div className="min-h-screen flex flex-col justify-center items-center bg-gray-900 text-white">
        <div className="relative">
          <div className="w-20 h-20 border-t-4 border-primary-500 border-solid rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-primary-500 font-medium text-sm">Loading</span>
          </div>
        </div>
        <p className="mt-4 text-gray-400 text-sm">Verifying session...</p>
      </div>
    );
  }

  // Error state - show error with retry option
  if (authState === "error") {
    return (
      <div className="min-h-screen flex flex-col justify-center items-center bg-gray-900 text-white">
        <div className="text-center max-w-md px-4">
          <div className="text-red-500 text-5xl mb-4">⚠️</div>
          <h2 className="text-xl font-semibold mb-2">Authentication Error</h2>
          <p className="text-gray-400 mb-4">
            There was a problem verifying your session. Please try signing in again.
          </p>
          <button
            onClick={() => navigate("/signin", { state: { from: location.pathname } })}
            className="px-6 py-2 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors"
          >
            Go to Sign In
          </button>
        </div>
      </div>
    );
  }

  // Unauthenticated state - redirect to sign in
  // Only redirect after we're certain the user is not authenticated
  if (!isAuthenticated || !user) {
    // Prevent redirect loops - don't redirect if we're already going to signin
    if (location.pathname === "/signin" || location.pathname === "/signup") {
      console.log("[ProtectedRoute] On signin page, allowing access");
      return <>{children}</>;
    }

    // Store the intended destination
    const from = location.pathname + location.search + location.hash;

    console.log("[ProtectedRoute] Not authenticated, redirecting to signin. Current path:", location.pathname, "Auth state:", authState, "User:", !!user);

    return (
      <Navigate
        to="/signin"
        state={{
          from: location.pathname,
          fromFull: from,
          timestamp: Date.now(),
        }}
        replace
      />
    );
  }

  console.log("[ProtectedRoute] User authenticated, allowing access to:", location.pathname);

  // Authenticated - render protected content
  console.log("[ProtectedRoute] User authenticated, rendering protected content", {
    userId: user?.id,
    pathname: location.pathname,
    authState,
    isAuthenticated
  });
  hasMadeDecisionRef.current = true;

  return <>{children}</>;
};

export default ProtectedRoute;

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import TrendingUp from 'lucide-react/dist/esm/icons/trending-up.js';
import Users from 'lucide-react/dist/esm/icons/users.js';
import Eye from 'lucide-react/dist/esm/icons/eye.js';
import MousePointer from 'lucide-react/dist/esm/icons/mouse-pointer.js';
import ShoppingCart from 'lucide-react/dist/esm/icons/shopping-cart.js';
import DollarSign from 'lucide-react/dist/esm/icons/dollar-sign.js';
import Clock from 'lucide-react/dist/esm/icons/clock.js';
import AlertTriangle from 'lucide-react/dist/esm/icons/alert-triangle.js';
import CheckCircle from 'lucide-react/dist/esm/icons/check-circle.js';
import XCircle from 'lucide-react/dist/esm/icons/x-circle.js';
import BarChart3 from 'lucide-react/dist/esm/icons/bar-chart-3.js';
import PieChart from 'lucide-react/dist/esm/icons/pie-chart.js';
import Activity from 'lucide-react/dist/esm/icons/activity.js';

// Analytics data types
interface AnalyticsSummary {
  total_sessions: number;
  total_users: number;
  total_events: number;
  conversion_rate: number;
  avg_session_duration: number;
  top_performing_apps: Array<{
    app_id: string;
    app_name: string;
    views: number;
    clicks: number;
    purchases: number;
    conversion_rate: number;
  }>;
  funnel_metrics: {
    card_views: number;
    card_clicks: number;
    modal_opens: number;
    cta_clicks: number;
    purchases: number;
  };
  performance_metrics: {
    avg_modal_load_time: number;
    image_load_success_rate: number;
    error_rate: number;
  };
  ab_test_results: Array<{
    test_id: string;
    test_name: string;
    variants: Array<{
      variant: string;
      conversions: number;
      conversion_rate: number;
      confidence: number;
    }>;
    winner?: string;
  }>;
}

interface AnalyticsDashboardProps {
  isAdmin?: boolean;
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ isAdmin = false }) => {
  const [timeRange, setTimeRange] = useState<'24h' | '7d' | '30d' | '90d'>('7d');
  const [data, setData] = useState<AnalyticsSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch analytics data
  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        setLoading(true);
        const response = await fetch(`/api/analytics/summary?range=${timeRange}`, {
          headers: {
            'Authorization': `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY}`,
          },
        });

        if (!response.ok) {
          throw new Error('Failed to fetch analytics data');
        }

        const analyticsData = await response.json();
        setData(analyticsData);
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, [timeRange]);

  if (loading) {
    return (
      <div className="flex justify-center items-center py-20">
        <div className="text-center">
          <div className="w-12 h-12 border-t-2 border-primary-500 border-solid rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-400">Loading analytics...</p>
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="text-center py-20">
        <AlertTriangle className="h-12 w-12 text-red-500 mx-auto mb-4" />
        <p className="text-red-400">Failed to load analytics data</p>
        <p className="text-gray-500 text-sm mt-2">{error}</p>
      </div>
    );
  }

  const formatNumber = (num: number): string => {
    if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
    if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
    return num.toString();
  };

  const formatPercentage = (num: number): string => {
    return (num * 100).toFixed(1) + '%';
  };

  const formatDuration = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}m ${secs}s`;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-white">Analytics Dashboard</h1>
          <p className="text-gray-400 mt-1">Real-time insights into user behavior and conversion optimization</p>
        </div>

        {/* Time Range Selector */}
        <div className="flex bg-gray-800 rounded-lg p-1">
          {(['24h', '7d', '30d', '90d'] as const).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`px-3 py-1 rounded-md text-sm font-medium transition-colors ${
                timeRange === range
                  ? 'bg-primary-600 text-white'
                  : 'text-gray-400 hover:text-white hover:bg-gray-700'
              }`}
            >
              {range}
            </button>
          ))}
        </div>
      </div>

      {/* Key Metrics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <MetricCard
          title="Total Sessions"
          value={formatNumber(data.total_sessions)}
          icon={<Users className="h-6 w-6" />}
          trend="+12.5%"
          color="blue"
