// Floating Icon component to add visual interest
const FloatingIcon: React.FC<{
  icon: React.ReactNode;
  size?: number;
  color?: string;
  top?: string;
  left?: string;
  right?: string;
  bottom?: string;
  delay?: number;
  duration?: number;
  distance?: number;
}> = ({
  icon,
  size = 24,
  color = "rgba(99, 102, 241, 0.2)",
  top,
  left,
  right,
  bottom,
  delay = 0,
  duration = 3,
  distance = 10,
}) => {
  return (
    <motion.div
      className="absolute z-0 pointer-events-none"
      style={{
        top,
        left,
        right,
        bottom,
        color,
      }}
      initial={{ opacity: 0 }}
      animate={{
        opacity: [0.4, 0.8, 0.4],
        y: [-distance, 0, -distance],
      }}
      transition={{
        repeat: Infinity,
        repeatType: "reverse",
        duration,
        delay,
        ease: "easeInOut",
      }}
    >
      {React.cloneElement(icon as React.ReactElement, {
        size,
        strokeWidth: 1,
      })}
    </motion.div>
  );
};

