interface CountdownTimerProps {
  hours: number;
  minutes: number;
  seconds: number;
  onComplete?: () => void;
}

const CountdownTimer: React.FC<CountdownTimerProps> = ({
  hours,
  minutes,
  seconds,
  onComplete,
}) => {
  const [timeLeft, setTimeLeft] = useState({
    hours,
    minutes,
    seconds,
  });

  useEffect(() => {
    const interval = setInterval(() => {
      setTimeLeft((prev) => {
        const newSeconds = prev.seconds - 1;

        if (newSeconds >= 0) {
          return { ...prev, seconds: newSeconds };
        }

        const newMinutes = prev.minutes - 1;

        if (newMinutes >= 0) {
          return { ...prev, minutes: newMinutes, seconds: 59 };
        }

        const newHours = prev.hours - 1;

        if (newHours >= 0) {
          return { hours: newHours, minutes: 59, seconds: 59 };
        }

        clearInterval(interval);
        if (onComplete) onComplete();
        return { hours: 0, minutes: 0, seconds: 0 };
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [onComplete]);

  // Derive time percentage for circular progress
  const totalSeconds = hours * 3600 + minutes * 60 + seconds;
  const currentSeconds =
    timeLeft.hours * 3600 + timeLeft.minutes * 60 + timeLeft.seconds;
  const percentage = (currentSeconds / totalSeconds) * 100;

  return (
    <div className="flex flex-col items-center mb-6">
      <div className="relative w-32 h-32 mb-4">
        {/* Background circle */}
        <svg className="w-full h-full" viewBox="0 0 100 100">
          <circle
            cx="50"
            cy="50"
            r="45"
            fill="none"
            stroke="rgba(255, 255, 255, 0.2)"
            strokeWidth="8"
          />
          {/* Progress circle with stroke-dasharray animation */}
          <motion.circle
            cx="50"
            cy="50"
            r="45"
            fill="none"
            stroke="url(#gradient)"
            strokeWidth="8"
            strokeLinecap="round"
            strokeDasharray={`${percentage * 2.83}, 283`} // 283 is approximately 2πr where r=45
            style={{ transformOrigin: "center", transform: "rotate(-90deg)" }}
            animate={{
              strokeDasharray: [`${percentage * 2.83}, 283`],
            }}
            transition={{ duration: 0.5 }}
          />
          <defs>
            <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#ec4899" />
              <stop offset="100%" stopColor="#4f46e5" />
            </linearGradient>
          </defs>
        </svg>

        {/* Time display in center */}
        <div className="absolute inset-0 flex flex-col items-center justify-center text-white">
          <motion.div
            className="text-3xl font-mono font-bold flex"
            whileHover={{
              scale: 1.1,
              textShadow: "0 0 8px rgba(255, 255, 255, 0.5)",
            }}
          >
            <span>{String(timeLeft.hours).padStart(2, "0")}</span>
            <span className="mx-1">:</span>
            <span>{String(timeLeft.minutes).padStart(2, "0")}</span>
            <span className="mx-1">:</span>
            <motion.span
              animate={{ scale: [1, 1.2, 1] }}
              transition={{ repeat: Infinity, duration: 1 }}
            >
              {String(timeLeft.seconds).padStart(2, "0")}
            </motion.span>
          </motion.div>
          <div className="text-xs opacity-70 mt-1">REMAINING</div>
        </div>
      </div>
    </div>
  );
};

