                key={index}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, delay: 0.2 + index * 0.1 }}
                whileHover={{
                  boxShadow: "0 8px 30px rgba(0, 0, 0, 0.12)",
                  y: -4,
                  transition: { duration: 0.2 },
                }}
                className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden mb-4"
              >
                <button
                  className="flex justify-between items-center w-full text-left px-6 py-5 focus:outline-none"
                  onClick={() => toggleFaq(index)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      toggleFaq(index);
                    }
                  }}
                  aria-expanded={openIndex === index}
                  aria-controls={faqId}
                  tabIndex={0}
                >
                <h3 className="text-lg font-medium text-white">
                  {faq.question}
                </h3>
                <div
                  className={`flex-shrink-0 ml-2 p-1 rounded-full transition-colors duration-200 ${
                    openIndex === index
                      ? "bg-primary-500/20 text-primary-400"
                      : "bg-gray-700 text-gray-400"
                  }`}
                >
                  <motion.div
                    animate={{ rotate: openIndex === index ? 180 : 0 }}
                    transition={{ duration: 0.3 }}
                  >
                    <ChevronDown className="h-5 w-5" />
                  </motion.div>
                  </div>
                </button>

                <AnimatePresence initial={false}>
                  {openIndex === index && (
                    <motion.div
                      id={faqId}
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.3 }}
                      className="overflow-hidden"
                    >
                      <div className="px-6 pb-5 text-gray-300">{faq.answer}</div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

