import React, { useState } from "react";

import { X, Eye, EyeOff, AlertCircle, CheckCircle } from "lucide-react";
import { useAuth } from "../context/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface SignUpModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSwitchToSignIn: () => void;
}

const SignUpModal: React.FC<SignUpModalProps> = ({
  isOpen,
  onClose,
  onSwitchToSignIn,
}) => {
  const { signUp } = useAuth();
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    confirmPassword: "",
    firstName: "",
    lastName: "",
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);

    if (formData.password !== formData.confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    if (formData.password.length < 6) {
      setError("Password must be at least 6 characters");
      return;
    }

    setLoading(true);

    try {
      const { error } = await signUp(formData.email, formData.password, {
        first_name: formData.firstName,
        last_name: formData.lastName,
      });

      if (error) {
        setError(error.message);
      } else {
        setSuccess(
          "Account created successfully! Please check your email to verify your account.",
        );
      }
    } catch (err) {
      setError("An unexpected error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange =
    (field: string) => (e: React.ChangeEvent<HTMLInputElement>) => {
      setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-gray-800 border-gray-700 text-white max-w-md">
        <DialogHeader>
          <DialogTitle className="text-2xl font-bold">Sign Up</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <Alert
              variant="destructive"
              className="bg-red-500/20 border-red-500/50"
            >
              <AlertCircle className="h-5 w-5" />
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          {success && (
            <Alert className="bg-green-500/20 border-green-500/50 text-green-400">
              <CheckCircle className="h-5 w-5" />
              <AlertDescription>{success}</AlertDescription>
            </Alert>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="signup-firstname" className="text-gray-300">
                First Name
              </Label>
              <Input
                id="signup-firstname"
                type="text"
                value={formData.firstName}
                onChange={handleInputChange("firstName")}
                className="bg-gray-700 border-gray-600 text-white placeholder:text-gray-400"
                placeholder="John"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="signup-lastname" className="text-gray-300">
                Last Name
              </Label>
              <Input
                id="signup-lastname"
                type="text"
                value={formData.lastName}
                onChange={handleInputChange("lastName")}
                className="bg-gray-700 border-gray-600 text-white placeholder:text-gray-400"
                placeholder="Doe"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="signup-email" className="text-gray-300">
              Email
            </Label>
            <Input
              id="signup-email"
              type="email"
              value={formData.email}
              onChange={handleInputChange("email")}
              className="bg-gray-700 border-gray-600 text-white placeholder:text-gray-400"
              placeholder="your@email.com"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="signup-password" className="text-gray-300">
              Password
            </Label>
            <div className="relative">
              <Input
                id="signup-password"
                type={showPassword ? "text" : "password"}
                value={formData.password}
                onChange={handleInputChange("password")}
                className="bg-gray-700 border-gray-600 text-white placeholder:text-gray-400 pr-12"
                placeholder="Create a password"
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-300 transition-colors"
              >
                {showPassword ? (
                  <EyeOff className="h-5 w-5" />
                ) : (
                  <Eye className="h-5 w-5" />
                )}
              </button>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="signup-confirm-password" className="text-gray-300">
              Confirm Password
            </Label>
            <div className="relative">
              <Input
                id="signup-confirm-password"
                type={showConfirmPassword ? "text" : "password"}
                value={formData.confirmPassword}
                onChange={handleInputChange("confirmPassword")}
                className="bg-gray-700 border-gray-600 text-white placeholder:text-gray-400 pr-12"
                placeholder="Confirm your password"
                required
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-300 transition-colors"
              >
                {showConfirmPassword ? (
                  <EyeOff className="h-5 w-5" />
                ) : (
                  <Eye className="h-5 w-5" />
                )}
              </button>
            </div>
          </div>

          <Button
            type="submit"
            disabled={loading}
            className="w-full bg-primary-600 hover:bg-primary-700 disabled:bg-primary-800"
          >
            {loading ? "Creating Account..." : "Sign Up"}
          </Button>
        </form>

        <div className="mt-6 text-center">
          <p className="text-gray-400">
            Already have an account?{" "}
            <button
              onClick={() => {
                onClose();
                onSwitchToSignIn();
              }}
              className="text-blue-400 hover:text-blue-300 transition-colors"
            >
              Sign in
            </button>
          </p>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default SignUpModal;

import React, { useState } from "react";
import { motion } from "framer-motion";
import {
  Mail,
  CheckCircle,
  AlertCircle,
  Loader,
  MessageSquare,
} from "lucide-react";

interface NewsletterSignupProps {
  variant?: "inline" | "card";
  className?: string;
  title?: string;
  description?: string;
}

const NewsletterSignup: React.FC<NewsletterSignupProps> = ({
  variant = "inline",
  className = "",
  title = "Subscribe to Our Newsletter",
  description = "Get the latest updates, tips and news delivered to your inbox.",
}) => {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<
    "idle" | "submitting" | "success" | "error"
  >("idle");
  const [errorMessage, setErrorMessage] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Basic validation
    if (!email) {
      setStatus("error");
      setErrorMessage("Email address is required.");
      return;
    }

    setStatus("submitting");

    try {
      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
      const response = await fetch(
        `${supabaseUrl}/functions/v1/newsletter-signup`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ email }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.error || "Something went wrong. Please try again.",
        );
      }

      // Success
      setStatus("success");
      setEmail("");
    } catch (error) {
      console.error("Newsletter signup error:", error);
      setStatus("error");
      setErrorMessage(
        error.message || "Something went wrong. Please try again.",
      );
    }
  };

  // Card variant
  if (variant === "card") {
    return (
      <div
        className={`bg-gradient-to-br from-primary-900/40 to-primary-700/40 rounded-xl border border-primary-500/30 p-6 ${className}`}
      >
        <h3 className="text-xl font-bold text-white mb-3">{title}</h3>
        <p className="text-gray-300 text-sm mb-4">{description}</p>

        {status === "success" ? (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-green-900/30 border border-green-600/30 rounded-lg p-4 text-center"
          >
            <CheckCircle className="h-10 w-10 text-green-500 mx-auto mb-2" />
            <p className="text-white font-medium">Thanks for subscribing!</p>
            <p className="text-gray-300 text-sm mt-1">
              You've been added to our mailing list.
            </p>
          </motion.div>
        ) : (
          <form onSubmit={handleSubmit}>
            {/* Error message */}
            {status === "error" && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                className="mb-4 bg-red-900/30 border border-red-600/30 p-3 rounded-lg flex items-start"
              >
                <AlertCircle className="h-5 w-5 text-red-500 mt-0.5 mr-2 flex-shrink-0" />
                <p className="text-red-300 text-sm">{errorMessage}</p>
              </motion.div>
            )}

            <div className="relative mb-3">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Mail className="h-5 w-5 text-gray-500" />
              </div>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Your email address"
                className="bg-gray-800/70 border border-gray-700 rounded-lg w-full pl-10 p-3 text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                required
              />
            </div>

            <motion.button
              whileHover={{ scale: 1.03 }}
              whileTap={{ scale: 0.98 }}
              type="submit"
              disabled={status === "submitting"}
              className={`w-full bg-white text-primary-600 hover:bg-gray-100 font-semibold py-3 rounded-lg transition-colors flex items-center justify-center ${
                status === "submitting" ? "opacity-75 cursor-not-allowed" : ""
              }`}
            >
              {status === "submitting" ? (
                <>
                  <Loader className="animate-spin -ml-1 mr-2 h-5 w-5" />
                  Subscribing...
                </>
              ) : (
                "Subscribe"
              )}
            </motion.button>

            <p className="text-xs text-gray-400 mt-3 text-center">
              We respect your privacy. Unsubscribe at any time.
            </p>
          </form>
        )}
      </div>
    );
  }

  // Inline variant (default)
  return (
    <div className={className}>
      {status === "success" ? (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-green-900/30 border border-green-600/30 rounded-lg p-4 flex items-center"
        >
          <CheckCircle className="h-6 w-6 text-green-500 mr-3 flex-shrink-0" />
          <div>
            <p className="text-white font-medium">Thanks for subscribing!</p>
            <p className="text-gray-300 text-sm">
              You've been added to our mailing list.
            </p>
          </div>
        </motion.div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <h3 className="text-xl font-bold text-white">{title}</h3>
          <p className="text-gray-300">{description}</p>

          {/* Error message */}
          {status === "error" && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
