interface CountdownTimerProps {
  hours: number;
  minutes: number;
  seconds: number;
}

const CountdownTimer: React.FC<CountdownTimerProps> = ({
  hours,
  minutes,
  seconds,
}) => {
  const [timeLeft, setTimeLeft] = useState({
    hours,
    minutes,
    seconds,
  });

  const [isBlinking, setIsBlinking] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setTimeLeft((prev) => {
        const newSeconds = prev.seconds - 1;

        // Set blinking when time is low
        if (prev.hours === 0 && prev.minutes < 30) {
          setIsBlinking(true);
        }

        if (newSeconds >= 0) {
          return { ...prev, seconds: newSeconds };
        }

        const newMinutes = prev.minutes - 1;

        if (newMinutes >= 0) {
          return { ...prev, minutes: newMinutes, seconds: 59 };
        }

        const newHours = prev.hours - 1;

        if (newHours >= 0) {
          return { hours: newHours, minutes: 59, seconds: 59 };
        }

        clearInterval(interval);
        return { hours: 0, minutes: 0, seconds: 0 };
      });
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex items-center space-x-2">
      <div className="hidden sm:block">
        <Timer className="h-4 w-4 text-white animate-pulse" />
      </div>
      <div className="flex items-center">
        <motion.div
          className={`bg-white/20 backdrop-blur-sm px-2 py-1 rounded-md text-white font-mono ${isBlinking ? "animate-pulse" : ""}`}
          animate={{ scale: [1, 1.05, 1] }}
          transition={{
            repeat: Infinity,
            repeatType: "mirror",
            duration: 1,
            repeatDelay: 59,
          }}
        >
          {String(timeLeft.hours).padStart(2, "0")}
        </motion.div>
        <span className="mx-1 text-white">:</span>
        <motion.div
          className={`bg-white/20 backdrop-blur-sm px-2 py-1 rounded-md text-white font-mono ${isBlinking ? "animate-pulse" : ""}`}
          animate={{ scale: [1, 1.05, 1] }}
          transition={{
            repeat: Infinity,
            repeatType: "mirror",
            duration: 1,
            repeatDelay: 59,
          }}
        >
          {String(timeLeft.minutes).padStart(2, "0")}
        </motion.div>
        <span className="mx-1 text-white">:</span>
        <motion.div
          className={`bg-white/20 backdrop-blur-sm px-2 py-1 rounded-md text-white font-mono ${isBlinking ? "animate-pulse" : ""}`}
          animate={{ scale: [1, 1.05, 1] }}
          transition={{
            repeat: Infinity,
            repeatType: "mirror",
            duration: 1,
          }}
        >
          {String(timeLeft.seconds).padStart(2, "0")}
        </motion.div>
      </div>
    </div>
  );
};

