import React, { useState, useEffect, useRef, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useAnimationContext } from "../context/AnimationContext";

interface Sparkle {
  id: string;
  createdAt: number;
  color: string;
  size: number;
  style: {
    top: string;
    left: string;
    zIndex: number;
  };
}

interface MagicSparklesProps {
  colors?: string[];
  minSparkles?: number;
  maxSparkles?: number;
  className?: string;
  overflow?: boolean;
  minSize?: number;
  maxSize?: number;
  speed?: "slow" | "medium" | "fast";
  children?: ReactNode;
}

// Function to generate random sparkles
const generateSparkle = (
  colors: string[],
  minSize: number,
  maxSize: number,
): Sparkle => {
  return {
    id: String(Math.random()),
    createdAt: Date.now(),
    color: colors[Math.floor(Math.random() * colors.length)],
    size: Math.random() * (maxSize - minSize) + minSize,
    style: {
      top: `${Math.random() * 100}%`,
      left: `${Math.random() * 100}%`,
      zIndex: Math.floor(Math.random() * 3), // Random z-index for depth effect
    },
  };
};

const MagicSparkles: React.FC<MagicSparklesProps> = ({
  colors = ["#FFC700", "#FF0069", "#6C00FF", "#4ade80", "#00D1FF"],
  minSparkles = 6,
  maxSparkles = 12,
  className = "",
  overflow = false,
  minSize = 10,
  maxSize = 20,
  speed = "medium",
  children,
}) => {
  const { prefersReducedMotion, lowPowerMode } = useAnimationContext();

  // Temporarily disable animations to prevent infinite re-render issues
  // TODO: Fix the infinite loop in sparkle animation logic
  const animationsDisabled = true;

  // Get a random number of sparkles between min and max (memoized to prevent re-renders)
  const sparkleCount = useMemo(() => Math.floor(
    Math.random() * (maxSparkles - minSparkles + 1) + minSparkles,
  ), [minSparkles, maxSparkles]);

  // Call all hooks unconditionally (React Rules of Hooks)
  const [sparkles, setSparkles] = useState<Sparkle[]>([]);
  const timeoutRef = useRef<number | null>(null);

  // Get animation duration based on speed
  const getAnimationDuration = React.useCallback(() => {
    switch (speed) {
      case "slow":
        return 1800;
      case "fast":
        return 800;
      case "medium":
      default:
        return 1200;
    }
  }, [speed]);

  // Initialize sparkles and set up cleanup
  useEffect(() => {
    // Skip animations for reduced motion, low power, or when disabled
    if (prefersReducedMotion || lowPowerMode || animationsDisabled) {
      return;
    }

    // Create initial sparkles
    const initialSparkles = Array.from({ length: sparkleCount }).map(() =>
      generateSparkle(colors, minSize, maxSize),
    );

    setSparkles(initialSparkles);

    // Replace sparkles periodically using setInterval for cleaner code
    const refreshRate = getAnimationDuration();

    const updateSparkles = () => {
      setSparkles((prevSparkles) => {
        // Remove one random sparkle
        const nextSparkles = [...prevSparkles];

        if (nextSparkles.length > 0) {
          const indexToRemove = Math.floor(Math.random() * nextSparkles.length);
          nextSparkles.splice(indexToRemove, 1);
        }

        // Add a new sparkle
        return [...nextSparkles, generateSparkle(colors, minSize, maxSize)];
      });
    };

    // Start the interval
    timeoutRef.current = window.setInterval(updateSparkles, refreshRate);

    // Cleanup function
    return () => {
      if (timeoutRef.current !== null) {
        window.clearInterval(timeoutRef.current);
        timeoutRef.current = null;
      }
    };
  }, [
    colors,
    minSize,
    maxSize,
    sparkleCount,
    prefersReducedMotion,
    lowPowerMode,
    animationsDisabled,
  ]);

  // Don't render animations for reduced motion, low power, or when disabled
  if (prefersReducedMotion || lowPowerMode || animationsDisabled) {
    return <div className={`relative ${className}`}>{children}</div>;
  }

  return (
    <div
      className={`relative ${className} ${overflow ? "" : "overflow-hidden"}`}
    >
      {children}

      <AnimatePresence>
        {sparkles.map((sparkle) => (
          <motion.div
            key={sparkle.id}
            className="absolute pointer-events-none"
            style={sparkle.style}
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0, opacity: 0 }}
            transition={{
              duration: getAnimationDuration() / 1000, // convert ms to seconds
              ease: "easeInOut",
            }}
          >
            <div
              style={{
                width: `${sparkle.size}px`,
                height: `${sparkle.size}px`,
                position: "relative",
              }}
            >
              <svg
                width="100%"
                height="100%"
                viewBox="0 0 68 68"
                fill="none"
                style={{ transform: `rotate(${Math.random() * 360}deg)` }}
              >
                <path
                  d="M26.5 25.5C19.0043 33.3697 0 34 0 34C0 34 19.1013 35.3684 26.5 43.5C33.234 50.901 34 68 34 68C34 68 36.9884 50.7065 44.5 43.5C51.6431 36.647 68 34 68 34C68 34 51.6947 32.0939 44.5 25.5C36.5605 18.2235 34 0 34 0C34 0 33.1982 18.5571 26.5 25.5Z"
                  fill={sparkle.color}
                />
              </svg>
            </div>
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

export default MagicSparkles;

import React, { useEffect, useState } from "react";
import { useAuth } from "../context/AuthContext";

interface AuthLoadingGateProps {
  children: ReactNode;
  /**
   * Minimum time to show loading state (prevents flash)
   * Default: 100ms
   */
  minLoadingTime?: number;
  /**
   * Custom loading component to show while auth is resolving
   */
  loadingComponent?: ReactNode;
  /**
   * Custom error component to show if auth fails
   */
  errorComponent?: ReactNode;
  /**
   * Callback when auth state is resolved (authenticated or not)
   */
  onAuthResolved?: (isAuthenticated: boolean) => void;
}

/**
 * AuthLoadingGate prevents page flicker by waiting for auth state resolution
 * before rendering children. This is useful for pages that need to know
 * the auth state before deciding what to render.
 *
 * Features:
 * - Minimum loading time to prevent flash
 * - Customizable loading and error states
 * - Callback for auth resolution
 */
const AuthLoadingGate: React.FC<AuthLoadingGateProps> = ({
  children,
  minLoadingTime = 100,
  loadingComponent,
  errorComponent,
  onAuthResolved,
}) => {
  const { loading, authState, isAuthenticated, error } = useAuth();
  const [hasMinLoadingTimePassed, setHasMinLoadingTimePassed] = useState(false);
  const [hasNotifiedResolution, setHasNotifiedResolution] = useState(false);

  // Minimum loading time to prevent flash
  useEffect(() => {
    const timer = setTimeout(() => {
      setHasMinLoadingTimePassed(true);
    }, minLoadingTime);

    return () => clearTimeout(timer);
  }, [minLoadingTime]);

  // Notify when auth is resolved
  useEffect(() => {
    if (!loading && authState !== "idle" && authState !== "loading" && !hasNotifiedResolution) {
      setHasNotifiedResolution(true);
      onAuthResolved?.(isAuthenticated);
    }
  }, [loading, authState, isAuthenticated, hasNotifiedResolution, onAuthResolved]);

  // Default loading component
  const defaultLoadingComponent = (
    <div className="min-h-screen flex flex-col justify-center items-center bg-gray-900 text-white">
      <div className="relative">
        <div className="w-16 h-16 border-t-4 border-primary-500 border-solid rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-primary-500 font-medium text-xs">Loading</span>
        </div>
      </div>
      <p className="mt-3 text-gray-400 text-sm">Initializing...</p>
    </div>
  );

  // Default error component
  const defaultErrorComponent = (
    <div className="min-h-screen flex flex-col justify-center items-center bg-gray-900 text-white">
      <div className="text-center max-w-md px-4">
        <div className="text-red-500 text-4xl mb-4">⚠️</div>
        <h2 className="text-lg font-semibold mb-2">Connection Error</h2>
        <p className="text-gray-400 text-sm mb-4">
          {error?.message || "Unable to verify your session. Please refresh the page."}
        </p>
        <button
          onClick={() => window.location.reload()}
          className="px-4 py-2 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors text-sm"
        >
          Refresh Page
        </button>
      </div>
    </div>
  );

  // Show error state
  if (authState === "error") {
    return <>{errorComponent || defaultErrorComponent}</>;
  }

  // Show loading state until auth is resolved AND minimum time has passed
  if (loading || authState === "loading" || authState === "idle" || !hasMinLoadingTimePassed) {
    return <>{loadingComponent || defaultLoadingComponent}</>;
  }

  // Auth is resolved, render children
  return <>{children}</>;
};

export default AuthLoadingGate;

import React from "react";
import { motion } from "framer-motion";
import MagicSparkles from "./MagicSparkles";

interface FeatureMapProps {
