                          <div className="mb-3">
                            <div className="text-xs text-gray-400 uppercase tracking-wider mb-1">Integrations</div>
                            <div className="text-sm text-gray-200">{gtmContent[app.group].integrationPoints.join(", ")}</div>
                          </div>
