                  {currentStep === 3 && (
                    <div className="space-y-4">
                      <p className="text-gray-300 font-body">Optional: Scan public profiles for '{targetName}'</p>
                      <Button
                        onClick={handleScan}
                        disabled={isScanning || !targetName}
