                  )}

              {/* Navigation */}
              <div className="flex justify-between mt-6">
                <Button
                  onClick={handleBack}
                  disabled={currentStep === 1}
                  variant="secondary"
                  className="bg-gray-700 hover:bg-gray-600 disabled:bg-gray-800 disabled:text-gray-500 text-white"
                >
                  <ChevronLeft className="h-4 w-4 mr-2" />
