                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 font-body">No assets yet</p>
                  )}
                </TabsContent>

                <TabsContent value="raw">
                  {output ? (
                    <pre className="text-xs text-gray-300 max-h-48 overflow-y-auto">
                      {JSON.stringify(output, null, 2).substring(0, 200)}...
