// Animation constants
const ANIMATION_DURATIONS = {
  FAST: 0.3,
  NORMAL: 0.6,
} as const;

// Validation functions
const validateEmail = (email: string): boolean => {
  const emailRegex =
    /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
  return emailRegex.test(email) && email.length <= 254;
};

const validatePassword = (
  password: string,
): { isValid: boolean; strength: number; feedback: string[] } => {
  const feedback: string[] = [];
  let strength = 0;

  if (password.length >= 8) {
    strength++;
  } else {
    feedback.push("At least 8 characters");
  }

  if (/[a-z]/.test(password)) {
    strength++;
  } else {
    feedback.push("One lowercase letter");
  }

  if (/[A-Z]/.test(password)) {
    strength++;
  } else {
    feedback.push("One uppercase letter");
  }

  if (/\d/.test(password)) {
    strength++;
  } else {
    feedback.push("One number");
  }

  if (/[^a-zA-Z\d]/.test(password)) {
    strength++;
  } else {
    feedback.push("One special character");
  }

  return {
    isValid: strength >= 3, // Require at least 3 criteria
    strength,
    feedback,
  };
};

const AdminSignUp: React.FC = () => {
  const { signup, isLoading } = useAdmin();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [announcements, setAnnouncements] = useState<string>("");

  // Focus management
  useEffect(() => {
    const emailInput = document.getElementById("email");
    emailInput?.focus();
  }, []);

  // Clear errors when inputs change
  useEffect(() => {
    if (error) setError(null);
  }, [formData]);

  // Screen reader announcements
  useEffect(() => {
    if (error) {
      setAnnouncements(`Sign up failed: ${error}`);
    } else if (success) {
      setAnnouncements("Sign up successful");
    } else {
      setAnnouncements("");
    }
  }, [error, success]);

  const validateField = useCallback(
    (field: string, value: string) => {
      const errors: Record<string, string> = {};

      switch (field) {
        case "email":
          if (!value.trim()) {
            errors.email = "Email is required";
          } else if (!validateEmail(value)) {
            errors.email = "Please enter a valid email address";
          }
          break;
        case "password":
          if (!value.trim()) {
            errors.password = "Password is required";
          } else {
            const passwordValidation = validatePassword(value);
            if (!passwordValidation.isValid) {
              errors.password = "Password does not meet requirements";
            }
          }
          break;
        case "confirmPassword":
          if (!value.trim()) {
            errors.confirmPassword = "Please confirm your password";
          } else if (value !== formData.password) {
            errors.confirmPassword = "Passwords do not match";
          }
          break;
      }

      setFieldErrors((prev) => ({ ...prev, [field]: errors[field] || "" }));
      return Object.keys(errors).length === 0;
    },
    [formData.password],
  );

  const handleInputChange = useCallback(
    (field: string) => (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value;
      setFormData((prev) => ({ ...prev, [field]: value }));

      // Validate on change if field has been touched
      if (touched[field]) {
        validateField(field, value);
      }
    },
    [touched, validateField],
  );

  const handleBlur = useCallback(
    (field: string) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
      validateField(field, formData[field as keyof typeof formData]);
    },
    [formData, validateField],
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);

    // Mark all fields as touched for validation
    setTouched({ email: true, password: true, confirmPassword: true });

    // Validate all fields
    const isEmailValid = validateField("email", formData.email);
    const isPasswordValid = validateField("password", formData.password);
    const isConfirmValid = validateField(
      "confirmPassword",
      formData.confirmPassword,
    );

    if (!isEmailValid || !isPasswordValid || !isConfirmValid) {
      setError("Please correct the errors below");
      return;
    }

    try {
      const result = await signup(formData.email, formData.password);
      if (result.success) {
        setSuccess("Account created successfully! Redirecting to login...");
        setTimeout(() => navigate("/admin/login"), 2000);
      } else {
        setError(result.error || "Sign up failed");
      }
    } catch (err) {
      setError("Network error occurred. Please try again.");
    }
  };

  return (
    <>
      <Helmet>
        <title>Admin Sign Up | VideoRemix.io</title>
        <meta
          name="description"
          content="Create admin account for VideoRemix.io dashboard."
        />
      </Helmet>

      <div className="min-h-screen bg-gray-900 flex items-center justify-center px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: ANIMATION_DURATIONS.NORMAL }}
          className="max-w-md w-full"
        >
          {/* Header */}
          <div className="text-center mb-8">
            <div className="flex items-center justify-center mb-4">
              <Shield className="h-12 w-12 text-blue-500 mr-3" />
              <h1 className="text-3xl font-bold text-white">Admin Sign Up</h1>
            </div>
            <p className="text-gray-400">
              Create your admin account for VideoRemix.io
            </p>
          </div>

          {/* Sign Up Form */}
          <div className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-8 border border-gray-700">
            <form onSubmit={handleSubmit} className="space-y-6" noValidate>
              {/* Status Messages */}
              {error && (
                <motion.div
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="bg-red-500/20 border border-red-500/50 text-red-400 p-4 rounded-lg flex items-center"
                  role="alert"
                >
                  <XCircle className="h-5 w-5 mr-2 flex-shrink-0" />
                  <span>{error}</span>
                </motion.div>
              )}

              {success && (
                <motion.div
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="bg-green-500/20 border border-green-500/50 text-green-400 p-4 rounded-lg flex items-center"
                  role="status"
                >
                  <CheckCircle className="h-5 w-5 mr-2 flex-shrink-0" />
                  <span>{success}</span>
                </motion.div>
              )}

              {/* Email Field */}
              <div>
                <label
                  htmlFor="email"
                  className="block text-sm font-medium text-gray-300 mb-2"
                >
                  Email Address <span className="text-red-400">*</span>
                </label>
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={handleInputChange("email")}
                  onBlur={handleBlur("email")}
                  className={`w-full bg-gray-700 border rounded-lg px-4 py-3 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-colors ${
                    fieldErrors.email ? "border-red-500" : "border-gray-600"
                  }`}
                  placeholder="admin@videoremix.vip"
                  disabled={isLoading}
                  required
                  aria-describedby={
                    fieldErrors.email ? "email-error" : undefined
                  }
                  aria-invalid={!!fieldErrors.email}
                />
                {fieldErrors.email && (
                  <p
                    id="email-error"
                    className="text-red-400 text-sm mt-1 flex items-center"
                    role="alert"
                  >
                    <XCircle className="h-4 w-4 mr-1" />
                    {fieldErrors.email}
                  </p>
                )}
              </div>

              {/* Password Field */}
              <div>
                <label
                  htmlFor="password"
                  className="block text-sm font-medium text-gray-300 mb-2"
                >
                  Password <span className="text-red-400">*</span>
                </label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    value={formData.password}
                    onChange={handleInputChange("password")}
                    onBlur={handleBlur("password")}
                    className={`w-full bg-gray-700 border rounded-lg px-4 py-3 pr-12 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-colors ${
                      fieldErrors.password
                        ? "border-red-500"
                        : "border-gray-600"
                    }`}
                    placeholder="Create a password"
                    disabled={isLoading}
                    required
                    aria-describedby={
                      fieldErrors.password
                        ? "password-error password-strength"
                        : "password-strength"
                    }
                    aria-invalid={!!fieldErrors.password}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-300 transition-colors focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 focus:ring-offset-gray-700 rounded"
                    disabled={isLoading}
                    aria-label={
                      showPassword ? "Hide password" : "Show password"
                    }
                  >
                    {showPassword ? (
                      <EyeOff className="h-5 w-5" />
                    ) : (
                      <Eye className="h-5 w-5" />
                    )}
                  </button>
                </div>

                {/* Password Strength Indicator */}
                {formData.password && (
                  <div id="password-strength" className="mt-2">
                    <div className="flex items-center space-x-2">
                      <div className="flex-1 bg-gray-700 rounded-full h-2">
                        <div
                          className={`h-2 rounded-full transition-all duration-300 ${
                            validatePassword(formData.password).strength <= 1
                              ? "bg-red-500"
                              : validatePassword(formData.password).strength <=
                                  2
                                ? "bg-orange-500"
                                : validatePassword(formData.password)
                                      .strength <= 3
                                  ? "bg-yellow-500"
                                  : validatePassword(formData.password)
                                        .strength <= 4
                                    ? "bg-blue-500"
                                    : "bg-green-500"
                          }`}
                          style={{
                            width: `${(validatePassword(formData.password).strength / 5) * 100}%`,
                          }}
                        />
                      </div>
                      <span
                        className={`text-xs font-medium ${
                          validatePassword(formData.password).strength <= 1
                            ? "text-red-400"
                            : validatePassword(formData.password).strength <= 2
                              ? "text-orange-400"
                              : validatePassword(formData.password).strength <=
                                  3
                                ? "text-yellow-400"
                                : validatePassword(formData.password)
                                      .strength <= 4
                                  ? "text-blue-400"
                                  : "text-green-400"
