                          (requirement, index) => (
                            <li key={index} className="flex items-center">
                              <XCircle className="h-3 w-3 mr-1 text-red-400" />
                              {requirement}
                            </li>
                          ),
                        )}
                      </ul>
                    )}
                  </div>
                )}

                {fieldErrors.password && (
                  <p
                    id="password-error"
                    className="text-red-400 text-sm mt-1 flex items-center"
                    role="alert"
                  >
                    <XCircle className="h-4 w-4 mr-1" />
                    {fieldErrors.password}
