import React, { useState, useEffect, useCallback, useMemo, memo } from "react";
import { motion } from "framer-motion";
import {
  Settings,
  Plus,
  Edit,
  Trash2,
  ToggleLeft,
  ToggleRight,
  Eye,
  EyeOff,
  ChevronDown,
  AlertTriangle,
  X,
  CheckCircle,
  ExternalLink,
  Copy,
  Globe,
} from "lucide-react";
import { supabase } from "../../utils/supabase";
