const AdminAppsManagement: React.FC = () => {
  const [apps, setApps] = useState<App[]>([]);
  const [allApps, setAllApps] = useState<App[]>([]);
  const [loading, setLoading] = useState(true);
  const [toggling, setToggling] = useState<string | null>(null);
  const [selectedApp, setSelectedApp] = useState<string>("all");
  const [showAppDropdown, setShowAppDropdown] = useState(false);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = appConfig.UI.ITEMS_PER_PAGE; // Show apps per page (4x3 grid)
  const [pagination, setPagination] = useState<PaginationInfo | null>(null);

  // Enhanced state for UX
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [notifications, setNotifications] = useState<
    Array<{
      id: string;
      type: "success" | "error";
      message: string;
    }>
  >([]);
  const [showDeleteModal, setShowDeleteModal] = useState<{
    show: boolean;
    ai-design-studio: App | null;
  }>({ show: false, ai-design-studio: null });
  const [operationLoading, setOperationLoading] = useState<{
    [key: string]: boolean;
  }>({});

  // Utility functions
  const addNotification = useCallback(
    (type: "success" | "error", message: string) => {
      const id = Date.now().toString();
      setNotifications((prev) => [...prev, { id, type, message }]);

      // Auto-remove after 5 seconds
      setTimeout(() => {
        setNotifications((prev) => prev.filter((n) => n.id !== id));
      }, 5000);
    },
    [],
  );

  const clearMessages = useCallback(() => {
    setError(null);
    setSuccess(null);
  }, []);

  // Memoized filtering for better performance
  const filteredApps = useMemo(() => {
    return selectedApp === "all"
      ? allApps
      : allApps.filter((ai-design-studio) => ai-design-studio.slug === selectedApp);
  }, [allApps, selectedApp]);

  useEffect(() => {
    fetchApps();
  }, []);

  // Update apps when filtered results change
  useEffect(() => {
    setApps(filteredApps);
  }, [filteredApps]);

  const fetchApps = useCallback(
    async (page = currentPage) => {
      try {
        clearMessages();

        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();

        if (sessionError || !session) {
          const devToken = localStorage.getItem("admin_token");
          if (devToken === "dev_bypass_token") {
            setError(
              "Dev mode: Using real admin login instead of bypass for API calls",
            );
          } else {
            setError("Authentication required. Please log in again.");
          }
          return;
        }

        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-apps?page=${page}&limit=${itemsPerPage}`,
          {
            headers: {
              Authorization: `Bearer ${session.access_token}`,
            },
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (data.success) {
          setAllApps(data.data || []);
          setPagination(data.pagination || null);
        } else {
          setError(data.error || "Failed to load applications");
        }
      } catch (error) {
        console.error("Error fetching apps:", error);
        setError(
          "Failed to load applications. Please check your connection and try again.",
        );
      } finally {
        setLoading(false);
      }
    },
    [clearMessages, currentPage, itemsPerPage],
  );

  const toggleApp = useCallback(
    async (appId: string, currentStatus: boolean) => {
      setToggling(appId);
      clearMessages();
      setOperationLoading((prev) => ({ ...prev, [appId]: true }));

      try {
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();

        if (sessionError || !session) {
          setError("Authentication required. Please log in again.");
          return;
        }

        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-apps/${appId}/toggle`,
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${session.access_token}`,
              "Content-Type": "application/json",
            },
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (data.success) {
          setAllApps((prevApps) =>
            prevApps.map((ai-design-studio) =>
              ai-design-studio.id === appId ? { ...ai-design-studio, is_active: !currentStatus } : ai-design-studio,
            ),
          );
          addNotification(
            "success",
            `App ${currentStatus ? "deactivated" : "activated"} successfully`,
          );
        } else {
          setError(data.error || "Failed to toggle ai-design-studio status");
        }
      } catch (error) {
        console.error("Error toggling ai-design-studio:", error);
        setError("Failed to toggle ai-design-studio status. Please try again.");
      } finally {
        setToggling(null);
        setOperationLoading((prev) => ({ ...prev, [appId]: false }));
      }
    },
    [clearMessages, addNotification],
  );

  const togglePublicVisibility = useCallback(
    async (appId: string, currentStatus: boolean) => {
      setOperationLoading((prev) => ({ ...prev, [appId]: true }));

      try {
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();

        if (sessionError || !session) {
          setError("Authentication required. Please log in again.");
          return;
        }

        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-apps/${appId}/toggle-public`,
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${session.access_token}`,
              "Content-Type": "application/json",
            },
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (data.success) {
          setAllApps((prevApps) =>
            prevApps.map((ai-design-studio) =>
              ai-design-studio.id === appId ? { ...ai-design-studio, is_public: !currentStatus } : ai-design-studio,
            ),
          );
          addNotification(
            "success",
            `App ${currentStatus ? "made private" : "made public"} successfully`,
          );
        } else {
          setError(data.error || "Failed to toggle public visibility");
        }
      } catch (error) {
        console.error("Error toggling public visibility:", error);
        setError("Failed to toggle public visibility. Please try again.");
      } finally {
        setOperationLoading((prev) => ({ ...prev, [appId]: false }));
      }
    },
    [addNotification],
  );

  const deleteApp = useCallback(
    async (appId: string) => {
      clearMessages();
      setOperationLoading((prev) => ({ ...prev, [appId]: true }));

      try {
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();

        if (sessionError || !session) {
          setError("Authentication required. Please log in again.");
          return;
        }

        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-apps/${appId}`,
          {
            method: "DELETE",
            headers: {
              Authorization: `Bearer ${session.access_token}`,
            },
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (data.success) {
          setAllApps((prevApps) => prevApps.filter((ai-design-studio) => ai-design-studio.id !== appId));
          addNotification("success", "App deleted successfully");
          setShowDeleteModal({ show: false, ai-design-studio: null });
        } else {
          setError(data.error || "Failed to delete ai-design-studio");
        }
      } catch (error) {
        console.error("Error deleting ai-design-studio:", error);
        setError("Failed to delete ai-design-studio. Please try again.");
      } finally {
        setOperationLoading((prev) => ({ ...prev, [appId]: false }));
      }
    },
    [clearMessages, addNotification],
  );

  const openDeleteModal = useCallback((ai-design-studio: App) => {
    setShowDeleteModal({ show: true, ai-design-studio });
  }, []);

  if (loading) {
    return (
      <div className="flex justify-center items-center py-20">
        <div className="w-8 h-8 border-t-2 border-primary-500 border-solid rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Notifications */}
      {notifications.map((notification) => (
        <motion.div
          key={notification.id}
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          className={`p-4 rounded-lg flex items-center justify-between ${
            notification.type === "success"
              ? "bg-green-500/20 border border-green-500/50 text-green-400"
              : "bg-red-500/20 border border-red-500/50 text-red-400"
          }`}
        >
          <div className="flex items-center">
            {notification.type === "success" ? (
              <CheckCircle className="h-5 w-5 mr-2" />
            ) : (
              <X className="h-5 w-5 mr-2" />
            )}
            <span>{notification.message}</span>
          </div>
          <button
            onClick={() =>
              setNotifications((prev) =>
                prev.filter((n) => n.id !== notification.id),
              )
            }
            className="text-gray-400 hover:text-white"
          >
            <X className="h-4 w-4" />
          </button>
        </motion.div>
      ))}

      {/* Error Message */}
      {error && (
        <div className="bg-red-500/20 border border-red-500/50 text-red-400 p-4 rounded-lg flex items-center justify-between">
          <div className="flex items-center">
            <AlertTriangle className="h-5 w-5 mr-2" />
            <span>{error}</span>
          </div>
          <button
            onClick={() => setError(null)}
            className="text-red-400 hover:text-red-300"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">
            Applications Management
          </h2>
          <p className="text-gray-400">
            Manage and configure your deployed applications
          </p>
        </div>
        <div className="flex items-center space-x-4">
          {/* App Selector */}
          <div className="relative">
            <button
              onClick={() => setShowAppDropdown(!showAppDropdown)}
              className="bg-gray-800 hover:bg-gray-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors border border-gray-600"
            >
              <span className="mr-2">
                {selectedApp === "all"
                  ? "All Apps"
                  : allApps.find((ai-design-studio) => ai-design-studio.slug === selectedApp)?.name ||
                    "Select App"}
              </span>
              <ChevronDown className="h-4 w-4" />
            </button>

            {showAppDropdown && (
              <div className="absolute right-0 mt-2 w-64 bg-gray-800 border border-gray-600 rounded-lg shadow-lg z-10">
                <div className="py-1">
                  <button
                    onClick={() => {
                      setSelectedApp("all");
                      setShowAppDropdown(false);
                    }}
                    className="w-full text-left px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                  >
                    All Apps
                  </button>
                  {allApps.map((ai-design-studio) => (
                    <button
                      key={ai-design-studio.id}
                      onClick={() => {
                        setSelectedApp(ai-design-studio.slug);
                        setShowAppDropdown(false);
                      }}
                      className="w-full text-left px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                    >
                      <div className="flex items-center justify-between">
                        <span>{ai-design-studio.name}</span>
                        {ai-design-studio.is_active ? (
                          <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                        ) : (
                          <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                        )}
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          <button className="bg-primary-600 hover:bg-primary-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors">
            <Plus className="h-4 w-4 mr-2" />
            Add App
          </button>
        </div>
      </div>

      {/* Apps Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {apps.map((ai-design-studio) => (
          <motion.div
            key={ai-design-studio.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-6 border border-gray-700 hover:border-gray-600 transition-colors"
          >
            {/* App Header */}
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center space-x-3">
                <div className="w-12 h-12 bg-gray-700 rounded-lg flex items-center justify-center">
                  {ai-design-studio.icon_url ? (
                    <img
                      src={ai-design-studio.icon_url}
                      alt={ai-design-studio.name}
                      className="w-8 h-8 rounded"
                    />
                  ) : (
                    <Settings className="h-6 w-6 text-gray-400" />
                  )}
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-white">
                    {ai-design-studio.name}
                  </h3>
                  <p className="text-sm text-gray-400">{ai-design-studio.category}</p>
                </div>
              </div>

              {/* Status Badge */}
              <div
                className={`px-2 py-1 rounded-full text-xs font-medium ${
                  ai-design-studio.is_active
                    ? "bg-green-500/20 text-green-400"
                    : "bg-red-500/20 text-red-400"
                }`}
              >
                {ai-design-studio.is_active ? "Active" : "Inactive"}
              </div>
            </div>

            {/* Description */}
            <p className="text-gray-300 text-sm mb-4 line-clamp-2">
              {ai-design-studio.description || "No description available"}
            </p>

            {/* Deployment URLs */}
            <div className="mb-4 space-y-2">
              {ai-design-studio.netlify_url && (
                <div className="flex items-center text-xs bg-gray-700/50 rounded px-2 py-1.5">
                  <Globe className="h-3 w-3 text-blue-400 mr-2 flex-shrink-0" />
                  <span className="text-gray-300 truncate flex-1">
                    {ai-design-studio.netlify_url}
                  </span>
                  <button
                    onClick={() => {
                      navigator.clipboard.writeText(ai-design-studio.netlify_url!);
                      addNotification("success", "Netlify URL copied!");
                    }}
                    className="ml-2 p-1 hover:bg-gray-600 rounded transition-colors"
                    title="Copy Netlify URL"
                  >
                    <Copy className="h-3 w-3 text-gray-400" />
                  </button>
                  <a
                    href={ai-design-studio.netlify_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="ml-1 p-1 hover:bg-gray-600 rounded transition-colors"
                    title="Open Netlify URL"
                  >
                    <ExternalLink className="h-3 w-3 text-gray-400" />
                  </a>
                </div>
              )}
              {ai-design-studio.custom_domain && (
                <div className="flex items-center text-xs bg-gray-700/50 rounded px-2 py-1.5">
                  <Globe className="h-3 w-3 text-green-400 mr-2 flex-shrink-0" />
                  <span className="text-gray-300 truncate flex-1">
                    {ai-design-studio.custom_domain}
                  </span>
                  <button
                    onClick={() => {
                      navigator.clipboard.writeText(ai-design-studio.custom_domain!);
                      addNotification("success", "Custom domain copied!");
                    }}
                    className="ml-2 p-1 hover:bg-gray-600 rounded transition-colors"
                    title="Copy custom domain"
                  >
                    <Copy className="h-3 w-3 text-gray-400" />
                  </button>
                  <a
                    href={ai-design-studio.custom_domain}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="ml-1 p-1 hover:bg-gray-600 rounded transition-colors"
                    title="Open custom domain"
                  >
                    <ExternalLink className="h-3 w-3 text-gray-400" />
                  </a>
                </div>
              )}
              {!ai-design-studio.netlify_url && !ai-design-studio.custom_domain && (
                <div className="text-xs text-gray-500 italic">
                  No deployment URLs configured
                </div>
              )}
