            </div>

            {/* Actions */}
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <button className="p-2 text-gray-400 hover:text-white hover:bg-gray-700 rounded-lg transition-colors">
                  <Edit className="h-4 w-4" />
                </button>
                <button
                  onClick={() => openDeleteModal(ai-design-studio)}
                  disabled={operationLoading[ai-design-studio.id]}
                  className="p-2 text-gray-400 hover:text-red-400 hover:bg-gray-700 rounded-lg transition-colors disabled:opacity-50"
                >
                  {operationLoading[ai-design-studio.id] ? (
                    <div className="w-4 h-4 border-t border-red-400 border-solid rounded-full animate-spin"></div>
                  ) : (
                    <Trash2 className="h-4 w-4" />
                  )}
                </button>
              </div>

              {/* Controls */}
              <div className="flex items-center space-x-3">
                {/* Public Visibility Toggle */}
                <div className="flex items-center space-x-2">
                  <Eye className="h-4 w-4 text-gray-400" />
                  <button
                    onClick={() =>
                      togglePublicVisibility(ai-design-studio.id, ai-design-studio.is_public)
                    }
                    disabled={operationLoading[ai-design-studio.id]}
                    className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
                      ai-design-studio.is_public ? "bg-blue-600" : "bg-gray-600"
                    } ${operationLoading[ai-design-studio.id] ? "opacity-50 cursor-not-allowed" : ""}`}
                    title={ai-design-studio.is_public ? "Make private" : "Make public"}
                  >
                    <span
                      className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${
                        ai-design-studio.is_public ? "translate-x-5" : "translate-x-1"
                      }`}
                    />
                  </button>
                </div>

                {/* Active Status Toggle */}
                <button
                  onClick={() => toggleApp(ai-design-studio.id, ai-design-studio.is_active)}
                  disabled={toggling === ai-design-studio.id}
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 ${
                    ai-design-studio.is_active ? "bg-green-600" : "bg-gray-600"
                  } ${toggling === ai-design-studio.id ? "opacity-50 cursor-not-allowed" : ""}`}
                  title={ai-design-studio.is_active ? "Deactivate ai-design-studio" : "Activate ai-design-studio"}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      ai-design-studio.is_active ? "translate-x-6" : "translate-x-1"
                    }`}
                  />
                  {toggling === ai-design-studio.id && (
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-3 h-3 border-t border-white border-solid rounded-full animate-spin"></div>
                    </div>
                  )}
                </button>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {apps.length === 0 && !loading && (
        <div className="text-center py-20">
          <Settings className="h-16 w-16 text-gray-600 mx-auto mb-4" />
          <h3 className="text-xl font-semibold text-white mb-2">
            No applications found
          </h3>
          <p className="text-gray-400">
            Get started by adding your first application.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex items-center justify-between mt-8">
          <div className="text-sm text-gray-400">
            Showing {(pagination.page - 1) * pagination.limit + 1} to{" "}
            {Math.min(pagination.page * pagination.limit, pagination.total)} of{" "}
            {pagination.total} apps
          </div>
          <div className="flex items-center space-x-2">
            <button
              onClick={() => {
                const newPage = currentPage - 1;
                setCurrentPage(newPage);
                fetchApps(newPage);
              }}
              disabled={currentPage === 1 || loading}
              className="px-3 py-2 bg-gray-800 hover:bg-gray-700 disabled:bg-gray-900 disabled:cursor-not-allowed text-white rounded-lg transition-colors border border-gray-600"
            >
              Previous
            </button>

            {/* Page numbers */}
            <div className="flex items-center space-x-1">
              {Array.from(
                { length: Math.min(5, pagination.totalPages) },
                (_, i) => {
                  const pageNum =
                    Math.max(
                      1,
                      Math.min(pagination.totalPages - 4, currentPage - 2),
                    ) + i;
                  if (pageNum > pagination.totalPages) return null;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => {
                        setCurrentPage(pageNum);
                        fetchApps(pageNum);
                      }}
                      disabled={loading}
                      className={`px-3 py-2 rounded-lg transition-colors border ${
                        currentPage === pageNum
                          ? "bg-primary-600 border-primary-500 text-white"
                          : "bg-gray-800 hover:bg-gray-700 border-gray-600 text-white disabled:cursor-not-allowed"
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                },
              )}
            </div>

            <button
              onClick={() => {
                const newPage = currentPage + 1;
                setCurrentPage(newPage);
                fetchApps(newPage);
              }}
              disabled={currentPage === pagination.totalPages || loading}
              className="px-3 py-2 bg-gray-800 hover:bg-gray-700 disabled:bg-gray-900 disabled:cursor-not-allowed text-white rounded-lg transition-colors border border-gray-600"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal.show && showDeleteModal.ai-design-studio && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-gray-800 rounded-lg p-6 max-w-md mx-4 border border-gray-700"
          >
            <div className="flex items-center mb-4">
              <AlertTriangle className="h-6 w-6 text-red-400 mr-3" />
              <h3 className="text-lg font-semibold text-white">
                Delete Application
              </h3>
            </div>
            <p className="text-gray-300 mb-6">
              Are you sure you want to delete{" "}
              <strong>{showDeleteModal.ai-design-studio.name}</strong>? This action cannot be
              undone and will remove all associated data.
            </p>
            <div className="flex space-x-3">
              <button
                onClick={() => setShowDeleteModal({ show: false, ai-design-studio: null })}
                className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() =>
                  showDeleteModal.ai-design-studio && deleteApp(showDeleteModal.ai-design-studio.id)
                }
                disabled={operationLoading[showDeleteModal.ai-design-studio.id]}
                className="flex-1 bg-red-600 hover:bg-red-700 text-white py-2 rounded-lg transition-colors disabled:opacity-50"
              >
                {operationLoading[showDeleteModal.ai-design-studio.id]
                  ? "Deleting..."
                  : "Delete App"}
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
};

export default AdminAppsManagement;

import React, { useState, useEffect, useCallback, useMemo, memo } from "react";
import { motion } from "framer-motion";
import {
  ToggleLeft,
  ToggleRight,
  Plus,
  Edit,
  Trash2,
  Settings,
  ChevronDown,
  AlertTriangle,
  X,
  CheckCircle,
  Shield,
} from "lucide-react";
import { supabase } from "../../utils/supabase";
import { useAdmin } from "../../context/AdminContext";

interface Feature {
  id: string;
  name: string;
  slug: string;
  description: string;
  is_enabled: boolean;
  app_slug?: string;
  app_name?: string;
  parent_app_id?: string;
  config: Record<string, any>;
  created_at: string;
  updated_at: string;
}

const AdminFeaturesManagement: React.FC = () => {
  const { user } = useAdmin();
  const [features, setFeatures] = useState<Feature[]>([]);
  const [allFeatures, setAllFeatures] = useState<Feature[]>([]);
  const [apps, setApps] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [toggling, setToggling] = useState<string | null>(null);
  const [selectedApp, setSelectedApp] = useState<string>("all");
  const [showAppDropdown, setShowAppDropdown] = useState(false);

  // Enhanced state for UX
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [notifications, setNotifications] = useState<
    Array<{
      id: string;
      type: "success" | "error";
      message: string;
    }>
  >([]);
  const [showDeleteModal, setShowDeleteModal] = useState<{
    show: boolean;
    feature: Feature | null;
  }>({ show: false, feature: null });
  const [operationLoading, setOperationLoading] = useState<{
    [key: string]: boolean;
  }>({});
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState<{
    show: boolean;
    feature: Feature | null;
  }>({ show: false, feature: null });
  const [formData, setFormData] = useState({
    name: "",
    slug: "",
    description: "",
    parent_app_id: "",
    is_enabled: true,
    config: "{}",
  });

  // Utility functions
  const addNotification = useCallback(
    (type: "success" | "error", message: string) => {
      const id = Date.now().toString();
      setNotifications((prev) => [...prev, { id, type, message }]);

      // Auto-remove after 5 seconds
      setTimeout(() => {
        setNotifications((prev) => prev.filter((n) => n.id !== id));
      }, 5000);
    },
    [],
  );

  const clearMessages = useCallback(() => {
    setError(null);
    setSuccess(null);
  }, []);

  // Memoized filtering for better performance
  const filteredFeatures = useMemo(() => {
    if (selectedApp === "all") {
      return allFeatures;
    }
    // Find the ai-design-studio ID for the selected ai-design-studio slug
    const selectedAppData = apps.find((ai-design-studio) => ai-design-studio.slug === selectedApp);
    return selectedAppData
      ? allFeatures.filter(
          (feature) => feature.parent_app_id === selectedAppData.id,
        )
      : allFeatures;
  }, [allFeatures, selectedApp, apps]);

  useEffect(() => {
    fetchFeatures();
    fetchApps();
  }, []);

  // Update features when filtered results change
  useEffect(() => {
    setFeatures(filteredFeatures);
  }, [filteredFeatures]);

  const fetchFeatures = useCallback(async () => {
    try {
      clearMessages();
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();

      if (sessionError || !session) {
        setError("Authentication required. Please log in again.");
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-features`,
        {
          headers: {
            Authorization: `Bearer ${session.access_token}`,
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setAllFeatures(data.data || []);
      } else {
        setError(data.error || "Failed to load features");
      }
    } catch (error) {
      console.error("Error fetching features:", error);
      setError(
        "Failed to load features. Please check your connection and try again.",
      );
    } finally {
      setLoading(false);
    }
  }, [clearMessages]);

  const fetchApps = useCallback(async () => {
    try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();

      if (sessionError || !session) return;

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-apps`,
        {
          headers: {
            Authorization: `Bearer ${session.access_token}`,
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setApps(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching apps:", error);
    }
  }, []);

  const openAddModal = useCallback(() => {
    setFormData({
      name: "",
      slug: "",
      description: "",
      parent_app_id: "",
      is_enabled: true,
      config: "{}",
    });
    setShowAddModal(true);
  }, []);

  const openEditModal = useCallback((feature: Feature) => {
    setFormData({
      name: feature.name,
      slug: feature.slug,
      description: feature.description,
      parent_app_id: feature.parent_app_id || "",
      is_enabled: feature.is_enabled,
      config: JSON.stringify(feature.config, null, 2),
    });
    setShowEditModal({ show: true, feature });
  }, []);

  const createFeature = useCallback(async () => {
    clearMessages();
    setOperationLoading((prev) => ({ ...prev, create: true }));

    try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (sessionError || !session) {
        setError("Authentication required. Please log in again.");
        return;
      }
      const token = session.access_token;

      let parsedConfig = {};
      try {
        parsedConfig = JSON.parse(formData.config);
      } catch (e) {
        setError("Invalid JSON in config field");
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-features`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            name: formData.name,
            slug: formData.slug,
            description: formData.description,
            parent_app_id: formData.parent_app_id || null,
            is_enabled: formData.is_enabled,
            config: parsedConfig,
          }),
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setAllFeatures((prevFeatures) => [data.data, ...prevFeatures]);
        addNotification("success", "Feature created successfully");
        setShowAddModal(false);
      } else {
        setError(data.error || "Failed to create feature");
      }
    } catch (error) {
      console.error("Error creating feature:", error);
      setError("Failed to create feature. Please try again.");
    } finally {
      setOperationLoading((prev) => ({ ...prev, create: false }));
    }
  }, [formData, clearMessages, addNotification]);

  const updateFeature = useCallback(async () => {
    if (!showEditModal.feature) return;

    clearMessages();
    setOperationLoading((prev) => ({
      ...prev,
      [showEditModal.feature!.id]: true,
    }));

    try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (sessionError || !session) {
        setError("Authentication required. Please log in again.");
        return;
      }
      const token = session.access_token;

      let parsedConfig = {};
      try {
        parsedConfig = JSON.parse(formData.config);
      } catch (e) {
        setError("Invalid JSON in config field");
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-features/${showEditModal.feature.id}`,
        {
          method: "PUT",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            name: formData.name,
            slug: formData.slug,
            description: formData.description,
            parent_app_id: formData.parent_app_id || null,
            is_enabled: formData.is_enabled,
            config: parsedConfig,
          }),
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setAllFeatures((prevFeatures) =>
          prevFeatures.map((f) =>
            f.id === showEditModal.feature!.id ? data.data : f,
          ),
        );
        addNotification("success", "Feature updated successfully");
        setShowEditModal({ show: false, feature: null });
      } else {
        setError(data.error || "Failed to update feature");
      }
    } catch (error) {
      console.error("Error updating feature:", error);
      setError("Failed to update feature. Please try again.");
    } finally {
      setOperationLoading((prev) => ({
        ...prev,
        [showEditModal.feature!.id]: false,
      }));
    }
  }, [formData, showEditModal, clearMessages, addNotification]);

  const toggleFeature = useCallback(
    async (featureId: string, currentStatus: boolean) => {
      setToggling(featureId);
      clearMessages();
      setOperationLoading((prev) => ({ ...prev, [featureId]: true }));

      try {
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();
        if (sessionError || !session) {
          setError("Authentication required. Please log in again.");
          return;
        }
        const token = session.access_token;

        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-features/${featureId}/toggle`,
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${token}`,
            },
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (data.success) {
          setAllFeatures((prevFeatures) =>
            prevFeatures.map((feature) =>
              feature.id === featureId
                ? { ...feature, is_enabled: data.data.is_enabled }
                : feature,
            ),
          );
          addNotification(
            "success",
            `Feature ${currentStatus ? "disabled" : "enabled"} successfully`,
          );
        } else {
          setError(data.error || "Failed to toggle feature status");
        }
      } catch (error) {
        console.error("Error toggling feature:", error);
        setError("Failed to toggle feature status. Please try again.");
      } finally {
        setToggling(null);
        setOperationLoading((prev) => ({ ...prev, [featureId]: false }));
      }
    },
    [clearMessages, addNotification],
  );

  const deleteFeature = useCallback(
    async (featureId: string) => {
      clearMessages();
      setOperationLoading((prev) => ({ ...prev, [featureId]: true }));

      try {
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();
        if (sessionError || !session) {
          setError("Authentication required. Please log in again.");
          return;
        }
        const token = session.access_token;

        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-features`,
          {
            method: "DELETE",
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ id: featureId }),
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (data.success) {
          setAllFeatures((prevFeatures) =>
            prevFeatures.filter((feature) => feature.id !== featureId),
          );
          addNotification("success", "Feature deleted successfully");
          setShowDeleteModal({ show: false, feature: null });
        } else {
          setError(data.error || "Failed to delete feature");
        }
      } catch (error) {
        console.error("Error deleting feature:", error);
        setError("Failed to delete feature. Please try again.");
      } finally {
        setOperationLoading((prev) => ({ ...prev, [featureId]: false }));
      }
    },
    [clearMessages, addNotification],
  );

  const openDeleteModal = useCallback((feature: Feature) => {
    setShowDeleteModal({ show: true, feature });
  }, []);

  if (loading) {
    return (
      <div className="flex justify-center items-center py-20">
        <div className="w-8 h-8 border-t-2 border-primary-500 border-solid rounded-full animate-spin"></div>
      </div>
    );
  }

  // Check if user is super admin for feature toggling
  if (user?.role !== "super_admin") {
    return (
      <div className="space-y-6">
        <div className="bg-yellow-500/20 border border-yellow-500/50 text-yellow-400 p-6 rounded-lg">
          <div className="flex items-center mb-4">
            <Shield className="h-6 w-6 mr-3" />
            <h3 className="text-lg font-semibold">
              Super Admin Access Required
            </h3>
          </div>
          <p className="text-sm">
            Feature toggling is restricted to super administrators only. You can
            view features but cannot modify their enabled/disabled status.
          </p>
        </div>

        {/* Show features in read-only mode */}
        <div className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-8 border border-gray-700">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-white flex items-center">
              <Settings className="h-6 w-6 mr-3 text-blue-500" />
              Features Management
            </h2>
          </div>

          {features.length === 0 ? (
            <div className="text-center py-12">
              <Settings className="h-16 w-16 mx-auto mb-4 text-gray-600" />
              <p className="text-gray-400 text-lg">No features found</p>
            </div>
          ) : (
            <div className="space-y-4">
              {features.map((feature) => (
                <div key={feature.id} className="bg-gray-700/50 rounded-lg p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <div className="flex items-center">
                        <span className="text-white font-medium">
                          {feature.name}
                        </span>
                        <span
                          className={`ml-3 px-2 py-1 text-xs rounded ${
                            feature.is_enabled
                              ? "bg-green-500/20 text-green-400"
                              : "bg-red-500/20 text-red-400"
                          }`}
                        >
                          {feature.is_enabled ? "Enabled" : "Disabled"}
                        </span>
                      </div>
                      {feature.description && (
                        <p className="text-gray-400 text-sm mt-1">
                          {feature.description}
                        </p>
                      )}
                      {feature.app_name && (
                        <p className="text-blue-400 text-xs mt-1">
                          App: {feature.app_name}
                        </p>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Notifications */}
      {notifications.map((notification) => (
        <motion.div
          key={notification.id}
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          className={`p-4 rounded-lg flex items-center justify-between ${
            notification.type === "success"
              ? "bg-green-500/20 border border-green-500/50 text-green-400"
              : "bg-red-500/20 border border-red-500/50 text-red-400"
          }`}
        >
          <div className="flex items-center">
            {notification.type === "success" ? (
              <CheckCircle className="h-5 w-5 mr-2" />
            ) : (
              <X className="h-5 w-5 mr-2" />
            )}
            <span>{notification.message}</span>
          </div>
          <button
            onClick={() =>
              setNotifications((prev) =>
                prev.filter((n) => n.id !== notification.id),
              )
            }
            className="text-gray-400 hover:text-white"
          >
            <X className="h-4 w-4" />
          </button>
        </motion.div>
      ))}

      {/* Error Message */}
      {error && (
        <div className="bg-red-500/20 border border-red-500/50 text-red-400 p-4 rounded-lg flex items-center justify-between">
          <div className="flex items-center">
            <AlertTriangle className="h-5 w-5 mr-2" />
            <span>{error}</span>
          </div>
          <button
            onClick={() => setError(null)}
            className="text-red-400 hover:text-red-300"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">
            Features Management
          </h2>
          <p className="text-gray-400">
            Control which features are available for each ai-design-studio
          </p>
        </div>
        <div className="flex items-center space-x-4">
          {/* App Selector */}
          <div className="relative">
            <button
              onClick={() => setShowAppDropdown(!showAppDropdown)}
              className="bg-gray-800 hover:bg-gray-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors border border-gray-600"
            >
              <span className="mr-2">
                {selectedApp === "all"
                  ? "All Features"
                  : apps.find((ai-design-studio) => ai-design-studio.slug === selectedApp)?.name ||
                    "Select App"}
              </span>
              <ChevronDown className="h-4 w-4" />
            </button>

            {showAppDropdown && (
              <div className="absolute right-0 mt-2 w-64 bg-gray-800 border border-gray-600 rounded-lg shadow-lg z-10">
                <div className="py-1">
                  <button
                    onClick={() => {
                      setSelectedApp("all");
                      setShowAppDropdown(false);
                    }}
                    className="w-full text-left px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                  >
                    All Features
                  </button>
                  {apps.map((ai-design-studio) => (
                    <button
                      key={ai-design-studio.id}
                      onClick={() => {
                        setSelectedApp(ai-design-studio.slug);
                        setShowAppDropdown(false);
                      }}
                      className="w-full text-left px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                    >
                      <div className="flex items-center justify-between">
                        <span>{ai-design-studio.name}</span>
                        {ai-design-studio.is_active ? (
                          <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                        ) : (
                          <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                        )}
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          <button
            onClick={openAddModal}
            className="bg-primary-600 hover:bg-primary-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors"
          >
            <Plus className="h-4 w-4 mr-2" />
            Add Feature
          </button>
        </div>
      </div>

      {/* Features List */}
      <div className="space-y-4">
        {features.map((feature) => (
          <motion.div
            key={feature.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-6 border border-gray-700 hover:border-gray-600 transition-colors"
          >
            <div className="flex items-center justify-between">
              {/* Feature Info */}
              <div className="flex-1">
                <div className="flex items-center space-x-3 mb-2">
                  <div className="w-10 h-10 bg-gray-700 rounded-lg flex items-center justify-center">
                    <ToggleLeft className="h-5 w-5 text-gray-400" />
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold text-white">
                      {feature.name}
                    </h3>
                    <p className="text-sm text-gray-400">{feature.slug}</p>
                  </div>
                </div>

                {feature.description && (
                  <p className="text-gray-300 text-sm mb-3">
                    {feature.description}
                  </p>
                )}

                {/* Config Preview */}
                {feature.config && Object.keys(feature.config).length > 0 && (
                  <div className="mb-3">
                    <p className="text-xs text-gray-500 mb-1">Configuration:</p>
                    <div className="bg-gray-900/50 rounded p-2 text-xs text-gray-400 font-mono">
                      {JSON.stringify(feature.config, null, 2).slice(0, 100)}
                      {JSON.stringify(feature.config).length > 100 && "..."}
                    </div>
                  </div>
                )}

                {/* Status */}
                <div className="flex items-center space-x-2">
                  <span
                    className={`px-2 py-1 rounded-full text-xs font-medium ${
                      feature.is_enabled
                        ? "bg-green-500/20 text-green-400"
                        : "bg-red-500/20 text-red-400"
                    }`}
                  >
                    {feature.is_enabled ? "Enabled" : "Disabled"}
                  </span>
                  <span className="text-xs text-gray-500">
                    Updated: {new Date(feature.updated_at).toLocaleDateString()}
                  </span>
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center space-x-3 ml-6">
                <button
                  onClick={() => openEditModal(feature)}
                  className="p-2 text-gray-400 hover:text-white hover:bg-gray-700 rounded-lg transition-colors"
                >
                  <Edit className="h-4 w-4" />
                </button>
                <button
                  onClick={() => openDeleteModal(feature)}
                  disabled={operationLoading[feature.id]}
                  className="p-2 text-gray-400 hover:text-red-400 hover:bg-gray-700 rounded-lg transition-colors disabled:opacity-50"
                >
                  {operationLoading[feature.id] ? (
                    <div className="w-4 h-4 border-t border-red-400 border-solid rounded-full animate-spin"></div>
                  ) : (
                    <Trash2 className="h-4 w-4" />
                  )}
                </button>

                {/* Toggle Switch */}
                <button
                  onClick={() => toggleFeature(feature.id, feature.is_enabled)}
                  disabled={toggling === feature.id}
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 ${
                    feature.is_enabled ? "bg-green-600" : "bg-gray-600"
                  } ${toggling === feature.id ? "opacity-50 cursor-not-allowed" : ""}`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      feature.is_enabled ? "translate-x-6" : "translate-x-1"
                    }`}
                  />
                  {toggling === feature.id && (
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-3 h-3 border-t border-white border-solid rounded-full animate-spin"></div>
                    </div>
                  )}
                </button>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {features.length === 0 && (
        <div className="text-center py-20">
          <ToggleLeft className="h-16 w-16 text-gray-600 mx-auto mb-4" />
          <h3 className="text-xl font-semibold text-white mb-2">
            No features found
          </h3>
          <p className="text-gray-400">
            Get started by adding your first feature.
          </p>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal.show && showDeleteModal.feature && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-gray-800 rounded-lg p-6 max-w-md mx-4 border border-gray-700"
          >
            <div className="flex items-center mb-4">
              <AlertTriangle className="h-6 w-6 text-red-400 mr-3" />
              <h3 className="text-lg font-semibold text-white">
                Delete Feature
              </h3>
            </div>
            <p className="text-gray-300 mb-6">
              Are you sure you want to delete{" "}
              <strong>{showDeleteModal.feature.name}</strong>? This action
              cannot be undone and will affect all associated applications.
            </p>
            <div className="flex space-x-3">
              <button
                onClick={() =>
                  setShowDeleteModal({ show: false, feature: null })
                }
                className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() =>
                  showDeleteModal.feature &&
                  deleteFeature(showDeleteModal.feature.id)
                }
                disabled={operationLoading[showDeleteModal.feature.id]}
                className="flex-1 bg-red-600 hover:bg-red-700 text-white py-2 rounded-lg transition-colors disabled:opacity-50"
              >
                {operationLoading[showDeleteModal.feature.id]
                  ? "Deleting..."
                  : "Delete Feature"}
              </button>
            </div>
          </motion.div>
        </div>
      )}

      {/* Add Feature Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-gray-800 rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto border border-gray-700"
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-white">
                Add New Feature
              </h3>
              <button
                onClick={() => setShowAddModal(false)}
                className="text-gray-400 hover:text-white"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Name *
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white"
                  placeholder="AI Video Generator"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Slug *
                </label>
                <input
                  type="text"
                  value={formData.slug}
                  onChange={(e) =>
                    setFormData({ ...formData, slug: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white"
                  placeholder="ai-video-generator"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Description
                </label>
                <textarea
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white h-24"
                  placeholder="Feature description..."
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Parent App *
                </label>
                <select
                  value={formData.parent_app_id}
                  onChange={(e) =>
                    setFormData({ ...formData, parent_app_id: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white"
                >
                  <option value="">Select Parent App</option>
                  {apps
                    .filter((ai-design-studio) => ai-design-studio.item_type === "ai-design-studio")
                    .map((ai-design-studio) => (
                      <option key={ai-design-studio.id} value={ai-design-studio.id}>
                        {ai-design-studio.name} ({ai-design-studio.slug})
                      </option>
                    ))}
                </select>
                <p className="text-xs text-gray-400 mt-1">
                  Features must belong to a parent application
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Configuration (JSON)
                </label>
                <textarea
                  value={formData.config}
                  onChange={(e) =>
                    setFormData({ ...formData, config: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white font-mono text-sm h-32"
                  placeholder='{"key": "value"}'
                />
              </div>

              <div className="flex items-center">
                <input
                  type="checkbox"
                  id="enabled"
                  checked={formData.is_enabled}
                  onChange={(e) =>
                    setFormData({ ...formData, is_enabled: e.target.checked })
                  }
                  className="w-4 h-4 text-primary-600 bg-gray-700 border-gray-600 rounded focus:ring-primary-500"
                />
                <label htmlFor="enabled" className="ml-2 text-sm text-gray-300">
                  Enable this feature
                </label>
              </div>
            </div>

            <div className="flex space-x-3 mt-6">
              <button
                onClick={() => setShowAddModal(false)}
                className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={createFeature}
                disabled={
                  operationLoading.create ||
                  !formData.name ||
                  !formData.slug ||
                  !formData.parent_app_id
                }
                className="flex-1 bg-primary-600 hover:bg-primary-700 text-white py-2 rounded-lg transition-colors disabled:opacity-50"
              >
                {operationLoading.create ? "Creating..." : "Create Feature"}
              </button>
            </div>
          </motion.div>
        </div>
      )}

      {/* Edit Feature Modal */}
      {showEditModal.show && showEditModal.feature && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-gray-800 rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto border border-gray-700"
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-white">Edit Feature</h3>
              <button
                onClick={() => setShowEditModal({ show: false, feature: null })}
                className="text-gray-400 hover:text-white"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Name *
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Slug *
                </label>
                <input
                  type="text"
                  value={formData.slug}
                  onChange={(e) =>
                    setFormData({ ...formData, slug: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Description
                </label>
                <textarea
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white h-24"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Parent App *
                </label>
                <select
                  value={formData.parent_app_id}
                  onChange={(e) =>
                    setFormData({ ...formData, parent_app_id: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white"
                >
                  <option value="">Select Parent App</option>
                  {apps
                    .filter((ai-design-studio) => ai-design-studio.item_type === "ai-design-studio")
                    .map((ai-design-studio) => (
                      <option key={ai-design-studio.id} value={ai-design-studio.id}>
                        {ai-design-studio.name} ({ai-design-studio.slug})
                      </option>
                    ))}
                </select>
                <p className="text-xs text-gray-400 mt-1">
                  Features must belong to a parent application
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">
                  Configuration (JSON)
                </label>
                <textarea
                  value={formData.config}
                  onChange={(e) =>
                    setFormData({ ...formData, config: e.target.value })
                  }
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-white font-mono text-sm h-32"
                />
              </div>

              <div className="flex items-center">
                <input
                  type="checkbox"
                  id="enabled-edit"
                  checked={formData.is_enabled}
                  onChange={(e) =>
                    setFormData({ ...formData, is_enabled: e.target.checked })
                  }
                  className="w-4 h-4 text-primary-600 bg-gray-700 border-gray-600 rounded focus:ring-primary-500"
                />
                <label
                  htmlFor="enabled-edit"
                  className="ml-2 text-sm text-gray-300"
                >
                  Enable this feature
                </label>
              </div>
            </div>

            <div className="flex space-x-3 mt-6">
              <button
                onClick={() => setShowEditModal({ show: false, feature: null })}
                className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={updateFeature}
                disabled={
                  operationLoading[showEditModal.feature.id] ||
                  !formData.name ||
                  !formData.slug ||
                  !formData.parent_app_id
                }
                className="flex-1 bg-primary-600 hover:bg-primary-700 text-white py-2 rounded-lg transition-colors disabled:opacity-50"
              >
                {operationLoading[showEditModal.feature.id]
                  ? "Updating..."
                  : "Update Feature"}
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
};

export default AdminFeaturesManagement;

import React, { useState, useEffect, useMemo, useCallback } from "react";
import { motion } from "framer-motion";
import {
  ShoppingCart,
  Download,
  Upload,
  Filter,
  ChevronDown,
  AlertTriangle,
  X,
  CheckCircle,
  Eye,
  RefreshCw,
  DollarSign,
  Cloud,
  Loader,
} from "lucide-react";
import { supabase } from "../../utils/supabase";

interface Purchase {
  id: string;
  user_id: string | null;
  email: string;
  platform: string;
  platform_transaction_id: string;
  product_name: string;
  product_sku: string | null;
  amount: number;
  currency: string;
  status: string;
  is_subscription: boolean;
  purchase_date: string;
  processed: boolean;
  created_at: string;
}

interface Product {
  id: string;
  name: string;
  slug: string;
  sku: string | null;
}

const AdminPurchasesManagement: React.FC = () => {
  const [purchases, setPurchases] = useState<Purchase[]>([]);
  const [allPurchases, setAllPurchases] = useState<Purchase[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedPlatform, setSelectedPlatform] = useState<string>("all");
  const [selectedStatus, setSelectedStatus] = useState<string>("all");
  const [showPlatformDropdown, setShowPlatformDropdown] = useState(false);
  const [showStatusDropdown, setShowStatusDropdown] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState<{
    show: boolean;
    purchase: Purchase | null;
  }>({ show: false, purchase: null });

  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);
  const [importData, setImportData] = useState("");
  const [syncing, setSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<any>(null);
  const [showSyncModal, setShowSyncModal] = useState(false);

  const clearMessages = useCallback(() => {
    setError(null);
    setSuccess(null);
  }, []);

  const filteredPurchases = useMemo(() => {
    let filtered = allPurchases;

    if (selectedPlatform !== "all") {
      filtered = filtered.filter((p) => p.platform === selectedPlatform);
    }

    if (selectedStatus !== "all") {
      filtered = filtered.filter((p) => p.status === selectedStatus);
    }

    return filtered;
  }, [allPurchases, selectedPlatform, selectedStatus]);

  useEffect(() => {
    fetchPurchases();
    fetchProducts();
  }, []);

  useEffect(() => {
    setPurchases(filteredPurchases);
  }, [filteredPurchases]);

  const fetchPurchases = async () => {
    try {
      clearMessages();
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (sessionError || !session) {
        setError("Authentication required. Please log in again.");
        return;
      }
      const token = session.access_token;

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-purchases`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setAllPurchases(data.data || []);
      } else {
        setError(data.error || "Failed to load purchases");
      }
    } catch (error) {
      console.error("Error fetching purchases:", error);
      setError(
        "Failed to load purchases. Please check your connection and try again.",
      );
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      const token = localStorage.getItem("admin_token");
      if (!token) return;

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-products`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      if (!response.ok) return;

      const data = await response.json();
      if (data.success) {
        setProducts(data.data || []);
      }
    } catch (error) {
      console.error("Error fetching products:", error);
    }
  };

  const handleImport = async () => {
    if (!importData.trim()) {
      setError("Please enter purchase data");
      return;
    }

    setImporting(true);
    clearMessages();

    try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (sessionError || !session) {
        setError("Authentication required. Please log in again.");
        return;
      }
      const token = session.access_token;

      const lines = importData.trim().split("\n");
      const purchasesToImport = lines
        .map((line) => {
          const [email, productName, amount, platform, transactionId] = line
            .split(",")
            .map((s) => s.trim());
          return {
            email,
            productName,
            amount: parseFloat(amount) || 0,
            platform: platform || "manual",
            transactionId:
              transactionId || `manual-${Date.now()}-${Math.random()}`,
          };
        })
        .filter((p) => p.email && p.productName);

      if (purchasesToImport.length === 0) {
        setError(
          "No valid purchases found. Format: email,product_name,amount,platform,transaction_id",
        );
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-purchases/import`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ purchases: purchasesToImport }),
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setSuccess(`Successfully imported ${data.count} purchases`);
        setImportData("");
        setShowImportModal(false);
        await fetchPurchases();
      } else {
        setError(data.error || "Failed to import purchases");
      }
    } catch (error) {
      console.error("Error importing purchases:", error);
      setError("Failed to import purchases. Please try again.");
    } finally {
      setImporting(false);
    }
  };

  const downloadTemplate = () => {
    const csvContent =
      "email,product_name,amount,platform,transaction_id\nuser@example.com,AI Video Creator,99.00,stripe,txn_123456\nuser2@example.com,Landing Page Creator,49.00,paykickstart,pk_789012";
    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "purchases_template.csv";
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const exportPurchases = () => {
    const csvContent = [
      "Email,Product Name,Amount,Currency,Platform,Status,Purchase Date",
      ...filteredPurchases.map((p) =>
        [
          p.email,
          p.product_name,
          p.amount,
          p.currency,
          p.platform,
          p.status,
          new Date(p.purchase_date).toLocaleDateString(),
        ].join(","),
      ),
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `purchases_export_${new Date().toISOString().split("T")[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const getPlatformBadgeColor = (platform: string) => {
    switch (platform.toLowerCase()) {
      case "stripe":
        return "bg-blue-500/20 text-blue-400";
      case "paykickstart":
        return "bg-green-500/20 text-green-400";
      case "zaxxa":
        return "bg-purple-500/20 text-purple-400";
      default:
        return "bg-gray-500/20 text-gray-400";
    }
  };

  const getStatusBadgeColor = (status: string) => {
    switch (status.toLowerCase()) {
      case "completed":
        return "bg-green-500/20 text-green-400";
      case "pending":
        return "bg-yellow-500/20 text-yellow-400";
      case "refunded":
        return "bg-red-500/20 text-red-400";
      case "failed":
        return "bg-red-500/20 text-red-400";
      default:
        return "bg-gray-500/20 text-gray-400";
    }
  };

  const startStripeSync = async () => {
    setSyncing(true);
    clearMessages();

    try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (sessionError || !session) {
        setError("Authentication required. Please log in again.");
        return;
      }
      const token = session.access_token;

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/stripe-sync?action=start`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setSuccess("Stripe sync started! This may take several minutes...");
        setSyncStatus({ job_id: data.job_id, status: "running" });
        pollSyncStatus(data.job_id);
      } else {
        setError(data.error || "Failed to start Stripe sync");
      }
    } catch (error) {
      console.error("Error starting Stripe sync:", error);
      setError("Failed to start Stripe sync. Please try again.");
    } finally {
      setSyncing(false);
    }
  };

  const pollSyncStatus = async (jobId: string) => {
    const token = localStorage.getItem("admin_token");
    if (!token) return;

    const interval = setInterval(async () => {
      try {
        const response = await fetch(
          `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/stripe-sync?action=status&job_id=${jobId}`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          },
        );

        if (!response.ok) {
          clearInterval(interval);
          return;
        }

        const data = await response.json();
        if (data.success && data.job) {
          setSyncStatus(data.job);

          if (data.job.status === "completed") {
            clearInterval(interval);
            setSuccess(
              `Stripe sync completed! Imported ${data.job.successful_records} customers with ${data.job.failed_records} failures.`,
            );
            await fetchPurchases();
          } else if (data.job.status === "failed") {
            clearInterval(interval);
            setError("Stripe sync failed. Check the logs for details.");
          }
        }
      } catch (error) {
        console.error("Error polling sync status:", error);
        clearInterval(interval);
      }
    }, 3000);

    setTimeout(() => clearInterval(interval), 600000);
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center py-20">
        <div className="w-8 h-8 border-t-2 border-primary-500 border-solid rounded-full animate-spin"></div>
      </div>
    );
  }

  const stats = {
    total: allPurchases.length,
    revenue: allPurchases
      .filter((p) => p.status === "completed")
      .reduce((sum, p) => sum + p.amount, 0),
    stripe: allPurchases.filter((p) => p.platform === "stripe").length,
    paykickstart: allPurchases.filter((p) => p.platform === "paykickstart")
      .length,
    zaxxa: allPurchases.filter((p) => p.platform === "zaxxa").length,
  };

  return (
    <div className="space-y-6">
      {error && (
        <div className="bg-red-500/20 border border-red-500/50 text-red-400 p-4 rounded-lg flex items-center justify-between">
          <div className="flex items-center">
            <AlertTriangle className="h-5 w-5 mr-2" />
            <span>{error}</span>
          </div>
          <button
            onClick={() => setError(null)}
            className="text-red-400 hover:text-red-300"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {success && (
        <div className="bg-green-500/20 border border-green-500/50 text-green-400 p-4 rounded-lg flex items-center justify-between">
          <div className="flex items-center">
            <CheckCircle className="h-5 w-5 mr-2" />
            <span>{success}</span>
          </div>
          <button
            onClick={() => setSuccess(null)}
            className="text-green-400 hover:text-green-300"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Total Purchases</p>
              <p className="text-2xl font-bold text-white">{stats.total}</p>
            </div>
            <ShoppingCart className="h-8 w-8 text-blue-400" />
          </div>
        </div>

        <div className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Total Revenue</p>
              <p className="text-2xl font-bold text-green-400">
                ${stats.revenue.toFixed(2)}
              </p>
            </div>
            <DollarSign className="h-8 w-8 text-green-400" />
          </div>
        </div>

        <div className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-4 border border-gray-700">
          <div className="flex items-center space-x-2">
            <div className="flex-1">
              <p className="text-xs text-gray-400">Stripe</p>
              <p className="text-lg font-bold text-blue-400">{stats.stripe}</p>
            </div>
            <div className="flex-1">
              <p className="text-xs text-gray-400">PayKickstart</p>
              <p className="text-lg font-bold text-green-400">
                {stats.paykickstart}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-gray-800/70 backdrop-blur-sm rounded-xl p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-400">Zaxxa</p>
              <p className="text-2xl font-bold text-purple-400">
                {stats.zaxxa}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Header with Filters */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">
            Purchases Management
          </h2>
          <p className="text-gray-400">
            View and manage all purchases across platforms
          </p>
        </div>
        <div className="flex items-center space-x-4">
          {/* Platform Filter */}
          <div className="relative">
            <button
              onClick={() => setShowPlatformDropdown(!showPlatformDropdown)}
              className="bg-gray-800 hover:bg-gray-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors border border-gray-600"
            >
              <span className="mr-2">
                {selectedPlatform === "all"
                  ? "All Platforms"
                  : selectedPlatform}
              </span>
              <ChevronDown className="h-4 w-4" />
            </button>

            {showPlatformDropdown && (
              <div className="absolute right-0 mt-2 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-lg z-10">
                <div className="py-1">
                  {["all", "stripe", "paykickstart", "zaxxa"].map(
                    (platform) => (
                      <button
                        key={platform}
                        onClick={() => {
                          setSelectedPlatform(platform);
                          setShowPlatformDropdown(false);
                        }}
                        className="w-full text-left px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                      >
                        {platform === "all"
                          ? "All Platforms"
                          : platform.charAt(0).toUpperCase() +
                            platform.slice(1)}
                      </button>
                    ),
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Status Filter */}
          <div className="relative">
            <button
              onClick={() => setShowStatusDropdown(!showStatusDropdown)}
              className="bg-gray-800 hover:bg-gray-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors border border-gray-600"
            >
              <span className="mr-2">
                {selectedStatus === "all" ? "All Status" : selectedStatus}
              </span>
              <ChevronDown className="h-4 w-4" />
            </button>

            {showStatusDropdown && (
              <div className="absolute right-0 mt-2 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-lg z-10">
                <div className="py-1">
                  {["all", "completed", "pending", "refunded", "failed"].map(
                    (status) => (
                      <button
                        key={status}
                        onClick={() => {
                          setSelectedStatus(status);
                          setShowStatusDropdown(false);
                        }}
                        className="w-full text-left px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                      >
                        {status === "all"
                          ? "All Status"
                          : status.charAt(0).toUpperCase() + status.slice(1)}
                      </button>
                    ),
                  )}
                </div>
              </div>
            )}
          </div>

          <button
            onClick={exportPurchases}
            className="bg-gray-700 hover:bg-gray-600 text-white px-4 py-2 rounded-lg flex items-center transition-colors"
          >
            <Download className="h-4 w-4 mr-2" />
            Export
          </button>

          <button
            onClick={downloadTemplate}
            className="bg-gray-700 hover:bg-gray-600 text-white px-4 py-2 rounded-lg flex items-center transition-colors"
          >
            <Download className="h-4 w-4 mr-2" />
            Template
          </button>

          <button
            onClick={() => setShowImportModal(true)}
            className="bg-primary-600 hover:bg-primary-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors"
          >
            <Upload className="h-4 w-4 mr-2" />
            Import
          </button>

          <button
            onClick={startStripeSync}
            disabled={syncing}
            className="bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {syncing ? (
              <Loader className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <Cloud className="h-4 w-4 mr-2" />
            )}
            {syncing ? "Syncing..." : "Sync Stripe"}
          </button>

          <button
            onClick={fetchPurchases}
            className="bg-primary-600 hover:bg-primary-700 text-white px-4 py-2 rounded-lg flex items-center transition-colors"
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Refresh
          </button>
        </div>
      </div>

      {/* Sync Status Banner */}
      {syncStatus && syncStatus.status === "running" && (
        <div className="bg-purple-500/20 border border-purple-500/50 text-purple-400 p-4 rounded-lg flex items-center justify-between">
          <div className="flex items-center">
            <Loader className="h-5 w-5 mr-2 animate-spin" />
            <div>
              <p className="font-semibold">Stripe Sync in Progress</p>
              <p className="text-sm">
                Processed: {syncStatus.processed_records || 0} /{" "}
                {syncStatus.total_records || "?"} customers (Success:{" "}
                {syncStatus.successful_records || 0}, Failed:{" "}
                {syncStatus.failed_records || 0})
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Purchases List */}
