/**
 * Research Planner AI — Production UI (Batch 5)
 * New VideoRemix Name: Research Planner AI
 * Creates complete research strategies, milestones, resource plans, and risk assessments.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Layers } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { StructuredResult } from "../../primitives/StructuredResult";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Input } from "../../../ui/input";
import { Label } from "../../../ui/label";

export default function ResearchPlannerAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [researchObjective, setResearchObjective] = useState("");
  const [availableResources, setAvailableResources] = useState("");
  const [timeline, setTimeline] = useState("4 weeks");
  const [teamExpertise, setTeamExpertise] = useState("");
  const [fileContent, setFileContent] = useState<string | null>(null);

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const handleRun = async () => {
    if (!researchObjective.trim()) return;

    const inputs = {
      researchObjective: researchObjective.trim(),
      availableResources: availableResources.trim() || undefined,
      timeline: timeline.trim(),
      teamExpertise: teamExpertise.trim() || undefined,
      additionalContext: fileContent || undefined,
    };

    await run(inputs);
  };

  const handleReset = () => reset();

  const handleClearAll = () => {
    setResearchObjective("");
    setAvailableResources("");
    setTimeline("4 weeks");
    setTeamExpertise("");
    setFileContent(null);
    reset();
  };

  return (
    <div className="space-y-8">
      <div>
        <div className="flex items-center gap-3">
          <Layers className="h-7 w-7 text-primary-500" />
          <h2 className="text-2xl font-semibold">{appName}</h2>
        </div>
        <p className="mt-2 text-gray-400">Designs rigorous research plans with methodology, search strategy, milestones, resource allocation, risk assessment, and expected outcomes.</p>
      </div>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Research Objective / Goal</Label>
            <PromptTextarea
              label=""
              placeholder="e.g. Understand the regulatory landscape for AI-generated content in the EU by Q3 2026"
              value={researchObjective}
              onChange={setResearchObjective}
              disabled={isRunning}
              maxLength={1800}
              rows={4}
              hint="Clear objective leads to a focused, executable plan."
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Available Resources</Label>
              <PromptTextarea
                label=""
                placeholder="Team size, budget, tools (e.g. 2 analysts, $5k budget, access to academic databases)"
                value={availableResources}
                onChange={setAvailableResources}
                disabled={isRunning}
                maxLength={1200}
                rows={3}
              />
            </div>

            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Timeline</Label>
              <Input
                value={timeline}
                onChange={(e) => setTimeline(e.target.value)}
                placeholder="e.g. 3 weeks, 2 months"
                disabled={isRunning}
                className="bg-black border-gray-700 text-white"
              />
              <p className="text-xs text-gray-500 mt-1.5">Helps create realistic milestones.</p>
            </div>
          </div>

          <PromptTextarea
            label="Team Expertise (optional)"
            placeholder="e.g. Strong in data analysis, limited legal background, one PhD in policy"
            value={teamExpertise}
            onChange={setTeamExpertise}
            disabled={isRunning}
            maxLength={800}
            rows={2}
            hint="The plan will account for skill gaps and suggest external help where needed."
          />

          <PromptTextarea
            label="Additional Constraints or Known Information"
            placeholder="Any fixed deadlines, must-use sources, or political sensitivities..."
            value={fileContent || ""}
            onChange={(v) => setFileContent(v)}
            disabled={isRunning}
            maxLength={2000}
            rows={3}
          />

          <Button
            onClick={handleRun}
            disabled={!researchObjective.trim() || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Designing research plan..." : "Run Research Planner AI"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <StructuredResult result={output} title="Research Plan" />
          <ResultActions
            onNew={handleReset}
            newLabel="New Plan"
            onClear={handleClearAll}
            clearLabel="Clear All"
          />
        </div>
      )}
    </div>
  );
}

/**
 * Newsletter Repurposer AI — Production UI
 * New VideoRemix Name: Newsletter Repurposer AI
 * Repurposes long-form newsletter/Substack content into bite-size social assets.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Mail, Hash, Linkedin, FileText, Share2, Megaphone } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";

interface RepurposedAsset {
  type: string;
  content: string;
  engagementHook?: string;
}

interface LinkedInSlide {
  slideNumber?: number;
  title?: string;
  content: string;
}

interface PromotionEmail {
  subject?: string;
  body?: string;
}

interface NewsletterOutput {
  keyInsights?: string[];
  repurposed?: RepurposedAsset[];
  threadVersion?: string;
  linkedInCarousel?: LinkedInSlide[];
  blogPostTitle?: string;
  blogPostOutline?: string;
  promotionEmail?: PromotionEmail;
}

const GOALS = [
  { id: "tweet", label: "Tweet", icon: Hash },
  { id: "linkedin", label: "LinkedIn", icon: Linkedin },
  { id: "blog", label: "Blog Excerpt", icon: FileText },
  { id: "email", label: "Email Promotion", icon: Mail },
  { id: "ad", label: "Ad Copy", icon: Megaphone },
  { id: "thread", label: "Thread Version", icon: Share2 },
];

export default function NewsletterRepurposerAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [newsletterText, setNewsletterText] = useState("");
  const [selectedGoals, setSelectedGoals] = useState<string[]>(["tweet", "linkedin", "thread"]);

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const toggleGoal = (goalId: string) => {
    setSelectedGoals((prev) =>
      prev.includes(goalId) ? prev.filter((g) => g !== goalId) : [...prev, goalId]
    );
  };

  const handleRun = async () => {
    if (!newsletterText.trim()) return;
    if (newsletterText.length > 10000) return;
    const inputs = {
      newsletterText: newsletterText.trim(),
      primaryGoals: selectedGoals.join(","),
    };
    await run(inputs);
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Mail className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">
        Turn your newsletter or Substack post into bite-size content for every platform.
      </p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <PromptTextarea
            label="Newsletter or Substack Text"
            placeholder="Paste your full newsletter or Substack article here..."
            value={newsletterText}
            onChange={setNewsletterText}
            disabled={isRunning}
            maxLength={10000}
            rows={12}
            hint="Paste the complete newsletter content for best results."
          />

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-3 block">Primary Goals</Label>
            <div className="flex flex-wrap gap-2">
              {GOALS.map(({ id, label, icon: Icon }) => {
                const isSelected = selectedGoals.includes(id);
                return (
                  <button
                    key={id}
                    type="button"
                    onClick={() => toggleGoal(id)}
                    disabled={isRunning}
                    className={`flex items-center gap-2 rounded-full px-4 py-2 text-sm font-medium transition-colors ${
                      isSelected
                        ? "bg-primary-600 text-white"
                        : "bg-[#0f0f0f] border border-gray-700 text-gray-300 hover:border-gray-500"
                    }`}
                  >
                    <Icon className="h-4 w-4" />
                    {label}
                  </button>
                );
              })}
            </div>
          </div>

          <Button
            onClick={handleRun}
            disabled={!newsletterText.trim() || selectedGoals.length === 0 || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Repurposing your content..." : "Run Newsletter Repurposer AI"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <NewsletterResult output={output} />
          <ResultActions onNew={() => reset()} newLabel="New Run" />
        </div>
      )}
    </div>
  );
}

function NewsletterResult({ output }: { output: NewsletterOutput }) {
  const { keyInsights, repurposed, threadVersion, linkedInCarousel, blogPostTitle, blogPostOutline, promotionEmail } = output;

  return (
    <div className="space-y-6">
      {/* Key Insights */}
      {keyInsights && keyInsights.length > 0 && (
        <div className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-6">
          <h3 className="text-lg font-semibold text-white mb-4">Key Insights</h3>
          <ol className="space-y-3">
            {keyInsights.map((insight: string, i: number) => (
              <li key={i} className="flex gap-3">
                <span className="flex-shrink-0 flex h-6 w-6 items-center justify-center rounded-full bg-primary-600 text-sm font-bold text-white">
                  {i + 1}
                </span>
                <span className="text-gray-200">{insight}</span>
              </li>
            ))}
          </ol>
        </div>
      )}

      {/* Repurposed Assets */}
      {repurposed && repurposed.length > 0 && (
        <div className="space-y-4">
          <h3 className="text-lg font-semibold text-white">Repurposed Assets</h3>
          {repurposed.map((asset: { type: string; content: string; engagementHook?: string }, i: number) => {
            const Icon = GOALS.find((g) => g.id === asset.type)?.icon || FileText;
            return (
              <div key={i} className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-5">
                <div className="flex items-center gap-2 mb-3">
                  <Icon className="h-5 w-5 text-primary-400" />
                  <span className="font-semibold capitalize text-primary-400">
                    {asset.type}
                  </span>
                </div>
                <p className="text-gray-200 whitespace-pre-wrap text-sm leading-relaxed mb-3">
                  {asset.content}
                </p>
                {asset.engagementHook && (
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-gray-500">Engagement Hook:</span>
                    <span className="text-sm text-primary-300">{asset.engagementHook}</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Thread Version */}
      {threadVersion && (
        <div className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-6">
          <div className="flex items-center gap-2 mb-4">
            <Share2 className="h-5 w-5 text-primary-400" />
            <h3 className="text-lg font-semibold text-white">Thread Version</h3>
          </div>
          <div className="space-y-4">
            {threadVersion.split("\n").filter(Boolean).map((tweet: string, i: number) => (
              <div key={i} className="flex gap-3">
                <span className="flex-shrink-0 flex h-6 w-6 items-center justify-center rounded-full bg-gray-700 text-xs font-bold text-gray-300">
                  {i + 1}
                </span>
                <p className="text-gray-200 text-sm leading-relaxed">{tweet}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* LinkedIn Carousel */}
      {linkedInCarousel && linkedInCarousel.length > 0 && (
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Linkedin className="h-5 w-5 text-primary-400" />
            <h3 className="text-lg font-semibold text-white">LinkedIn Carousel</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {linkedInCarousel.map((slide: { title?: string; content: string }, i: number) => (
              <div key={i} className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-5">
                <div className="flex items-center gap-2 mb-3">
                  <span className="flex-shrink-0 flex h-6 w-6 items-center justify-center rounded-full bg-primary-600 text-sm font-bold text-white">
                    {i + 1}
                  </span>
                  {slide.title && (
                    <span className="font-semibold text-primary-400">{slide.title}</span>
                  )}
                </div>
                <p className="text-gray-200 text-sm leading-relaxed whitespace-pre-wrap">
                  {slide.content}
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Blog Post */}
      {(blogPostTitle || blogPostOutline) && (
        <div className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-6">
          <div className="flex items-center gap-2 mb-4">
            <FileText className="h-5 w-5 text-primary-400" />
            <h3 className="text-lg font-semibold text-white">Blog Post</h3>
          </div>
          {blogPostTitle && (
            <h4 className="text-xl font-semibold text-primary-300 mb-4">{blogPostTitle}</h4>
          )}
          {blogPostOutline && (
            <div className="space-y-2">
              {blogPostOutline.split("\n").filter(Boolean).map((line: string, i: number) => (
                <p key={i} className="text-gray-300 text-sm pl-4 border-l-2 border-primary-600">
                  {line}
                </p>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Promotion Email */}
      {promotionEmail && (
        <div className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-6">
          <div className="flex items-center gap-2 mb-4">
            <Mail className="h-5 w-5 text-primary-400" />
            <h3 className="text-lg font-semibold text-white">Promotion Email</h3>
          </div>
          {promotionEmail.subject && (
            <div className="mb-4">
              <span className="text-xs text-gray-500 uppercase tracking-wide">Subject:</span>
              <p className="text-lg font-semibold text-primary-300 mt-1">{promotionEmail.subject}</p>
            </div>
          )}
          {promotionEmail.body && (
            <div className="bg-black rounded-lg p-4">
              <p className="text-gray-200 whitespace-pre-wrap text-sm leading-relaxed">
                {promotionEmail.body}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * AI Tool Router — Production UI (Overflow App)
 * New VideoRemix Name: AI Tool Router
 * Analyzes your goal and routes you to the single best (or optimal combination of) internal AI apps + gives you the perfect prompt to paste.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Shuffle, Lightbulb } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { StructuredResult } from "../../primitives/StructuredResult";
import { ResultActions } from "../../primitives/ResultActions";
import { BasicFileUpload } from "../../primitives/BasicFileUpload";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";
import { PromptTextarea } from "../../primitives/PromptTextarea";

export default function AIToolRouter({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [goalDescription, setGoalDescription] = useState("");
  const [constraints, setConstraints] = useState("");
  const [fileContent, setFileContent] = useState<string | null>(null);

  const { run, isRunning, output, error, reset, lastInputs } = useRunAIApp(appId, {
    onResult,
    onError,
    onReset,
    enableMultiTurn: true,
  });

  useEffect(() => { onRunningChange?.(isRunning); }, [isRunning, onRunningChange]);

  const handleFile = (_file: File | null, content?: string) => {
    setFileContent(content || null);
  };

  const handleRun = async () => {
    if (!goalDescription.trim()) return;
    await run({
      goalDescription: goalDescription.trim(),
      constraints: constraints.trim(),
      fileContent: fileContent || "",
      goal: "Analyze the request and recommend the best internal AI ai-design-studio(s) from the 95-ai-design-studio suite with ready-to-paste prompts and routing logic",
    });
  };

  const handleReset = () => reset();

  const handleClearAll = () => {
    setGoalDescription("");
    setConstraints("");
    setFileContent(null);
    reset();
  };

  const quickChips = [
    "I need help with competitive research and then writing a sales email",
    "Turn this messy brief into a full project plan + code review",
    "Analyze this document and then create a Notion-ready summary + action tracker",
    "Research current market data and then produce a board-ready slide deck outline",
    "I have customer feedback — route to the best tools for insight extraction + response templates",
  ];

  const handleQuick = async (q: string) => {
    await run({ ...(lastInputs || {}), goalDescription: q });
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <div className="rounded-full bg-primary-500/10 p-2">
          <Shuffle className="h-6 w-6 text-primary-500" />
        </div>
        <div>
          <h2 className="text-2xl font-semibold">{appName}</h2>
          <p className="text-sm text-gray-400 -mt-0.5">The intelligent router for the entire 95-ai-design-studio Internal AI Suite</p>
        </div>
      </div>

      <p className="text-gray-400 max-w-3xl">
        Describe what you want to accomplish in plain English (or paste a brief/document). The router analyzes your goal against all 95 specialized AI apps and returns the optimal route — which ai-design-studio(s) to use, in what order, plus copy-paste ready prompts tailored to your exact request.
      </p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-1.5 block">What do you want to accomplish?</Label>
            <PromptTextarea
              value={goalDescription}
              onChange={setGoalDescription}
              placeholder="e.g. I need to research 3 competitors, write a differentiated sales email, and create a one-page battlecard..."
              disabled={isRunning}
              minRows={5}
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-1.5 block">Constraints, Tone, or Special Requirements (optional)</Label>
            <PromptTextarea
              value={constraints}
              onChange={setConstraints}
              placeholder="Must be under 200 words, professional but warm tone, include pricing comparison, etc."
              disabled={isRunning}
              minRows={2}
            />
          </div>

          <BasicFileUpload
            label="Upload context (brief, competitor PDF, customer email thread, etc.)"
            onFileSelect={handleFile}
            disabled={isRunning}
            accept=".pdf,.txt,.docx,.md,.png,.jpg"
          />

          <Button
            onClick={handleRun}
            disabled={!goalDescription.trim() || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 py-6 text-lg"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Lightbulb className="mr-2 h-5 w-5" />}
            {isRunning ? "Routing to the best tools..." : "Route My Request"}
          </Button>

          <p className="text-xs text-gray-500">Multi-turn enabled — refine the goal and it will re-route or improve the recommended prompts.</p>
        </div>
      ) : (
        <div className="space-y-6">
          <StructuredResult result={output} title="Recommended Routing & Ready-to-Use Prompts" />

          <div className="flex flex-wrap gap-2">
            {quickChips.map((chip, i) => (
              <button
                key={i}
                onClick={() => handleQuick(chip)}
                disabled={isRunning}
                className="text-xs px-3 py-1.5 rounded-full border border-gray-700 hover:bg-gray-800 text-gray-300 disabled:opacity-50"
              >
                {chip}
              </button>
            ))}
          </div>

          <ResultActions onNew={handleReset} newLabel="Route Another Request" onClear={handleClearAll} clearLabel="Clear & Start Fresh" />
        </div>
      )}
    </div>
  );
}

/**
 * Smart Search AI — Production UI
