  };

  const handleRun = async () => {
    const content = (blogContent || fileContent || "").trim();
    if (!content) return;
    const inputs = {
      blogContent: content,
      targetDuration: parseInt(targetDuration, 10),
      style,
      audience: audience.trim() || "general business audience",
