/**
 * AI Dictation Assistant — Production UI
 * New VideoRemix Name: AI Dictation Assistant
 * Turns spoken ideas, notes, or dictation into organized text, summaries, emails, and documents.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Mic, MessageSquare } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { StructuredResult } from "../../primitives/StructuredResult";
import { BasicFileUpload } from "../../primitives/BasicFileUpload";
import { ResultActions } from "../../primitives/ResultActions";
import { RealtimeVoiceSession } from "../../primitives/RealtimeVoiceSession";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";

export default function AIDictationAssistant({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [dictationContent, setDictationContent] = useState("");
  const [outputFormat, setOutputFormat] = useState("organized_text");
  const [tone, setTone] = useState("professional");
  const [fileContent, setFileContent] = useState<string | null>(null);

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const outputFormats = [
    { value: "organized_text", label: "Organized Text Document" },
    { value: "summary", label: "Executive Summary" },
    { value: "email", label: "Professional Email" },
    { value: "meeting_notes", label: "Meeting Notes Format" },
    { value: "report", label: "Full Report / Document" },
  ];

  const tones = [
    { value: "professional", label: "Professional" },
    { value: "casual", label: "Casual & Conversational" },
    { value: "persuasive", label: "Persuasive & Engaging" },
    { value: "technical", label: "Technical & Detailed" },
    { value: "friendly", label: "Friendly & Warm" },
  ];

  const handleFile = (_file: File | null, content?: string) => {
    setFileContent(content || null);
    if (content) setDictationContent(content);
  };

  const handleRun = async () => {
    const content = (dictationContent || fileContent || "").trim();
    if (!content) return;
    const inputs = {
      spokenDictation: content,
      outputFormat,
      tone,
      goal: "Transform spoken ideas into polished, organized output",
    };
    await run(inputs);
  };

  const handleReset = () => reset();

  const handleClearAll = () => {
    setDictationContent("");
    setOutputFormat("organized_text");
    setTone("professional");
    setFileContent(null);
    reset();
  };

  const finalContent = dictationContent || fileContent || "";

  // === Voice + Text Mode Support ===
  const [mode, setMode] = useState<"text" | "voice">("text");

  const handleVoiceResult = (json: any) => {
    onResult?.(json);
  };

  const handleVoiceEnd = () => {};

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Mic className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Convert spoken ideas, voice notes, or raw dictation into polished text, summaries, emails, and documents.</p>

      {/* Mode Switch */}
      <div className="inline-flex rounded-xl border border-gray-800 bg-black/60 p-1">
        <button
          onClick={() => setMode("text")}
          className={`flex items-center gap-2 rounded-lg px-5 py-2 text-sm font-medium transition-all ${mode === "text" ? "bg-primary-600 text-white" : "text-gray-400 hover:text-white"}`}
        >
          <MessageSquare className="h-4 w-4" /> Text + Upload (Classic)
        </button>
        <button
          onClick={() => setMode("voice")}
          className={`flex items-center gap-2 rounded-lg px-5 py-2 text-sm font-medium transition-all ${mode === "voice" ? "bg-primary-600 text-white" : "text-gray-400 hover:text-white"}`}
        >
          <Mic className="h-4 w-4" /> Live Voice Dictation
        </button>
      </div>

      {/* LIVE VOICE MODE */}
      {mode === "voice" && !output && (
        <RealtimeVoiceSession
          appId={appId}
          voice="alloy"
          onStructuredResult={handleVoiceResult}
          onEnd={handleVoiceEnd}
        />
      )}

      {/* TEXT MODE (original) */}
      {mode === "text" && !output && (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Spoken Dictation / Notes</Label>
            <PromptTextarea
              label=""
              placeholder="Paste your spoken notes, transcription, or dictation here. Include all ideas, points, and details you want organized..."
              value={dictationContent}
              onChange={setDictationContent}
              disabled={isRunning}
              maxLength={5000}
              rows={8}
              hint="Include as much detail as possible for best results. Can include rough ideas, bullet points, or full transcription."
            />
          </div>

          <BasicFileUpload
            label="Or upload .txt / .md file (auto-fills content)"
            onFileSelect={handleFile}
            disabled={isRunning}
            accept=".txt,.md"
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Output Format</Label>
              <select
                value={outputFormat}
                onChange={(e) => setOutputFormat(e.target.value)}
                disabled={isRunning}
                className="w-full rounded-md border border-gray-700 bg-black px-3 py-2 text-white focus:border-primary-500"
              >
                {outputFormats.map((fmt) => (
                  <option key={fmt.value} value={fmt.value}>{fmt.label}</option>
                ))}
              </select>
            </div>
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Tone & Style</Label>
              <select
                value={tone}
                onChange={(e) => setTone(e.target.value)}
                disabled={isRunning}
                className="w-full rounded-md border border-gray-700 bg-black px-3 py-2 text-white focus:border-primary-500"
              >
                {tones.map((t) => (
                  <option key={t.value} value={t.value}>{t.label}</option>
                ))}
              </select>
            </div>
          </div>

          <Button
            onClick={handleRun}
            disabled={!finalContent.trim() || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Processing dictation..." : "Run AI Dictation Assistant"}
          </Button>
        </div>
      )}

      {/* SHARED RESULT (works for voice + text) */}
      {output && (
        <div className="space-y-6">
          <StructuredResult result={output} title="Dictation Output" />
          <ResultActions
            onNew={handleReset}
            newLabel="New Dictation"
            onClear={handleClearAll}
            clearLabel="Clear All"
          />
        </div>
      )}
    </div>
  );
}

/**
 * Fact Check AI — Production UI (Batch 5)
 * New VideoRemix Name: Fact Check AI
 * Verifies claims with evidence, sources, verdict, and related misinformation detection.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, ShieldCheck } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { StructuredResult } from "../../primitives/StructuredResult";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Input } from "../../../ui/input";
import { Label } from "../../../ui/label";

export default function FactCheckAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [claimToVerify, setClaimToVerify] = useState("");
  const [context, setContext] = useState("");
  const [urgency, setUrgency] = useState<"quick" | "standard" | "thorough">("standard");

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const handleRun = async () => {
    if (!claimToVerify.trim()) return;

    const inputs = {
      claimToVerify: claimToVerify.trim(),
      context: context.trim() || undefined,
      urgency,
    };

    await run(inputs);
  };

  const handleReset = () => reset();

  const handleClearAll = () => {
    setClaimToVerify("");
    setContext("");
    setUrgency("standard");
    reset();
  };

  return (
    <div className="space-y-8">
      <div>
        <div className="flex items-center gap-3">
          <ShieldCheck className="h-7 w-7 text-primary-500" />
          <h2 className="text-2xl font-semibold">{appName}</h2>
        </div>
        <p className="mt-2 text-gray-400">Real-time fact verification. Returns clear verdict, source-by-source evidence, detailed analysis, and detection of related misinformation using live web search.</p>
      </div>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Claim or Statement to Verify</Label>
            <PromptTextarea
              label=""
              placeholder="e.g. 'AI models will replace 80% of software engineers by 2028'"
              value={claimToVerify}
              onChange={setClaimToVerify}
              disabled={isRunning}
              maxLength={1200}
              rows={3}
              hint="Paste the exact claim. The more specific, the better."
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Context (where/when the claim was made)</Label>
            <Input
              value={context}
              onChange={(e) => setContext(e.target.value)}
              placeholder="e.g. Viral LinkedIn post by @username, March 2026"
              disabled={isRunning}
              className="bg-black border-gray-700 text-white"
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Verification Urgency</Label>
            <div className="flex gap-2">
              {(["quick", "standard", "thorough"] as const).map((u) => (
                <Button key={u} type="button" variant={urgency === u ? "default" : "outline"} onClick={() => setUrgency(u)} disabled={isRunning} className="flex-1 capitalize">
                  {u}
                </Button>
              ))}
            </div>
          </div>

          <Button
            onClick={handleRun}
            disabled={!claimToVerify.trim() || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Verifying claim against reliable sources..." : "Run Fact Check AI"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <StructuredResult result={output} title="Fact Check Report" />
          <ResultActions
            onNew={handleReset}
            newLabel="Check Another Claim"
            onClear={handleClearAll}
            clearLabel="Clear All"
          />
        </div>
      )}
    </div>
  );
}

/**
 * YouTube Repurposer AI — Production UI
 * New VideoRemix Name: YouTube Repurposer AI
 * Turn video transcript or description into 5+ repurposed assets for social, email, blog, and shorts.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Youtube } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";

interface Asset {
  format: string;
  title: string;
  content: string;
  cta?: string;
  charCount?: number;
}

interface ShortsIdea {
  timestamp: string;
  hook: string;
}

interface OutputShape {
  summary?: string;
  assets?: Asset[];
  shortsIdeas?: ShortsIdea[];
  blogOutline?: string;
  emailSubjectLines?: string[];
  crossPostTips?: string[];
}

const FORMAT_OPTIONS = [
  "Twitter/X Thread",
  "LinkedIn Post",
  "Blog Article",
  "Email Newsletter",
  "Shorts Script",
  "Instagram Caption",
];

const TONE_OPTIONS = ["Professional", "Casual", "Inspirational", "Humorous", "Educational"];

function formatBadgeColor(format: string): string {
  if (format.includes("Twitter")) return "bg-blue-600";
  if (format.includes("LinkedIn")) return "bg-sky-700";
  if (format.includes("Blog")) return "bg-emerald-700";
  if (format.includes("Email")) return "bg-violet-700";
  if (format.includes("Shorts")) return "bg-rose-700";
  if (format.includes("Instagram")) return "bg-pink-700";
  return "bg-gray-700";
}

export default function YouTubeRepurposerAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [transcript, setTranscript] = useState("");
  const [selectedFormats, setSelectedFormats] = useState<string[]>(["Twitter/X Thread", "LinkedIn Post"]);
  const [selectedTone, setSelectedTone] = useState("Professional");

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const toggleFormat = (format: string) => {
    setSelectedFormats(prev =>
      prev.includes(format) ? prev.filter(f => f !== format) : [...prev, format]
    );
  };

  const handleRun = async () => {
    if (!transcript.trim() || selectedFormats.length === 0) return;
    if (transcript.length > 10000) return;
    const inputs = {
      transcript: transcript.trim(),
      targetFormats: selectedFormats.join(","),
      tone: selectedTone,
    };
    await run(inputs);
  };

  const typedOutput = output as OutputShape | null;

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Youtube className="h-7 w-7 text-red-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Transform any YouTube video into 5+ optimized assets — threads, posts, emails, blogs, and shorts.</p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          {/* Transcript textarea */}
          <PromptTextarea
            label="Video Transcript or Description"
            placeholder="Paste your YouTube video transcript or description here..."
            value={transcript}
            onChange={setTranscript}
            disabled={isRunning}
            maxLength={10000}
            rows={10}
            hint="Include the full transcript or a detailed video description for best results."
          />

          {/* Target formats */}
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-3 block">Target Formats</Label>
            <div className="flex flex-wrap gap-2">
              {FORMAT_OPTIONS.map(format => {
                const isSelected = selectedFormats.includes(format);
                return (
                  <button
                    key={format}
                    type="button"
                    onClick={() => toggleFormat(format)}
                    disabled={isRunning}
                    className={`
                      px-4 py-2 rounded-full text-sm font-medium transition-all border
                      ${isSelected
                        ? "bg-primary-600 text-white border-primary-600"
                        : "bg-black text-gray-400 border-gray-700 hover:border-gray-500"
                      }
                      disabled:opacity-50
                    `}
                  >
                    {format}
                  </button>
                );
              })}
            </div>
            <p className="mt-2 text-xs text-gray-500">
              {selectedFormats.length === 0 ? "Select at least one format" : `${selectedFormats.length} format${selectedFormats.length > 1 ? "s" : ""} selected`}
            </p>
          </div>

          {/* Tone */}
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Tone</Label>
            <select
              value={selectedTone}
              onChange={e => setSelectedTone(e.target.value)}
              disabled={isRunning}
              className="w-full rounded-md border border-gray-700 bg-black px-3 py-2.5 text-white md:w-64"
            >
              {TONE_OPTIONS.map(t => (
                <option key={t}>{t}</option>
              ))}
            </select>
          </div>

          <Button
            onClick={handleRun}
            disabled={!transcript.trim() || selectedFormats.length === 0 || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Repurposing your video content..." : "Run YouTube Repurposer AI"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          {/* Summary card */}
          {typedOutput?.summary && (
            <div className="rounded-xl border border-yellow-600/30 bg-yellow-900/10 p-6">
              <h3 className="text-sm font-semibold text-yellow-400 uppercase tracking-wider mb-3">Key Insights Summary</h3>
              <p className="text-gray-200 leading-relaxed">{typedOutput.summary}</p>
            </div>
          )}

          {/* Assets */}
          {typedOutput?.assets && typedOutput.assets.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Repurposed Assets</h3>
              <div className="space-y-4">
                {typedOutput.assets.map((asset, i) => (
                  <div key={i} className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-5">
                    <div className="flex items-center justify-between mb-3">
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold text-white ${formatBadgeColor(asset.format)}`}>
                        {asset.format}
                      </span>
                      {asset.charCount && (
                        <span className="text-xs text-gray-500">{asset.charCount} chars</span>
                      )}
                    </div>
                    {asset.title && (
                      <h4 className="text-base font-semibold text-primary-400 mb-2">{asset.title}</h4>
                    )}
                    <p className="text-gray-300 text-sm leading-relaxed whitespace-pre-wrap">{asset.content}</p>
                    {asset.cta && (
                      <div className="mt-3 inline-block rounded bg-primary-900/40 px-3 py-1 text-xs text-primary-300 border border-primary-700/50">
                        CTA: {asset.cta}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Shorts Ideas */}
          {typedOutput?.shortsIdeas && typedOutput.shortsIdeas.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Shorts Ideas</h3>
              <div className="space-y-3">
                {typedOutput.shortsIdeas.map((idea, i) => (
                  <div key={i} className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-4 flex gap-4">
                    <span className="text-2xl font-bold text-primary-500">{i + 1}</span>
                    <div>
                      <span className="inline-block px-2 py-0.5 rounded bg-rose-900/40 text-rose-400 text-xs font-mono mb-2">
                        Hook {idea.timestamp}
                      </span>
                      <p className="text-gray-200 text-sm leading-relaxed">{idea.hook}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Blog Outline */}
          {typedOutput?.blogOutline && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Blog Article Outline</h3>
              <div className="rounded-xl border border-gray-800 bg-[#0a0a0a] p-5">
                <pre className="text-gray-300 text-sm whitespace-pre-wrap font-sans leading-relaxed">{typedOutput.blogOutline}</pre>
              </div>
            </div>
          )}

          {/* Email Subject Lines */}
          {typedOutput?.emailSubjectLines && typedOutput.emailSubjectLines.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Email Subject Lines</h3>
              <ol className="space-y-2">
                {typedOutput.emailSubjectLines.map((line, i) => (
                  <li key={i} className="flex items-start gap-3 rounded-lg border border-gray-800 bg-[#0a0a0a] p-4">
                    <span className="flex-shrink-0 w-6 h-6 rounded-full bg-violet-900/60 text-violet-300 text-xs font-bold flex items-center justify-center mt-0.5">
                      {i + 1}
                    </span>
                    <span className="text-gray-200 text-sm">{line}</span>
                  </li>
                ))}
              </ol>
            </div>
          )}

          {/* Cross-Post Tips */}
          {typedOutput?.crossPostTips && typedOutput.crossPostTips.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Cross-Post Tips</h3>
              <ul className="space-y-2">
                {typedOutput.crossPostTips.map((tip, i) => (
                  <li key={i} className="flex items-start gap-3 rounded-lg border border-gray-800 bg-[#0a0a0a] p-4">
                    <span className="flex-shrink-0 text-primary-500 mt-0.5">•</span>
                    <span className="text-gray-300 text-sm">{tip}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          <ResultActions onNew={() => reset()} newLabel="New Run" />
        </div>
      )}
    </div>
  );
}

/**
 * Landing Page Critic AI — Production UI
 * New VideoRemix Name: Landing Page Critic AI
 */

import React, { useState, useEffect } from "react";
import { Target, Users, Play, Loader2, TrendingUp, AlertTriangle, CheckCircle2, Lightbulb, ArrowRight, RefreshCw, Zap, LayoutGrid, Image as LucideImage } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { BasicFileUpload } from "../../primitives/BasicFileUpload";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";
import { Input } from "../../../ui/input";

export default function LandingPageCriticAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [landingPageUrl, setLandingPageUrl] = useState("");
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [screenshotName, setScreenshotName] = useState<string | null>(null);
  const [targetGoal, setTargetGoal] = useState<"conversion" | "signup" | "purchase">("conversion");
  const [targetAudience, setTargetAudience] = useState("");
  const [iterationPrompt, setIterationPrompt] = useState("");
  const [lastInputs, setLastInputs] = useState<Record<string, unknown> | null>(null);
  const [isImageLoading, setIsImageLoading] = useState(false);
  const [stickyScreenshot, setStickyScreenshot] = useState<string | null>(null);

  const { run, isRunning, output, reset, clearHistory } = useRunAIApp(appId, {
    enableMultiTurn: true,
    onResult,
    onError,
    onReset,
  });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const goalOptions = ["conversion", "signup", "purchase"] as const;
  const goalLabels: Record<typeof goalOptions[number], string> = {
    conversion: "Conversion (Sign up, Subscribe)",
    signup: "Sign Up (Account Creation)",
    purchase: "Purchase (E-commerce)",
  };

  const quickIterateOptions = [
    "Focus more on mobile UX",
    "Suggest bolder CTA improvements",
    "Deeper accessibility analysis",
    "Analyze above-the-fold section",
    "Focus on trust signals",
    "Critique the pricing layout",
  ];

  const handleScreenshot = (file: File | null) => {
    if (file) {
      setScreenshotName(file.name);
      setIsImageLoading(true);
      const reader = new FileReader();
      reader.onload = (e) => {
        const dataUrl = e.target?.result as string;
        setScreenshot(dataUrl);
        setIsImageLoading(false);
      };
      reader.onerror = () => {
        setIsImageLoading(false);
        setScreenshotName(null);
        setScreenshot(null);
      };
      reader.readAsDataURL(file);
    } else {
      setScreenshotName(null);
      setScreenshot(null);
      setIsImageLoading(false);
    }
  };

  const buildInputs = (extra?: Record<string, unknown>) => {
    const inputs: Record<string, unknown> = {
      targetGoal,
      targetAudience: targetAudience.trim(),
    };
    if (landingPageUrl.trim()) {
      inputs.landingPageUrl = landingPageUrl.trim();
    }
    if (screenshot) {
      inputs.screenshot = screenshot;
    }
    if (extra) {
      Object.assign(inputs, extra);
    }
    return inputs;
  };

  const handleRun = async () => {
    const hasUrl = landingPageUrl.trim().length > 0;
    const hasScreenshot = !!screenshot;
    if (!hasUrl && !hasScreenshot) return;

    const inputs = buildInputs();
    setLastInputs(inputs);
    setStickyScreenshot(screenshot || stickyScreenshot);
    await run(inputs);
  };

  const handleQuickIterate = async (instruction: string) => {
    const base = lastInputs || buildInputs();
    const iterInputs = { ...base, _iterationFocus: instruction };
    setLastInputs(iterInputs);
    await run(iterInputs);
  };

  const handleCustomIterate = async () => {
    if (!iterationPrompt.trim()) return;
    const base = lastInputs || buildInputs();
    const iterInputs = { ...base, _customFeedback: iterationPrompt.trim() };
    setLastInputs(iterInputs);
    setIterationPrompt("");
    await run(iterInputs);
  };

  const handleReset = () => {
    clearHistory();
    reset();
    setStickyScreenshot(null);
  };

  const handleClearAll = () => {
    setLandingPageUrl("");
    setScreenshot(null);
    setScreenshotName(null);
    setTargetGoal("conversion");
    setTargetAudience("");
    setIterationPrompt("");
    setLastInputs(null);
    setStickyScreenshot(null);
    setIsImageLoading(false);
    clearHistory();
    reset();
  };

  const getScoreColor = (score: number) => {
    if (score < 5) return "text-red-400";
    if (score < 7) return "text-yellow-400";
    return "text-green-400";
  };

  const getScoreTrackColor = (score: number) => {
    if (score < 5) return "bg-red-500";
    if (score < 7) return "bg-yellow-500";
    return "bg-green-500";
  };

  const getScoreBgColor = (score: number) => {
    if (score < 5) return "from-red-950/30 to-red-900/10";
    if (score < 7) return "from-yellow-950/30 to-yellow-900/10";
    return "from-green-950/30 to-green-900/10";
  };

  const renderScoreGauge = (score: number) => {
    const clampedScore = Math.max(1, Math.min(10, score));
    const percentage = (clampedScore / 10) * 100;

    return (
      <div className={`rounded-2xl bg-gradient-to-br ${getScoreBgColor(score)} border border-gray-800 p-8 text-center`}>
        <div className={`text-8xl font-bold ${getScoreColor(score)} mb-3`}>{score}</div>
        <div className="text-sm text-gray-400 mb-6">out of 10</div>
        <div className="h-3 w-full bg-gray-800 rounded-full overflow-hidden">
          <div
            className={`h-full rounded-full transition-all duration-1000 ${getScoreTrackColor(score)}`}
            style={{ width: `${percentage}%` }}
          />
        </div>
        <div className="flex justify-between text-xs text-gray-500 mt-2">
          <span>Poor</span>
          <span>Average</span>
          <span>Excellent</span>
        </div>
      </div>
    );
  };

  const renderListItem = (text: string, icon: React.ReactNode, colorClass: string) => (
    <li className="flex items-start gap-3 py-2">
      <span className={`mt-0.5 ${colorClass}`}>{icon}</span>
      <span className="text-gray-300 text-sm leading-relaxed">{text}</span>
    </li>
  );

  const renderAnalysisSection = (title: string, content: string | undefined, icon: React.ReactNode) => {
    if (!content) return null;
    return (
      <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
        <div className="flex items-center gap-2 mb-3">
          <span className="text-primary-400">{icon}</span>
          <h4 className="font-semibold text-white text-lg">{title}</h4>
        </div>
        <p className="text-gray-300 text-sm leading-relaxed whitespace-pre-wrap">{content}</p>
      </div>
    );
  };

  const hasInput = landingPageUrl.trim().length > 0 || !!screenshot;
  const canRun = hasInput && !isRunning && !isImageLoading;

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Target className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Analyze any landing page for UX, messaging, and conversion improvements. Supports URL analysis or screenshot upload with AI vision.</p>

      {!output ? (
        <div className="space-y-6 max-w-4xl">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Landing Page URL</Label>
              <Input
                value={landingPageUrl}
                onChange={(e) => setLandingPageUrl(e.target.value)}
                placeholder="https://example.com/landing"
                disabled={isRunning}
                className="bg-black border-gray-700 text-white"
              />
              <p className="text-xs text-gray-500 mt-1.5">AI will crawl and analyze the page</p>
            </div>
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Screenshot (alternative)</Label>
              <BasicFileUpload
                label=""
                onFileSelect={handleScreenshot}
                disabled={isRunning}
                accept=".png,.jpg,.jpeg,.webp"
                maxSizeMB={10}
              />
              {screenshotName && isImageLoading && (
                <div className="flex items-center gap-2 text-sm text-amber-400 mt-2">
                  <Loader2 className="h-4 w-4 animate-spin" /> Processing image...
                </div>
              )}
              {screenshotName && screenshot && !isImageLoading && (
                <div className="flex items-center gap-2 text-sm text-green-400 mt-2">
                  <LucideImage className="h-4 w-4" /> {screenshotName}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Target Goal</Label>
              <div className="flex flex-wrap gap-2">
                {goalOptions.map((g) => (
                  <button
                    key={g}
                    onClick={() => setTargetGoal(g)}
                    disabled={isRunning}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-all border ${targetGoal === g ? "bg-primary-600 text-white border-primary-500" : "bg-black border-gray-700 text-gray-300 hover:border-gray-500"}`}
                  >
                    {goalLabels[g]}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Target Audience</Label>
              <Input
                value={targetAudience}
                onChange={(e) => setTargetAudience(e.target.value)}
                placeholder="e.g. SaaS founders, e-commerce shoppers, B2B buyers"
                disabled={isRunning}
                className="bg-black border-gray-700 text-white"
              />
            </div>
          </div>

          <Button
            onClick={handleRun}
            disabled={!canRun}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Analyzing landing page..." : "Analyze Landing Page"}
          </Button>
          {!hasInput && (
            <p className="text-xs text-gray-500">Provide a URL or upload a screenshot to begin analysis</p>
          )}
        </div>
      ) : (
        <div className="space-y-6">
          {stickyScreenshot && (
            <div className="sticky top-4 z-10 mb-6">
              <div className="inline-flex items-center gap-3 rounded-xl border border-gray-700 bg-black/90 backdrop-blur px-4 py-2">
                <img src={stickyScreenshot} alt="Screenshot" className="h-12 w-auto rounded-lg object-contain border border-gray-700" />
                <span className="text-xs text-gray-400">Screenshot preserved for iterations</span>
                <button onClick={() => setStickyScreenshot(null)} className="text-gray-500 hover:text-white ml-2">
                  <RefreshCw className="h-4 w-4" />
                </button>
              </div>
            </div>
          )}

          <div className="rounded-2xl border border-gray-800 bg-[#0a0a0a] p-8 space-y-8">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Target className="h-6 w-6 text-primary-500" />
                <h3 className="text-2xl font-semibold text-white">Critique Results</h3>
              </div>
              <span className="text-xs text-gray-500">Vision + Web Search ready</span>
            </div>

            {output.overallScore !== undefined && renderScoreGauge(output.overallScore)}

            {(output.strengths?.length || output.weaknesses?.length) && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {output.strengths?.length > 0 && (
                  <div className="rounded-xl border border-green-900/50 bg-green-950/20 p-6">
                    <h4 className="font-semibold text-green-400 mb-4 flex items-center gap-2">
                      <CheckCircle2 className="h-5 w-5" /> What Works
                    </h4>
                    <ul className="space-y-2">
                      {output.strengths.map((s: string, i: number) => (
                        <li key={i} className="flex items-start gap-2 text-sm text-gray-300">
                          <ArrowRight className="h-4 w-4 text-green-400 mt-0.5 flex-shrink-0" />
                          {s}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
                {output.weaknesses?.length > 0 && (
                  <div className="rounded-xl border border-red-900/50 bg-red-950/20 p-6">
                    <h4 className="font-semibold text-red-400 mb-4 flex items-center gap-2">
                      <AlertTriangle className="h-5 w-5" /> Needs Improvement
                    </h4>
                    <ul className="space-y-2">
                      {output.weaknesses.map((w: string, i: number) => (
                        <li key={i} className="flex items-start gap-2 text-sm text-gray-300">
                          <ArrowRight className="h-4 w-4 text-red-400 mt-0.5 flex-shrink-0" />
                          {w}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            )}

            {(output.uxAnalysis || output.conversionAnalysis) && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {renderAnalysisSection("UX Analysis", output.uxAnalysis, <LayoutGrid className="h-5 w-5" />)}
                {renderAnalysisSection("Conversion Analysis", output.conversionAnalysis, <TrendingUp className="h-5 w-5" />)}
              </div>
            )}

            {output.specificRecommendations?.length > 0 && (
              <div>
                <h4 className="font-semibold text-primary-400 mb-4 text-lg flex items-center gap-2">
                  <Lightbulb className="h-5 w-5" /> Actionable Recommendations
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {output.specificRecommendations.map((rec: string, i: number) => (
                    <div key={i} className="rounded-xl border border-gray-800 bg-black p-5 hover:border-primary-600 transition-colors">
                      <div className="flex items-start gap-3">
                        <span className="flex-shrink-0 w-7 h-7 rounded-full bg-primary-600/20 text-primary-400 text-sm font-semibold flex items-center justify-center">
                          {i + 1}
                        </span>
                        <p className="text-sm text-gray-300 leading-relaxed">{rec}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {output.abTestIdeas?.length > 0 && (
              <div>
                <h4 className="font-semibold text-primary-400 mb-4 text-lg flex items-center gap-2">
                  <Zap className="h-5 w-5" /> A/B Test Ideas
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {output.abTestIdeas.map((idea: string, i: number) => (
                    <div key={i} className="rounded-xl border border-gray-700 bg-black/50 p-4 hover:border-amber-600 transition-colors">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-xs font-semibold text-amber-400 uppercase tracking-wide">Test {i + 1}</span>
                      </div>
                      <p className="text-sm text-gray-300 leading-relaxed">{idea}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="rounded-xl border border-gray-800 bg-black/30 p-6 space-y-4">
            <div className="flex items-center gap-2 text-primary-400">
              <Zap className="h-5 w-5" />
              <span className="font-semibold text-white">Quick Iterate</span>
              <span className="text-xs text-gray-500 ml-auto">Multi-turn context preserved</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {quickIterateOptions.map((inst, i) => (
                <Button
                  key={i}
                  variant="outline"
                  size="sm"
                  onClick={() => handleQuickIterate(inst)}
                  disabled={isRunning}
                  className="border-gray-700 hover:bg-primary-950 text-xs"
                >
                  {inst}
                </Button>
              ))}
            </div>
            <div className="flex flex-col sm:flex-row gap-3 pt-2">
              <Input
                value={iterationPrompt}
                onChange={(e) => setIterationPrompt(e.target.value)}
                placeholder="Custom feedback instruction (e.g. 'focus on trust signals and social proof')"
                disabled={isRunning}
                className="flex-1 bg-black border-gray-700 text-white"
              />
              <Button onClick={handleCustomIterate} disabled={!iterationPrompt.trim() || isRunning} className="self-end bg-primary-600 hover:bg-primary-500 px-8">
                Apply
              </Button>
            </div>
          </div>

          <ResultActions onNew={handleReset} newLabel="New Analysis" onClear={handleClearAll} clearLabel="Clear All" />
        </div>
      )}
    </div>
  );
}

