            <Label className="text-sm font-medium text-gray-300 mb-2 block">Course Topic / Title</Label>
            <PromptTextarea
              label=""
              placeholder="e.g. Building AI Agents for Customer Support Teams"
              value={courseTopic}
              onChange={setCourseTopic}
