  const [interviewType, setInterviewType] = useState<"screening" | "technical" | "behavioral" | "final">("technical");
  const [iterationPrompt, setIterationPrompt] = useState("");
  const [lastInputs, setLastInputs] = useState<Record<string, unknown> | null>(null);

  const { run, isRunning, output, reset, clearHistory } = useRunAIApp(appId, {
    enableMultiTurn: true,
    onResult,
    onError,
    onReset,
  });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const typeLabels: Record<typeof interviewType, string> = {
    screening: "Screening (Initial call)",
    technical: "Technical (Skills assessment)",
    behavioral: "Behavioral (Culture fit)",
    final: "Final (Leadership/Executive)",
  };

  const quickIterateOptions = [
    "Focus on strengths",
    "Highlight red flags",
    "Compare to requirements",
    "Cultural fit score",
    "Technical depth",
    "Follow-up questions",
  ];

  const buildInputs = (extra?: Record<string, unknown>) => {
    const inputs: Record<string, unknown> = {
      interviewNotes: interviewNotes.trim(),
      candidateResponses: candidateResponses.trim(),
      jobRequirements: jobRequirements.trim(),
      interviewType,
    };
    if (extra) Object.assign(inputs, extra);
    return inputs;
  };

  const handleRun = async () => {
    if (!interviewNotes.trim() || !candidateResponses.trim() || !jobRequirements.trim()) return;
    const inputs = buildInputs();
    setLastInputs(inputs);
    await run(inputs);
  };

  const handleQuickIterate = async (instruction: string) => {
    const base = lastInputs || buildInputs();
    const iterInputs = { ...base, _iterationFocus: instruction };
    setLastInputs(iterInputs);
    await run(iterInputs);
  };

  const handleCustomIterate = async () => {
    if (!iterationPrompt.trim()) return;
    const base = lastInputs || buildInputs();
    const iterInputs = { ...base, _customFeedback: iterationPrompt.trim() };
    setLastInputs(iterInputs);
    setIterationPrompt("");
    await run(iterInputs);
  };

  const handleReset = () => {
    clearHistory();
    reset();
  };

  const handleClearAll = () => {
    setInterviewNotes("");
    setCandidateResponses("");
    setJobRequirements("");
    setInterviewType("technical");
    setIterationPrompt("");
    setLastInputs(null);
    clearHistory();
    reset();
  };

  const renderSection = (title: string, content: unknown, icon: React.ReactNode, colorClass: string) => {
    if (!content) return null;
    return (
      <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
        <div className="flex items-center gap-2 mb-3">
          <span className={colorClass}>{icon}</span>
          <h4 className="font-semibold text-white text-lg">{title}</h4>
        </div>
        <div className="text-sm text-gray-300 leading-relaxed whitespace-pre-wrap">
          {typeof content === "string" ? content : JSON.stringify(content, null, 2)}
        </div>
      </div>
    );
  };

  const renderList = (title: string, items: unknown, icon: React.ReactNode, colorClass: string) => {
    if (!items || (Array.isArray(items) && items.length === 0)) return null;
    const itemArray = Array.isArray(items) ? items : [items];
    return (
      <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
        <div className="flex items-center gap-2 mb-4">
          <span className={colorClass}>{icon}</span>
          <h4 className="font-semibold text-white text-lg">{title}</h4>
        </div>
        <div className="space-y-3">
          {itemArray.map((item: unknown, i: number) => (
            <div key={i} className="flex items-start gap-3">
              <ArrowRight className={`h-4 w-4 ${colorClass} mt-0.5 flex-shrink-0`} />
              <span className="text-sm text-gray-300">
                {typeof item === "string" ? item : typeof item === "object" ? (item as Record<string, unknown>).text || (item as Record<string, unknown>).strength || JSON.stringify(item) : String(item)}
              </span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const renderRecommendation = (recommendation: unknown) => {
    if (!recommendation) return null;
    const rec = String(recommendation).toLowerCase();
    const isHire = rec.includes("hire") && !rec.includes("no hire");
    const isHold = rec.includes("hold");
    const bgClass = isHire ? "border-green-900/50 bg-green-950/20" : isHold ? "border-yellow-900/50 bg-yellow-950/20" : "border-red-900/50 bg-red-950/20";
    const textClass = isHire ? "text-green-400" : isHold ? "text-yellow-400" : "text-red-400";
    const icon = isHire ? <CheckCircle2 className="h-5 w-5" /> : isHold ? <Users className="h-5 w-5" /> : <AlertTriangle className="h-5 w-5" />;
    return (
      <div className={`rounded-xl border ${bgClass} p-6`}>
        <div className="flex items-center gap-2 mb-3">
          <span className={textClass}>{icon}</span>
          <h4 className={`font-semibold text-lg ${textClass}`}>Overall Recommendation</h4>
        </div>
        <p className="text-sm text-gray-200 whitespace-pre-wrap">{typeof recommendation === "string" ? recommendation : JSON.stringify(recommendation, null, 2)}</p>
      </div>
    );
  };

  const renderScoreCard = (scoreCard: unknown) => {
    if (!scoreCard || typeof scoreCard !== "object") return null;
    const scores = scoreCard as Record<string, unknown>;
    return (
      <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
        <h4 className="font-semibold text-primary-400 mb-4 flex items-center gap-2">
          <ClipboardCheck className="h-5 w-5" /> Score Card
        </h4>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          {Object.entries(scores).map(([key, value]) => {
            const numVal = typeof value === "number" ? value : parseFloat(String(value));
            const isNum = !isNaN(numVal);
            const colorClass = isNum ? (numVal >= 7 ? "text-green-400" : numVal >= 4 ? "text-yellow-400" : "text-red-400") : "text-gray-300";
            return (
              <div key={key} className="text-center p-3 rounded-lg bg-black/50 border border-gray-800">
                <div className={`text-2xl font-bold ${colorClass}`}>{isNum ? numVal.toFixed(1) : String(value)}</div>
                <div className="text-xs text-gray-500 capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  const canRun = interviewNotes.trim().length > 0 && candidateResponses.trim().length > 0 && jobRequirements.trim().length > 0 && !isRunning;

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <ClipboardCheck className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Generate structured interview feedback with performance summaries, recommendations, and scorecards.</p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Interview Notes *</Label>
            <PromptTextarea
              label=""
              placeholder="e.g. Candidate seemed nervous initially but warmed up. Struggled with system design but showed strong coding skills. Good communication throughout."
              value={interviewNotes}
              onChange={setInterviewNotes}
              disabled={isRunning}
              maxLength={2000}
              rows={5}
              hint="General observations about the candidate"
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Candidate Responses *</Label>
            <PromptTextarea
              label=""
              placeholder="e.g.\nQ: Tell me about a time you led a team through a difficult project.\nA: Discussed leading a re-platforming effort at previous company. Showed ownership but couldn't quantify the impact.\n\nQ: Design a URL shortener.\nA: Good understanding of hashing, discussed collisions, but struggled with scale considerations."
              value={candidateResponses}
              onChange={setCandidateResponses}
              disabled={isRunning}
              maxLength={2500}
              rows={8}
              hint="Key questions and how the candidate responded"
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Job Requirements *</Label>
            <PromptTextarea
              label=""
              placeholder="e.g. Senior React Developer needed. Must have: 5+ years experience, TypeScript proficiency, system design skills, experience leading a team of 3+, strong communication."
              value={jobRequirements}
              onChange={setJobRequirements}
              disabled={isRunning}
              maxLength={1000}
              rows={4}
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Interview Type</Label>
            <div className="flex flex-wrap gap-2">
              {(Object.keys(typeLabels) as Array<keyof typeof typeLabels>).map((t) => (
                <button
                  key={t}
                  onClick={() => setInterviewType(t)}
                  disabled={isRunning}
                  className={`px-4 py-2 rounded-full text-sm font-medium transition-all border ${interviewType === t ? "bg-primary-600 text-white border-primary-500" : "bg-black border-gray-700 text-gray-300 hover:border-gray-500"}`}
                >
                  {typeLabels[t]}
                </button>
              ))}
            </div>
          </div>

          <Button onClick={handleRun} disabled={!canRun} className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6">
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Generating feedback..." : "Generate Interview Feedback"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="rounded-2xl border border-gray-800 bg-[#0a0a0a] p-8 space-y-8">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <ClipboardCheck className="h-6 w-6 text-primary-500" />
                <h3 className="text-2xl font-semibold text-white">Interview Feedback</h3>
              </div>
              <span className="text-xs text-gray-500">File Search + multi-turn ready</span>
            </div>

            {output.overallRecommendation && renderRecommendation(output.overallRecommendation)}

            {output.performanceSummary && renderSection("Performance Summary", output.performanceSummary, <ClipboardCheck className="h-5 w-5" />, "text-primary-400")}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {output.strengthsDemonstrated && renderList("Strengths", output.strengthsDemonstrated, <CheckCircle2 className="h-5 w-5" />, "text-green-400")}
              {output.gapsOrConcerns && renderList("Gaps & Concerns", output.gapsOrConcerns, <AlertTriangle className="h-5 w-5" />, "text-red-400")}
            </div>

            {output.skillsAssessment && renderSection("Skills Assessment vs Requirements", output.skillsAssessment, <ClipboardCheck className="h-5 w-5" />, "text-blue-400")}
            {output.culturalFit && renderSection("Cultural Fit", output.culturalFit, <Users className="h-5 w-5" />, "text-purple-400")}
            {output.followUpQuestions && renderList("Follow-Up Questions", output.followUpQuestions, <ArrowRight className="h-5 w-5" />, "text-amber-400")}
            {output.scoreCard && renderScoreCard(output.scoreCard)}

            {output && !output.performanceSummary && (
              <div className="text-sm text-gray-400 bg-black/50 p-8 rounded-xl border border-gray-800">
                <pre className="whitespace-pre-wrap text-xs text-gray-500">{JSON.stringify(output, null, 2)}</pre>
              </div>
            )}
          </div>

          <div className="rounded-xl border border-gray-800 bg-black/30 p-6 space-y-4">
            <div className="flex items-center gap-2 text-primary-400">
              <Zap className="h-5 w-5" />
              <span className="font-semibold text-white">Iterate on feedback</span>
              <span className="text-xs text-gray-500 ml-auto">Multi-turn context preserved</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {quickIterateOptions.map((inst, i) => (
                <Button key={i} variant="outline" size="sm" onClick={() => handleQuickIterate(inst)} disabled={isRunning} className="border-gray-700 hover:bg-primary-950 text-xs">
                  {inst}
                </Button>
              ))}
            </div>
            <div className="flex flex-col sm:flex-row gap-3 pt-2">
              <PromptTextarea
                label=""
                placeholder="Custom refinement (e.g. 'focus more on technical depth')"
                value={iterationPrompt}
                onChange={setIterationPrompt}
                disabled={isRunning}
                rows={2}
                maxLength={500}
                className="flex-1"
              />
              <Button onClick={handleCustomIterate} disabled={!iterationPrompt.trim() || isRunning} className="self-end bg-primary-600 hover:bg-primary-500 px-8">
                Apply
              </Button>
            </div>
          </div>

          <ResultActions onNew={handleReset} newLabel="New Feedback" onClear={handleClearAll} clearLabel="Clear All" />
        </div>
      )}
    </div>
  );
}

InterviewSummaryAI.displayName = "InterviewSummaryAI";

/**
 * AI Design Studio — Production UI
 * New VideoRemix Name: AI Design Studio
 */

import React, { useState, useEffect } from "react";
import { Palette, Image as LucideImage, Play, Loader2, Wand2 } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { BasicFileUpload } from "../../primitives/BasicFileUpload";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";
import { Input } from "../../../ui/input";

export default function AIDesignStudio({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [designGoal, setDesignGoal] = useState("");
  const [style, setStyle] = useState<"modern" | "minimalist" | "bold" | "playful">("modern");
  const [targetPlatform, setTargetPlatform] = useState<"web" | "mobile" | "both">("web");
  const [colorPreference, setColorPreference] = useState("");
  const [referenceImage, setReferenceImage] = useState<string | null>(null);
  const [refImageName, setRefImageName] = useState<string | null>(null);
  const [iterationPrompt, setIterationPrompt] = useState("");
  const [lastInputs, setLastInputs] = useState<Record<string, unknown> | null>(null);
  // isImageLoading guards against race condition: FileReader.readAsDataURL is async;
  // prevents Run button from being enabled (and clicked) before base64 referenceImage is populated in buildInputs.
  const [isImageLoading, setIsImageLoading] = useState(false);

  const { run, isRunning, output, reset, clearHistory } = useRunAIApp(appId, { 
    enableMultiTurn: true, 
    onResult, 
    onError, 
    onReset 
  });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const styleOptions = ["modern", "minimalist", "bold", "playful"] as const;
  const platformOptions = ["web", "mobile", "both"] as const;
  const colorSuggestions = ["#2563eb", "#10b981", "#f59e0b", "#ef4444", "monochrome", "pastel", "earth tones", "vibrant"];

  const handleReferenceImage = (file: File | null, _content?: string) => {
    if (file) {
      setRefImageName(file.name);
      setIsImageLoading(true);
      const reader = new FileReader();
      reader.onload = (e) => {
        const dataUrl = e.target?.result as string;
        setReferenceImage(dataUrl);
        setIsImageLoading(false);
      };
      reader.onerror = () => {
        setIsImageLoading(false);
        setRefImageName(null);
        setReferenceImage(null);
      };
      reader.readAsDataURL(file);
    } else {
      setRefImageName(null);
      setReferenceImage(null);
      setIsImageLoading(false);
    }
  };

  const buildInputs = (goal: string, extra?: Record<string, unknown>) => ({
    designGoal: goal.trim(),
    style,
    targetPlatform,
    colorPreference: colorPreference.trim() || "balanced modern palette with good contrast",
    ...(referenceImage ? { referenceImage } : {}),
    ...extra,
  });

  const handleRun = async () => {
    if (!designGoal.trim()) return;
    // Race closed: button is disabled while isImageLoading, so referenceImage (if any) is guaranteed to be set before buildInputs runs.
    const inputs = buildInputs(designGoal);
    setLastInputs(inputs);
    await run(inputs);
  };

  const handleQuickIterate = async (instruction: string) => {
    const base = lastInputs || buildInputs(designGoal || "Refine the previous design concept");
    const iterInputs = { ...base, designGoal: instruction, refinementRequest: instruction };
    setLastInputs(iterInputs as Record<string, unknown>);
    await run(iterInputs);
  };

  const handleCustomIterate = async () => {
    if (!iterationPrompt.trim()) return;
    const base = lastInputs || buildInputs(designGoal || "Apply refinement");
    const iterInputs = { ...base, designGoal: iterationPrompt.trim(), refinementRequest: iterationPrompt.trim() };
    setLastInputs(iterInputs as Record<string, unknown>);
    setIterationPrompt("");
    await run(iterInputs);
  };

  const handleReset = () => {
    clearHistory();
    reset();
  };

  const handleClearAll = () => {
    setDesignGoal("");
    setStyle("modern");
    setTargetPlatform("web");
    setColorPreference("");
    setReferenceImage(null);
    setRefImageName(null);
    setIterationPrompt("");
    setLastInputs(null);
    setIsImageLoading(false);
    clearHistory();
    reset();
  };

  const renderColorPalette = (palette: unknown) => {
    if (!palette) return null;
    let colors: Array<{ hex: string; usage?: string }> = [];
    if (Array.isArray(palette)) {
      colors = palette.map((c: unknown) => (typeof c === "string" ? { hex: c } : (c as { hex?: string; usage?: string })));
    } else if (typeof palette === "object") {
      colors = Object.entries(palette).map(([name, hex]) => ({ hex: String(hex), usage: name }));
    } else if (typeof palette === "string") {
      const matches = palette.match(/#[0-9a-fA-F]{6}/g) || [];
      colors = matches.map((h) => ({ hex: h }));
    }
    if (colors.length === 0) return <div className="text-gray-400 text-sm">{JSON.stringify(palette)}</div>;
    return (
      <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-3">
        {colors.slice(0, 6).map((c, i) => (
          <div key={i} className="group">
            <div
              className="w-full h-14 rounded-xl border border-gray-700 shadow-inner cursor-pointer transition-transform group-hover:scale-105"
              style={{ backgroundColor: c.hex }}
              onClick={() => navigator.clipboard.writeText(c.hex)}
              title={`Copy ${c.hex}`}
            />
            <div className="mt-1.5 text-[10px] font-mono text-gray-400 truncate">{c.hex}</div>
            {c.usage && <div className="text-[10px] text-gray-500 truncate">{c.usage}</div>}
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Palette className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Create stunning UI/UX designs, color systems, and component libraries. Upload reference images for moodboards or existing UIs. Supports multi-turn iteration ("more minimalist", "variations").</p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Design Goal *</Label>
            <PromptTextarea
              label=""
              placeholder="e.g. Design a clean investment dashboard for fintech SaaS users to track portfolios and receive AI insights"
              value={designGoal}
              onChange={setDesignGoal}
              disabled={isRunning}
              maxLength={2000}
              rows={5}
              hint="Describe the product, users, key screens and flows"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Visual Style</Label>
              <div className="flex flex-wrap gap-2">
                {styleOptions.map((s) => (
                  <button
                    key={s}
                    onClick={() => setStyle(s)}
                    disabled={isRunning}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-all border ${style === s ? "bg-primary-600 text-white border-primary-500" : "bg-black border-gray-700 text-gray-300 hover:border-gray-500"}`}
                  >
                    {s.charAt(0).toUpperCase() + s.slice(1)}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Target Platform</Label>
              <div className="flex flex-wrap gap-2">
                {platformOptions.map((p) => (
                  <button
                    key={p}
                    onClick={() => setTargetPlatform(p)}
                    disabled={isRunning}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-all border ${targetPlatform === p ? "bg-primary-600 text-white border-primary-500" : "bg-black border-gray-700 text-gray-300 hover:border-gray-500"}`}
                  >
                    {p === "web" ? "Web" : p === "mobile" ? "Mobile" : "Web + Mobile"}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Color Preference</Label>
            <Input
              value={colorPreference}
              onChange={(e) => setColorPreference(e.target.value)}
              placeholder="deep blues with energetic orange accents or 'soft pastels, high contrast'"
              disabled={isRunning}
              className="bg-black border-gray-700 text-white"
            />
            <div className="flex flex-wrap gap-2 mt-2">
              {colorSuggestions.map((c, idx) => (
                <button
                  key={idx}
                  onClick={() => setColorPreference(c)}
                  disabled={isRunning}
                  className="text-xs px-3 py-1 rounded-full border border-gray-700 hover:border-primary-500 text-gray-400 hover:text-white"
                  style={c.startsWith("#") ? { backgroundColor: c + "20", borderColor: c } : {}}
                >
                  {c}
                </button>
              ))}
            </div>
          </div>

          <BasicFileUpload
            label="Optional Reference Image (screenshot, moodboard, wireframe, existing UI)"
            onFileSelect={handleReferenceImage}
            disabled={isRunning}
            accept=".png,.jpg,.jpeg,.webp,.gif"
            maxSizeMB={5}
          />
          {refImageName && isImageLoading && (
            <div className="flex items-center gap-3 text-sm text-amber-400 -mt-2">
              <Loader2 className="h-4 w-4 animate-spin" /> Processing image for vision...
            </div>
          )}
          {refImageName && referenceImage && !isImageLoading && (
            <div className="flex items-center gap-3 text-sm text-green-400 -mt-2">
              <LucideImage className="h-4 w-4" /> {refImageName} — will be analyzed via vision
            </div>
          )}

          <Button
            onClick={handleRun}
            disabled={!designGoal.trim() || isRunning || isImageLoading}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Generating design concepts with vision..." : "Run AI Design Studio"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="rounded-2xl border border-gray-800 bg-[#0a0a0a] p-8 space-y-8">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Palette className="h-6 w-6 text-primary-500" />
                <h3 className="text-2xl font-semibold text-white">Design Output</h3>
              </div>
              <div className="text-xs text-gray-500">Vision + multi-turn ready</div>
            </div>

            <div>
              <h4 className="font-semibold text-primary-400 mb-2 text-lg">Design Concept</h4>
              <p className="text-lg leading-relaxed text-gray-200">{output.designConcept || output.concept || JSON.stringify(output)}</p>
            </div>

            {(output.colorPalette || output.colors || output.color) && (
              <div>
                <h4 className="font-semibold text-primary-400 mb-4 text-lg flex items-center gap-2">Color Palette</h4>
                {renderColorPalette(output.colorPalette || output.colors || output.color)}
              </div>
            )}

            {output.typography && (
              <div>
                <h4 className="font-semibold text-primary-400 mb-3 text-lg">Typography</h4>
                <div className="text-sm text-gray-200 bg-black/50 p-5 rounded-xl border border-gray-800 whitespace-pre-wrap">
