import { Play, Loader2, TrendingUp } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { StructuredResult } from "../../primitives/StructuredResult";
import { ResultActions } from "../../primitives/ResultActions";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { BasicFileUpload } from "../../primitives/BasicFileUpload";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";

export default function LocalBusinessAnalyticsAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [businessType, setBusinessType] = useState("restaurant");
  const [keyMetrics, setKeyMetrics] = useState("");
  const [timePeriod, setTimePeriod] = useState("month");
  const [analysisGoal, setAnalysisGoal] = useState("performance");
  const [uploadedFile, setUploadedFile] = useState<string | null>(null);
  const [isFileLoading, setIsFileLoading] = useState(false);

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset, enableMultiTurn: true });

  useEffect(() => { onRunningChange?.(isRunning); }, [isRunning, onRunningChange]);

  const handleFileUpload = (file: File | null) => {
    if (!file) return;
    setIsFileLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => { setUploadedFile(e.target?.result as string); setIsFileLoading(false); };
    reader.onerror = () => { setIsFileLoading(false); setUploadedFile(null); };
    reader.readAsDataURL(file);
  };

  const handleRun = async () => {
    if (!keyMetrics.trim() && !uploadedFile) return;
    await run({
      businessType,
      keyMetrics: keyMetrics.trim(),
      timePeriod,
      analysisGoal,
      fileData: uploadedFile,
    });
  };

  const handleReset = () => { reset(); setUploadedFile(null); };
  const handleClearAll = () => {
    setBusinessType("restaurant");
    setKeyMetrics("");
    setTimePeriod("month");
    setAnalysisGoal("performance");
    setUploadedFile(null);
    reset();
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <TrendingUp className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Get performance scores, trend analysis, peak times identification, customer insights, recommendations, and actionable next steps for your business.</p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Business Type</Label>
              <select value={businessType} onChange={e => setBusinessType(e.target.value)} disabled={isRunning} className="w-full rounded-md border border-gray-700 bg-black px-3 py-2 text-white">
                <option value="restaurant">Restaurant</option>
                <option value="retail">Retail</option>
                <option value="service">Service</option>
                <option value="healthcare">Healthcare</option>
                <option value="professional">Professional</option>
              </select>
            </div>
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Time Period</Label>
              <select value={timePeriod} onChange={e => setTimePeriod(e.target.value)} disabled={isRunning} className="w-full rounded-md border border-gray-700 bg-black px-3 py-2 text-white">
                <option value="week">Week</option>
                <option value="month">Month</option>
                <option value="quarter">Quarter</option>
                <option value="year">Year</option>
              </select>
            </div>
            <div>
              <Label className="text-sm font-medium text-gray-300 mb-2 block">Analysis Goal</Label>
              <select value={analysisGoal} onChange={e => setAnalysisGoal(e.target.value)} disabled={isRunning} className="w-full rounded-md border border-gray-700 bg-black px-3 py-2 text-white">
                <option value="performance">Performance Review</option>
                <option value="optimization">Optimization</option>
                <option value="forecasting">Forecasting</option>
              </select>
            </div>
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Upload Metrics Data (CSV/JSON)</Label>
            <BasicFileUpload onFileSelect={handleFileUpload} accept=".csv,.json" disabled={isRunning} />
            {uploadedFile && <p className="mt-2 text-sm text-green-400">File uploaded successfully</p>}
          </div>

          <PromptTextarea label="Key Metrics (or paste directly)" placeholder="Daily sales: $1200, $1450, $980... | Foot traffic: 45, 62, 38... | Average order: $32, $28, $41..." value={keyMetrics} onChange={setKeyMetrics} disabled={isRunning} rows={5} />

          <Button onClick={handleRun} disabled={(!keyMetrics.trim() && !uploadedFile) || isRunning} className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 py-6 text-lg">
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Analyzing data..." : "Run Local Business Analytics AI"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <StructuredResult result={output} title="Business Analytics Report" />
          <ResultActions onNew={handleReset} newLabel="New Analysis" onClear={handleClearAll} clearLabel="Clear All" />
        </div>
      )}
    </div>
  );
}

/**
 * Codebase Chat AI — Production UI
 * New VideoRemix Name: Codebase Chat AI
 * Chat with codebases, understand structure, and find relevant code snippets.
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Code2 } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { StructuredResult } from "../../primitives/StructuredResult";
import { BasicFileUpload } from "../../primitives/BasicFileUpload";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Input } from "../../../ui/input";
import { Label } from "../../../ui/label";

export default function CodebaseChatAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [codebaseDescription, setCodebaseDescription] = useState("");
  const [codeContent, setCodeContent] = useState("");
  const [query, setQuery] = useState("");
  const [language, setLanguage] = useState("general");
  const [fileContent, setFileContent] = useState<string | null>(null);

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const languages = ["general", "javascript", "typescript", "python", "rust", "go", "java", "csharp", "cpp", "ruby", "php"];

  const handleFile = (_file: File | null, content?: string) => {
    setFileContent(content || null);
    if (content) setCodeContent(content);
  };

  const handleRun = async () => {
    const content = (codeContent || fileContent || "").trim();
    if (!content && !codebaseDescription.trim()) return;
    const inputs = {
      codebaseDescription: codebaseDescription.trim(),
      codeContent: content,
      query: query.trim(),
      language,
      goal: "Provide code explanations and find relevant snippets",
    };
    await run(inputs);
  };

  const handleReset = () => reset();

  const handleClearAll = () => {
    setCodebaseDescription("");
    setCodeContent("");
    setQuery("");
    setLanguage("general");
    setFileContent(null);
    reset();
  };

  const hasContent = codebaseDescription.trim() || codeContent.trim() || fileContent;

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Code2 className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Upload code or describe your codebase, ask questions, and get instant explanations, structure analysis, and relevant code snippets.</p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Codebase Description</Label>
            <PromptTextarea
              label=""
              placeholder="Describe your codebase structure, purpose, tech stack, key modules, and what you're trying to understand or accomplish..."
              value={codebaseDescription}
              onChange={setCodebaseDescription}
              disabled={isRunning}
              maxLength={3000}
              rows={5}
              hint="Include tech stack, framework, key files/folders, and the overall architecture."
            />
          </div>

          <BasicFileUpload
            label="Upload code files (.txt, .js, .ts, .py, etc.)"
            onFileSelect={handleFile}
            disabled={isRunning}
            accept=".txt,.js,.ts,.jsx,.tsx,.py,.rb,.go,.java,.cs,.cpp,.c,.php,.md"
          />

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Code Content</Label>
            <PromptTextarea
              label=""
              placeholder="Paste code snippets, file contents, or specific sections you want analyzed..."
              value={codeContent}
              onChange={setCodeContent}
              disabled={isRunning}
              maxLength={6000}
              rows={10}
              hint="Paste specific code sections you need help understanding or finding patterns in."
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Programming Language</Label>
            <select
              value={language}
              onChange={(e) => setLanguage(e.target.value)}
              disabled={isRunning}
              className="w-full rounded-md border border-gray-700 bg-black px-3 py-2 text-white focus:border-primary-500"
            >
              {languages.map((lang) => <option key={lang} value={lang}>{lang.charAt(0).toUpperCase() + lang.slice(1)}</option>)}
            </select>
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Your Question / Query</Label>
            <Input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="e.g. How does the auth system work? Find all API endpoints. Explain this function..."
              disabled={isRunning}
              className="bg-black border-gray-700 text-white"
            />
          </div>

          <Button
            onClick={handleRun}
            disabled={!hasContent || isRunning}
            className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6"
          >
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Analyzing codebase..." : "Analyze Codebase"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <StructuredResult result={output} title="Codebase Analysis" />
          <ResultActions
            onNew={handleReset}
            newLabel="New Query"
            onClear={handleClearAll}
            clearLabel="Clear All"
          />
        </div>
      )}
    </div>
  );
}

/**
 * Resume Analyzer AI — Production UI
 * New VideoRemix Name: Resume Analyzer AI
 */

import React, { useState, useEffect } from "react";
import { FileText, Play, Loader2, ArrowRight, RefreshCw, Zap, CheckCircle2, AlertTriangle, TrendingUp } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Label } from "../../../ui/label";
import { Input } from "../../../ui/input";

export default function ResumeAnalyzerAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [resumeText, setResumeText] = useState("");
  const [jobTarget, setJobTarget] = useState("");
  const [experienceLevel, setExperienceLevel] = useState<"entry" | "mid" | "senior" | "executive">("mid");
  const [iterationPrompt, setIterationPrompt] = useState("");
  const [lastInputs, setLastInputs] = useState<Record<string, unknown> | null>(null);

  const { run, isRunning, output, reset, clearHistory } = useRunAIApp(appId, {
    enableMultiTurn: true,
    onResult,
    onError,
    onReset,
  });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const levelLabels: Record<typeof experienceLevel, string> = {
    entry: "Entry Level (0-2 years)",
    mid: "Mid Level (3-5 years)",
    senior: "Senior Level (5-10 years)",
    executive: "Executive (10+ years)",
  };

  const quickIterateOptions = [
    "Focus on technical skills",
    "ATS optimization tips",
    "Quantify achievements",
    "Leadership experience",
    "Education section",
    "Summary improvement",
  ];

  const buildInputs = (extra?: Record<string, unknown>) => {
    const inputs: Record<string, unknown> = {
      resumeText: resumeText.trim(),
      jobTarget: jobTarget.trim(),
      experienceLevel,
    };
    if (extra) Object.assign(inputs, extra);
    return inputs;
  };

  const handleRun = async () => {
    if (!resumeText.trim() || !jobTarget.trim()) return;
    const inputs = buildInputs();
    setLastInputs(inputs);
    await run(inputs);
  };

  const handleQuickIterate = async (instruction: string) => {
    const base = lastInputs || buildInputs();
    const iterInputs = { ...base, _iterationFocus: instruction };
    setLastInputs(iterInputs);
    await run(iterInputs);
  };

  const handleCustomIterate = async () => {
    if (!iterationPrompt.trim()) return;
    const base = lastInputs || buildInputs();
    const iterInputs = { ...base, _customFeedback: iterationPrompt.trim() };
    setLastInputs(iterInputs);
    setIterationPrompt("");
    await run(iterInputs);
  };

  const handleReset = () => {
    clearHistory();
    reset();
  };

  const handleClearAll = () => {
    setResumeText("");
    setJobTarget("");
    setExperienceLevel("mid");
    setIterationPrompt("");
    setLastInputs(null);
    clearHistory();
    reset();
  };

  const renderScoreGauge = (score: unknown, label: string, colorClass: string) => {
    if (score === undefined || score === null) return null;
    const numScore = typeof score === "number" ? score : parseFloat(String(score));
    if (isNaN(numScore)) return null;
    const bgClass = numScore >= 7 ? "text-green-400" : numScore >= 4 ? "text-yellow-400" : "text-red-400";
    const gaugeColor = numScore >= 7 ? "bg-green-500" : numScore >= 4 ? "bg-yellow-500" : "bg-red-500";
    const percentage = Math.min(100, (numScore / 10) * 100);
    return (
      <div className="rounded-xl border border-gray-800 bg-black/50 p-6 text-center">
        <div className={`text-5xl font-bold ${bgClass} mb-1`}>{numScore.toFixed(1)}</div>
        <div className="text-xs text-gray-400 mb-3">{label}</div>
        <div className="h-2 w-full bg-gray-800 rounded-full overflow-hidden">
          <div className={`h-full rounded-full ${gaugeColor}`} style={{ width: `${percentage}%` }} />
        </div>
      </div>
    );
  };

  const renderList = (title: string, items: unknown, icon: React.ReactNode, colorClass: string) => {
    if (!items || (Array.isArray(items) && items.length === 0)) return null;
    const itemArray = Array.isArray(items) ? items : [items];
    return (
      <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
        <div className="flex items-center gap-2 mb-4">
          <span className={colorClass}>{icon}</span>
          <h4 className="font-semibold text-white text-lg">{title}</h4>
        </div>
        <div className="space-y-3">
          {itemArray.map((item: unknown, i: number) => (
            <div key={i} className="flex items-start gap-3">
              <ArrowRight className={`h-4 w-4 ${colorClass} mt-0.5 flex-shrink-0`} />
              <span className="text-sm text-gray-300">
                {typeof item === "string" ? item : typeof item === "object" ? (item as Record<string, unknown>).text || (item as Record<string, unknown>).suggestion || JSON.stringify(item) : String(item)}
              </span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const canRun = resumeText.trim().length > 0 && jobTarget.trim().length > 0 && !isRunning;

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <FileText className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Analyze resumes and get actionable feedback on fit, ATS compatibility, and improvement suggestions.</p>

      {!output ? (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Resume Text *</Label>
            <PromptTextarea
              label=""
              placeholder="Paste your full resume here (or paste a job description below and enter your resume in the next field)..."
              value={resumeText}
              onChange={setResumeText}
              disabled={isRunning}
              maxLength={5000}
              rows={10}
              hint="Copy-paste your resume text. Include work history, skills, education."
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Target Position *</Label>
            <Input
              value={jobTarget}
              onChange={(e) => setJobTarget(e.target.value)}
              placeholder="e.g. Senior Frontend Engineer, Product Manager, Data Scientist"
              disabled={isRunning}
              className="bg-black border-gray-700 text-white"
            />
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Experience Level</Label>
            <div className="flex flex-wrap gap-2">
              {(Object.keys(levelLabels) as Array<keyof typeof levelLabels>).map((l) => (
                <button
                  key={l}
                  onClick={() => setExperienceLevel(l)}
                  disabled={isRunning}
                  className={`px-4 py-2 rounded-full text-sm font-medium transition-all border ${experienceLevel === l ? "bg-primary-600 text-white border-primary-500" : "bg-black border-gray-700 text-gray-300 hover:border-gray-500"}`}
                >
                  {levelLabels[l]}
                </button>
              ))}
            </div>
          </div>

          <Button onClick={handleRun} disabled={!canRun} className="w-full md:w-auto bg-primary-600 hover:bg-primary-500 text-lg py-6">
            {isRunning ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Play className="mr-2 h-5 w-5" />}
            {isRunning ? "Analyzing resume..." : "Analyze Resume"}
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="rounded-2xl border border-gray-800 bg-[#0a0a0a] p-8 space-y-8">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <FileText className="h-6 w-6 text-primary-500" />
                <h3 className="text-2xl font-semibold text-white">Analysis Results</h3>
              </div>
              <span className="text-xs text-gray-500">File Search + multi-turn ready</span>
            </div>

            {output.overallScore !== undefined && renderScoreGauge(output.overallScore, "Overall Resume Score", "text-primary-400")}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {output.strengths && renderList("Strengths", output.strengths, <CheckCircle2 className="h-5 w-5" />, "text-green-400")}
              {output.weaknesses && renderList("Areas to Improve", output.weaknesses, <AlertTriangle className="h-5 w-5" />, "text-red-400")}
            </div>

            {output.skillsMatch && (
              <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
                <div className="flex items-center gap-2 mb-4">
                  <TrendingUp className="h-5 w-5 text-blue-400" />
                  <h4 className="font-semibold text-white text-lg">Skills Match</h4>
                </div>
                <div className="text-sm text-gray-300 whitespace-pre-wrap">
                  {typeof output.skillsMatch === "string" ? output.skillsMatch : JSON.stringify(output.skillsMatch, null, 2)}
                </div>
              </div>
            )}

            {output.atsCompatibility !== undefined && (
              <div className="rounded-xl border border-blue-900/50 bg-blue-950/20 p-6 text-center">
                <div className="text-4xl font-bold text-blue-400 mb-1">{typeof output.atsCompatibility === "number" ? output.atsCompatibility.toFixed(0) : output.atsCompatibility}</div>
                <div className="text-xs text-gray-400">ATS Compatibility Score</div>
              </div>
            )}

            {output.specificImprovements && renderList("Actionable Improvements", output.specificImprovements, <ArrowRight className="h-5 w-5" />, "text-primary-400")}
            {output.coverLetterTips && (
              <div className="rounded-xl border border-gray-800 bg-black/50 p-6">
                <div className="flex items-center gap-2 mb-3">
                  <FileText className="h-5 w-5 text-amber-400" />
                  <h4 className="font-semibold text-amber-400 text-lg">Cover Letter Tips</h4>
                </div>
                <p className="text-sm text-gray-300 whitespace-pre-wrap">
                  {typeof output.coverLetterTips === "string" ? output.coverLetterTips : JSON.stringify(output.coverLetterTips, null, 2)}
                </p>
              </div>
            )}

            {output && output.overallScore === undefined && (
              <div className="text-sm text-gray-400 bg-black/50 p-8 rounded-xl border border-gray-800">
                <pre className="whitespace-pre-wrap text-xs text-gray-500">{JSON.stringify(output, null, 2)}</pre>
              </div>
            )}
          </div>

          <div className="rounded-xl border border-gray-800 bg-black/30 p-6 space-y-4">
            <div className="flex items-center gap-2 text-primary-400">
              <Zap className="h-5 w-5" />
              <span className="font-semibold text-white">Iterate on feedback</span>
              <span className="text-xs text-gray-500 ml-auto">Multi-turn context preserved</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {quickIterateOptions.map((inst, i) => (
                <Button key={i} variant="outline" size="sm" onClick={() => handleQuickIterate(inst)} disabled={isRunning} className="border-gray-700 hover:bg-primary-950 text-xs">
                  {inst}
                </Button>
              ))}
            </div>
            <div className="flex flex-col sm:flex-row gap-3 pt-2">
              <PromptTextarea
                label=""
                placeholder="Custom feedback request (e.g. 'focus on quantifying achievements')"
                value={iterationPrompt}
                onChange={setIterationPrompt}
                disabled={isRunning}
                rows={2}
                maxLength={500}
                className="flex-1"
              />
              <Button onClick={handleCustomIterate} disabled={!iterationPrompt.trim() || isRunning} className="self-end bg-primary-600 hover:bg-primary-500 px-8">
                Apply
              </Button>
            </div>
          </div>

          <ResultActions onNew={handleReset} newLabel="New Analysis" onClear={handleClearAll} clearLabel="Clear All" />
        </div>
      )}
    </div>
  );
}

ResumeAnalyzerAI.displayName = "ResumeAnalyzerAI";

/**
 * Lead Research Scraper AI — Production UI
 * New VideoRemix Name: Lead Research Scraper AI
 */

import React, { useState, useEffect } from "react";
import { Play, Loader2, Search } from "lucide-react";
import type { AIAppProps } from "../types";
import { useRunAIApp } from "../useRunAIApp";
import { PromptTextarea } from "../../primitives/PromptTextarea";
import { StructuredResult } from "../../primitives/StructuredResult";
import { ResultActions } from "../../primitives/ResultActions";
import { Button } from "../../../ui/button";
import { Input } from "../../../ui/input";
import { Label } from "../../../ui/label";

export default function LeadResearchScraperAI({ appId, appName, onResult, onError, onRunningChange, onReset }: AIAppProps) {
  const [keywords, setKeywords] = useState("");
  const [industry, setIndustry] = useState("SaaS");
  const [location, setLocation] = useState("");
  const [numLeads, setNumLeads] = useState(6);

  const { run, isRunning, output, error, reset } = useRunAIApp(appId, { onResult, onError, onReset });

  useEffect(() => {
    onRunningChange?.(isRunning);
  }, [isRunning, onRunningChange]);

  const industries = ["SaaS", "E-commerce", "Healthcare", "Fintech", "Marketing Agencies", "All"];

  const handleRun = async () => {
    if (!keywords.trim()) return;
    const inputs = {
      keywords: keywords.trim(),
      industry,
      location: location.trim() || "Global / US",
      targetCount: numLeads,
      sources: "LinkedIn, company sites, recent news, job boards",
    };
    await run(inputs);
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-3">
        <Search className="h-7 w-7 text-primary-500" />
        <h2 className="text-2xl font-semibold">{appName}</h2>
      </div>
      <p className="text-gray-400 -mt-4">Instantly scrape, qualify, and enrich high-intent leads from public signals and web data.</p>

