      {/* === TEXT MODE (original behavior preserved 100%) === */}
      {mode === "text" && !output && (
        <div className="space-y-6 max-w-3xl">
          <div>
            <Label className="text-sm font-medium text-gray-300 mb-2 block">Intake Requirements & Goals</Label>
