              a.href = url; a.download = `build-plan-${Date.now()}.json`; a.click();
            }}
          />
            <ResultActions
             onNew={handleReset}
             newLabel="New Plan"
             onClear={handleClearAll}
             clearLabel="Clear All"
           />
         </div>
       )}
     </div>
   );
 }

