interface AnimatedTestimonialCardProps {
  testimonials: Testimonial[];
  className?: string;
  autoPlay?: boolean;
  interval?: number;
}

const AnimatedTestimonialCard: React.FC<AnimatedTestimonialCardProps> = ({
  testimonials,
  className = '',
  autoPlay = true,
  interval = 6000,
}) => {
  const [activeIndex, setActiveIndex] = useState(0);
  const [direction, setDirection] = useState(0);

  const next = () => {
    setDirection(1);
    setActiveIndex((prev) => (prev + 1) % testimonials.length);
  };

  const prev = () => {
    setDirection(-1);
    setActiveIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
  };

  return (
    <div className={`relative ${className}`}>
      <AnimatePresence mode="wait">
        <motion.div
          key={activeIndex}
          initial={{ opacity: 0, x: direction * 100 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -direction * 100 }}
          transition={{ duration: 0.5 }}
          className="bg-gradient-to-br from-gray-800 to-gray-900 rounded-2xl p-8 border border-gray-700"
        >
          <Quote className="h-8 w-8 text-primary-500/30 mb-4" />
          <p className="text-xl text-white mb-6 italic">
            "{testimonials[activeIndex].quote}"
          </p>

          <div className="flex items-center mb-4">
            <img
              src={testimonials[activeIndex].image}
              alt={testimonials[activeIndex].name}
              className="w-12 h-12 rounded-full object-cover mr-4"
            />
            <div>
              <div className="text-white font-bold">{testimonials[activeIndex].name}</div>
              <div className="text-gray-400 text-sm">
                {testimonials[activeIndex].role}, {testimonials[activeIndex].company}
              </div>
            </div>
          </div>

          <div className="flex gap-1 mb-4">
            {[...Array(testimonials[activeIndex].rating)].map((_, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, scale: 0 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: i * 0.1 }}
              >
                <Star className="h-5 w-5 text-yellow-500 fill-yellow-500" />
              </motion.div>
            ))}
          </div>

          <div className="grid grid-cols-3 gap-4">
            {testimonials[activeIndex].metrics.map((metric, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 + i * 0.1 }}
                className="text-center bg-black/30 rounded-lg p-3"
              >
                <div className="text-lg font-bold text-primary-400">{metric.value}</div>
                <div className="text-xs text-gray-400">{metric.label}</div>
              </motion.div>
            ))}
          </div>
        </motion.div>
      </AnimatePresence>

      {/* Navigation */}
      <div className="flex justify-center gap-2 mt-6">
        {testimonials.map((_, i) => (
          <motion.button
            key={i}
            whileHover={{ scale: 1.2 }}
            whileTap={{ scale: 0.9 }}
            onClick={() => {
              setDirection(i > activeIndex ? 1 : -1);
              setActiveIndex(i);
            }}
            className={`w-2 h-2 rounded-full transition-all ${
              i === activeIndex ? 'w-8 bg-primary-500' : 'bg-gray-600'
            }`}
          />
        ))}
      </div>
    </div>
  );
};

export default AnimatedTestimonialCard;

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface TextRevealProps {
  text: string;
  className?: string;
  delay?: number;
  duration?: number;
  staggerChildren?: number;
  as?: keyof JSX.IntrinsicElements;
}

const TextReveal: React.FC<TextRevealProps> = ({
  text,
  className = '',
  delay = 0,
  duration = 0.05,
  staggerChildren = 0.03,
  as: Component = 'h2',
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => observer.disconnect();
  }, []);

  const words = text.split(' ');

  return (
    <div ref={ref}>
      <Component className={className}>
        <AnimatePresence>
          {words.map((word, wordIndex) => (
            <span key={wordIndex} className="inline-block">
              {word.split('').map((char, charIndex) => (
                <motion.span
                  key={`${wordIndex}-${charIndex}`}
                  initial={{ opacity: 0, y: 20, filter: 'blur(10px)' }}
                  animate={
                    isVisible
                      ? { opacity: 1, y: 0, filter: 'blur(0px)' }
                      : { opacity: 0, y: 20, filter: 'blur(10px)' }
                  }
                  transition={{
                    duration: duration * 10,
                    delay: delay + (wordIndex * staggerChildren * 10) + charIndex * 0.01,
                    ease: 'easeOut',
                  }}
                  className="inline-block"
                >
                  {char}
                </motion.span>
              ))}
              <span className="inline-block">&nbsp;</span>
            </span>
          ))}
        </AnimatePresence>
      </Component>
    </div>
  );
};

export default TextReveal;

import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';

interface AnimatedBorderGradientProps {
  children: React.ReactNode;
  className?: string;
  borderWidth?: number;
  duration?: number;
  colors?: string[];
}

const AnimatedBorderGradient: React.FC<AnimatedBorderGradientProps> = ({
  children,
  className = '',
  borderWidth = 2,
  duration = 3,
  colors = ['#6366f1', '#8b5cf6', '#a78bfa', '#c4b5fd'],
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isInView, setIsInView] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry.isIntersecting),
      { threshold: 0.1 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      className={`relative ${className}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {(isHovered || isInView) && (
        <motion.div
          className="absolute inset-0 rounded-inherit"
          style={{
            background: `conic-gradient(from 0deg, ${colors.join(', ')})`,
            padding: borderWidth,
          }}
          animate={{ rotate: 360 }}
          transition={{ duration, repeat: Infinity, ease: 'linear' }}
        >
          <div className="w-full h-full bg-gray-900 rounded-inherit" />
        </motion.div>
      )}
      <div className="relative z-10">{children}</div>
    </div>
  );
};

export default AnimatedBorderGradient;

import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';

interface FloatingIconProps {
  icon: React.ReactNode;
  className?: string;
  containerClassName?: string;
  speed?: number;
  amplitude?: number;
  delay?: number;
  mouseRepulsion?: boolean;
  onClick?: () => void;
  tooltip?: string;
}

const FloatingIcon: React.FC<FloatingIconProps> = ({
  icon,
  className = '',
  containerClassName = '',
  speed = 3,
  amplitude = 15,
  delay = 0,
  mouseRepulsion = true,
  onClick,
  tooltip,
}) => {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mouseRepulsion) return;

    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      setMousePosition({
        x: e.clientX - rect.left - rect.width / 2,
        y: e.clientY - rect.top - rect.height / 2,
      });
    };

    const container = containerRef.current;
    container?.addEventListener('mousemove', handleMouseMove);
    return () => container?.removeEventListener('mousemove', handleMouseMove);
  }, [mouseRepulsion]);

  const repulsionX = mouseRepulsion ? -mousePosition.x * 0.1 : 0;
  const repulsionY = mouseRepulsion ? -mousePosition.y * 0.1 : 0;

  return (
    <motion.div
      ref={containerRef}
      className={`relative ${containerClassName}`}
      initial={{ opacity: 0, scale: 0 }}
      animate={{
        opacity: 1,
        scale: 1,
        y: [0, -amplitude, 0],
      }}
      transition={{
        opacity: { duration: 0.5, delay },
        scale: { type: 'spring', stiffness: 260, damping: 20, delay },
        y: {
          duration: speed,
          repeat: Infinity,
          ease: 'easeInOut',
          delay,
        },
      }}
      whileHover={{
        scale: 1.2,
        transition: { type: 'spring', stiffness: 400, damping: 10 },
      }}
      onHoverStart={() => {
        if (onClick) onClick();
      }}
    >
      <motion.div
        animate={{
          x: repulsionX,
          y: repulsionY,
        }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        className={`p-3 rounded-xl bg-gradient-to-br from-gray-800/80 to-gray-900/80 backdrop-blur-sm border border-gray-700/50 cursor-pointer ${className}`}
        whileTap={{ scale: 0.9 }}
      >
        {icon}
      </motion.div>
      {tooltip && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          whileHover={{ opacity: 1, y: 0 }}
          className="absolute -bottom-8 left-1/2 -translate-x-1/2 whitespace-nowrap bg-gray-900 text-white text-xs px-2 py-1 rounded pointer-events-none"
        >
          {tooltip}
        </motion.div>
      )}
    </motion.div>
  );
};

export default FloatingIcon;

